INSERT OR REPLACE INTO academy_lessons (id, course_id, slug, title, body_md, est_minutes, source_clauses_json, source_pages_json, sort_order) VALUES ('lesson-4cf17e619f022d19', 'course-69a841a646a964cb', 'permit-004-l8', 'The top soil and vegetable', '### —

matter in all unexcavated areas under a

building shall be removed.  All stumps, roots and other wood debris shall be removed from the soil to a minimum depth of 300mm in unexcavated areas under a building.

