INSERT OR REPLACE INTO academy_lessons (id, course_id, slug, title, body_md, est_minutes, source_clauses_json, source_pages_json, sort_order) VALUES ('lesson-e2c8c23b6ba186b0', 'course-cd6d6a6a9f53f3f6', 'fire-006-l3', 'Section null', NULL, 10, '["GHBC-C-006678","GHBC-C-006679","GHBC-C-006680","GHBC-C-006681","GHBC-C-006682","GHBC-C-006700","GHBC-C-006701","GHBC-C-006702","GHBC-C-006703","GHBC-C-006704","GHBC-C-006705"]', '[1337,1338,1339,1340]', 2);
