INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c13201310a129c5a', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.9.2.1.1): “…buildings (that is, buildings that are more than ______ in height and for special buildings like educational, assembly______stitutional______dustrial, storage and hazardous and mixed occupancies having area more than……” — what value is stated?', '["30 m","15 m","7.5 m","22.7 m"]', 1, 'Clause 1.9.2.1.1 (GHBC-C-000074, page 118): (f) in the case of building plans for multi-storeyed/special buildings (that is, buildings that are more than 15m in height and for special buildings like educational, assembly, institutional, industrial, storage and hazardous and mixed occupancies having area more than 500m2), require the following additional information, as applicable;', 'standard', 'GHBC-C-000074', 'GHBC-REQ-000203', 118, '3b6b0916f978ff74a0c5572d648bcc35d66a572976dba78e1859e046534bc9d6', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-972851ed608a55e2', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.9.2.1.1): “…buildings (that is, buildings that are more than ______ in height and for special buildings like educational, assembly______stitutional______dustrial, storage and hazardous and mixed occupancies having area more than……” — what value is stated?', '["500 m2","250 m2","744 m2","1000 m2"]', 0, 'Clause 1.9.2.1.1 (GHBC-C-000074, page 118): (f) in the case of building plans for multi-storeyed/special buildings (that is, buildings that are more than 15m in height and for special buildings like educational, assembly, institutional, industrial, storage and hazardous and mixed occupancies having area more than 500m2), require the following additional information, as applicable;', 'standard', 'GHBC-C-000074', 'GHBC-REQ-000203', 118, '3b6b0916f978ff74a0c5572d648bcc35d66a572976dba78e1859e046534bc9d6', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-018bcce7e8f15adc', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.9.3.2): “…of which has been pursued in good faith within ______ after the effective date of this Code and has not been abandoned.…” — what value is stated?', '["180 days","90 days","30 days","28 days"]', 0, 'Clause 1.9.3.2 (GHBC-C-000084, page 120): This Code shall not require changes in the construction documents, construction or designated occupancy of a structure for which a lawful permit has been heretofore issued or otherwise lawfully authorized, and the construction of which has been pursued in good faith within 180 days after the effective date of this Code and has not been abandoned.', 'study', 'GHBC-C-000084', 'GHBC-REQ-000228', 120, 'e65440ac81a24a070eb79cc49ffa2657ea1cb7c88df80bf028ad70e04968633d', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6acd35009c25a82f', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.9.5): “…by the Head of Works for a period of not less than ______ from date of completion of the permitted work, or as required by this Code.…” — what value is stated?', '["30 days","28 days","180 days","90 days"]', 2, 'Clause 1.9.5 (GHBC-C-000089, page 121): One set of approved construction documents shall be retained by the Head of Works for a period of not less than 180 days from date of completion of the permitted work, or as required by this Code.', 'standard', 'GHBC-C-000089', 'GHBC-REQ-000241', 121, '15af9fe07d5c73cd61da17f2c93cf91071ee84cb11310aa25ff3dcfbeed19fdb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ce6302318d6fb74a', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.10.1): “…time of service, but shall not be permitted for more than ______.…” — what value is stated?', '["180 days","90 days","30 days","28 days"]', 0, 'Clause 1.10.1 (GHBC-C-000090, page 121): Such permits shall be limited as to time of service, but shall not be permitted for more than 180 days.', 'study', 'GHBC-C-000090', 'GHBC-REQ-000243', 121, '2bb1f1b61dc58df8b44253596be18d03c12e515fd49c243494d7133f54fcf37b', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6320a1739cf8c577', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.14.2): “…and the referenced Codes and standards set forth in Clause ______ case of emergency where necessary to eliminate an immediate hazard to life or property or where such utility…” — what value is stated?', '["0.625 in","2.1 in","3 in","1.4 in"]', 3, 'Clause 1.14.2 (GHBC-C-000121, page 124): The Head of Works shall have the authority to authorize disconnection of utility service to the building, structure or system regulated by this Code and the referenced Codes and standards set forth in Clause 1.1.4 in case of emergency where necessary to eliminate an immediate hazard to life or property or where such utility', 'standard', 'GHBC-C-000121', 'GHBC-REQ-000326', 124, 'ce31bef537143690919f7eb9298928d2b0dc984fb12cb5457d486b294560dcc1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-dddfc9a01f0f0917', NULL, NULL, 'threshold', 1, 'GS 1207:2018 Part 1 (Clause 1.15.4): “…The Board of Appeal shall consist of at least ______embers, each with a minimum of 15 years professional experience and good standing members of the Ghana Institute of Architects, Ghana Institute of Planners, Ghana……” — what value is stated?', '["13.8 m","7 m","3.5 m","10.2 m"]', 1, 'Clause 1.15.4 (GHBC-C-000126, page 125): The Board of Appeal shall consist of at least 7 members, each with a minimum of 15 years professional experience and good standing members of the Ghana Institute of Architects, Ghana Institute of Planners, Ghana Institution of Engineering and the Ghana Institution of Surveyors, plus other members', 'standard', 'GHBC-C-000126', 'GHBC-REQ-000337', 125, '2eb285bab8a4b77f48fa6662d16077efa9fa9de653851d59fa8a1e1577ee62b1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ab2bd70093c59135', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause AEROSOL CONTAINER): “…container up to a maximum size of 33.8 fluid ounces (______l), or a glass bottle up to a maximum size of 4 fluid ounces (______l), designed and intended to dispense an aerosol.…” — what value is stated?', '["1629 m","2018 m","1000 m","500 m"]', 2, 'Clause AEROSOL CONTAINER (GHBC-C-000155, page 127): A metal can or plastic container up to a maximum size of 33.8 fluid ounces (1000 ml), or a glass bottle up to a maximum size of 4 fluid ounces (118 ml), designed and intended to dispense an aerosol.', 'standard', 'GHBC-C-000155', 'GHBC-REQ-000383', 127, '2f70b9a148c62576d3904688f9c33d376fb6f4b0b0086da91ae8afb5bdbe679b', 'extracted', 1);
