INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-521f25c6d9523888', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause BARRICADE): “…An artificial mound or revetment a minimum thickness of ______.…” — what value is stated?', '["1829 mm","914 mm","457 mm","1372 mm"]', 1, 'Clause BARRICADE (GHBC-C-000194, page 129): An artificial mound or revetment a minimum thickness of 3 feet (914 mm).', 'study', 'GHBC-C-000194', 'GHBC-REQ-000453', 129, '3d10a57bc8160d88927bafed20860cbd21bdfeef7f6e06f870e59714e54df99b', 'requires_review', 0);
