INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-99a0cc9b7e482415', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause DAY BOX): “…constructed in accordance with the requirements for a Type ______agazine as defined and classified in Part 56 of the Ghana Fire Code.…” — what value is stated?', '["3 m","1.5 m","4.5 m","6 m"]', 0, 'Clause DAY BOX (GHBC-C-000261, page 134): A portable magazine designed to hold explosive materials constructed in accordance with the requirements for a Type 3 magazine as defined and classified in Part 56 of the Ghana Fire Code.', 'standard', 'GHBC-C-000261', 'GHBC-REQ-000627', 134, 'beb7cb1dffad904a4fec16ee2ff5d515fd59688bc5d581bfb89ce6c946e5fd3f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-efc24ed45bab9a96', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause MATERIALS): “…ceiling coverings, floor coverings, ordinary window shades______terior finish and materials ______ or less in thickness applied directly to and adhering tightly to a substrate.…” — what value is stated?', '["1 mm","1.2 mm","0.64 mm","0.33 mm"]', 2, 'Clause MATERIALS (GHBC-C-000264, page 135): Decorative materials do not include wall coverings, ceiling coverings, floor coverings, ordinary window shades, interior finish and materials 0.64 mm (0.025 inch) or less in thickness applied directly to and adhering tightly to a substrate.', 'study', 'GHBC-C-000264', 'GHBC-REQ-000632', 135, '33c052736d98d33f27de06174668e570ffd35ceed54d9021052d4f9d62b89b4b', 'requires_review', 0);
