INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-00776159a201233f', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause FABRIC PARTITION): “…which the vertical framing members are spaced greater than ______ on center.…” — what value is stated?', '["610 mm","1829 mm","2438 mm","1219 mm"]', 3, 'Clause FABRIC PARTITION (GHBC-C-000324, page 138): A partition consisting of a finished surface made of fabric, without a continuous rigid backing, that is directly attached to a framing system in which the vertical framing members are spaced greater than 1219 mm (4 feet) on center.', 'standard', 'GHBC-C-000324', 'GHBC-REQ-000750', 138, 'd19b46fecc344cd2a82049525efe9a8efa632e1e71e063559be141ea7af22bed', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-627b40275635543c', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause FABRIC PARTITION): “…which the vertical framing members are spaced greater than ______ on center.…” — what value is stated?', '["2 feet","6 feet","8 feet","4 feet"]', 3, 'Clause FABRIC PARTITION (GHBC-C-000324, page 138): A partition consisting of a finished surface made of fabric, without a continuous rigid backing, that is directly attached to a framing system in which the vertical framing members are spaced greater than 1219 mm (4 feet) on center.', 'standard', 'GHBC-C-000324', 'GHBC-REQ-000750', 138, 'd19b46fecc344cd2a82049525efe9a8efa632e1e71e063559be141ea7af22bed', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0629cf090e8537fb', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause GRADE FLOOR OPENING): “…such that the sill height of the opening is not more than ______ above or below the finished ground level adjacent to the opening.…” — what value is stated?', '["559 mm","1676 mm","2210 mm","1118 mm"]', 3, 'Clause GRADE FLOOR OPENING (GHBC-C-000396, page 143): opening located such that the sill height of the opening is not more than 1118 mm (44 inches) above or below the finished ground level adjacent to the opening.', 'study', 'GHBC-C-000396', 'GHBC-REQ-000887', 143, '541949bcc8546e679ddfce9c96da31ab8d68a8747a746cb9f06f8e6ee2c9da17', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-60df830ee52090ed', NULL, NULL, 'threshold', 2, 'GS 1207:2018 Part 2 (Clause GRADE FLOOR OPENING): “…such that the sill height of the opening is not more than ______ above or below the finished ground level adjacent to the opening.…” — what value is stated?', '["84 in","44 in","22 in","66 in"]', 1, 'Clause GRADE FLOOR OPENING (GHBC-C-000396, page 143): opening located such that the sill height of the opening is not more than 1118 mm (44 inches) above or below the finished ground level adjacent to the opening.', 'study', 'GHBC-C-000396', 'GHBC-REQ-000887', 143, '541949bcc8546e679ddfce9c96da31ab8d68a8747a746cb9f06f8e6ee2c9da17', 'requires_review', 0);
