INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e09254b9d6e97405', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.2.7.3): “…(______) in area and open mall buildings greater than ______ within the established perimeter line shall be provided with emergency power that is capable of operating the emergency voice/alarm communication system in……” — what value is stated?', '["4645 m2","2323 m2","5574 m2","2500 m2"]', 0, 'Clause 4.2.7.3 (GHBC-C-000813, page 181): (50,000 square feet) in area and open mall buildings greater than 4645 m2 (50,000 square feet) within the established perimeter line shall be provided with emergency power that is capable of operating the emergency voice/alarm communication system in accordance with this Code.', 'standard', 'GHBC-C-000813', 'GHBC-REQ-001896', 181, 'ea7c08b08b02558e8b0b6fe9cff931ebc66beb7523de6aeccb2f26061536d6e9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d57df3f26dcec394', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.2.7.4): “…Where the total floor area is greater than ______ within either a covered mall building or within the perimeter line of an open mall building, an emergency voice/alarm communication system shall be provided.…” — what value is stated?', '["4645 m2","2323 m2","5574 m2","2500 m2"]', 0, 'Clause 4.2.7.4 (GHBC-C-000814, page 181): Where the total floor area is greater than 4645 m2 (50,000 square feet) within either a covered mall building or within the perimeter line of an open mall building, an emergency voice/alarm communication system shall be provided.', 'standard', 'GHBC-C-000814', 'GHBC-REQ-001898', 181, 'e41a981c38c83366e2ed916756398a8f4ea8eb8b4b39f5c1b21e3ba2dc05c979', 'extracted', 1);
