INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-358b55d73c93d661', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.2.8.6): “…passageway or corridor from a mall shall be not less than ______.…” — what value is stated?', '["3200 mm","1676 mm","838 mm","2500 mm"]', 1, 'Clause 4.2.8.6 (GHBC-C-000827, page 183): The width of an exit passageway or corridor from a mall shall be not less than 1676 mm (66 inches).', 'standard', 'GHBC-C-000827', 'GHBC-REQ-001933', 183, '80feb20387fdc35d45d09e2d0f788216e0b4b3aa1b802d6e953606defaf4a34f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0233464132d80db7', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.2.8.6): “…passageway or corridor from a mall shall be not less than ______.…” — what value is stated?', '["119 in","66 in","33 in","100 in"]', 1, 'Clause 4.2.8.6 (GHBC-C-000827, page 183): The width of an exit passageway or corridor from a mall shall be not less than 1676 mm (66 inches).', 'standard', 'GHBC-C-000827', 'GHBC-REQ-001933', 183, '80feb20387fdc35d45d09e2d0f788216e0b4b3aa1b802d6e953606defaf4a34f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cdfe62f6b8a8fd4b', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.1.1): “…For buildings not greater than ______ in building height, the fire-resistance rating of the building elements in Type IA construction shall be permitted to be reduced to the minimum fire-resistance ratings for the……” — what value is stated?', '["63 m","200 m","250 m","128 m"]', 3, 'Clause 4.3.2.1.1 (GHBC-C-000834, page 184): For buildings not greater than 128 m (420 feet) in building height, the fire-resistance rating of the building elements in Type IA construction shall be permitted to be reduced to the minimum fire-resistance ratings for the building elements in Type IB.', 'study', 'GHBC-C-000834', 'GHBC-REQ-001970', 184, '3f6081d5f8c03b46ee9e47be13da70d0b679477d470cf9e1ef8d1a99906b26eb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-02678c7070337874', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.1.1): “…For buildings not greater than ______ in building height, the fire-resistance rating of the building elements in Type IA construction shall be permitted to be reduced to the minimum fire-resistance ratings for the……” — what value is stated?', '["1000 feet","420 feet","200 feet","500 feet"]', 1, 'Clause 4.3.2.1.1 (GHBC-C-000834, page 184): For buildings not greater than 128 m (420 feet) in building height, the fire-resistance rating of the building elements in Type IA construction shall be permitted to be reduced to the minimum fire-resistance ratings for the building elements in Type IB.', 'study', 'GHBC-C-000834', 'GHBC-REQ-001970', 184, '3f6081d5f8c03b46ee9e47be13da70d0b679477d470cf9e1ef8d1a99906b26eb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1b92cad312b2f1d4', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.1.1): “…In other than Group F-1, H-2, H-3, H-______ and S-1 occupancies, the fireresistance rating of the building…” — what value is stated?', '["-4 m","-3.5 m","-5 m","-3 m"]', 2, 'Clause 4.3.2.1.1 (GHBC-C-000834, page 184): In other than Group F-1, H-2, H-3, H-5, M and S-1 occupancies, the fireresistance rating of the building', 'study', 'GHBC-C-000834', 'GHBC-REQ-001972', 184, '85d075f3e623707649b87b9bd5402b7b30fa8b23f2f5e9a60240b4d858056a71', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-390f3f1a0dc46723', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.1.2): “…For buildings not greater than ______ in building height, the required fire-resistance rating of the fire barriers enclosing vertical shafts, other than interior exit stairway and elevator hoistway enclosures, is……” — what value is stated?', '["200 m","250 m","128 m","63 m"]', 2, 'Clause 4.3.2.1.2 (GHBC-C-000835, page 184): For buildings not greater than 128 m (420 feet) in building height, the required fire-resistance rating of the fire barriers enclosing vertical shafts, other than interior exit stairway and elevator hoistway enclosures, is permitted to be reduced to 1 hour where automatic sprinklers are installed within the shafts at the top and at alternate floor levels.', 'study', 'GHBC-C-000835', 'GHBC-REQ-001977', 184, 'e5c4aa3c956f4777132b272f4d0d86d890ccd53b7b29a7d3603e4d7d5f1f5769', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8cc5e65259951d0f', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.1.2): “…For buildings not greater than ______ in building height, the required fire-resistance rating of the fire barriers enclosing vertical shafts, other than interior exit stairway and elevator hoistway enclosures, is……” — what value is stated?', '["500 feet","1000 feet","420 feet","200 feet"]', 2, 'Clause 4.3.2.1.2 (GHBC-C-000835, page 184): For buildings not greater than 128 m (420 feet) in building height, the required fire-resistance rating of the fire barriers enclosing vertical shafts, other than interior exit stairway and elevator hoistway enclosures, is permitted to be reduced to 1 hour where automatic sprinklers are installed within the shafts at the top and at alternate floor levels.', 'study', 'GHBC-C-000835', 'GHBC-REQ-001977', 184, 'e5c4aa3c956f4777132b272f4d0d86d890ccd53b7b29a7d3603e4d7d5f1f5769', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6ca7a0156c877c23', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3): “…with this Code and for all buildings that are more than ______ in building height, enclosures for interior exit stairways and elevator hoistway enclosures shall comply with Clauses 4.3.2.3.1 through 4.3.2.3.4.…” — what value is stated?', '["128 m","63 m","200 m","250 m"]', 0, 'Clause 4.3.2.3 (GHBC-C-000837, page 184): For high-rise buildings of Risk Category III or IV in accordance with this Code and for all buildings that are more than 128 m (420 feet) in building height, enclosures for interior exit stairways and elevator hoistway enclosures shall comply with Clauses 4.3.2.3.1 through 4.3.2.3.4.', 'study', 'GHBC-C-000837', 'GHBC-REQ-001980', 184, 'd1f779b628ded1ad4c51dabfbd8584410d765a22e8e329478d1ddf08f5139378', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-65d8b7cc54433b3e', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3): “…with this Code and for all buildings that are more than ______ in building height, enclosures for interior exit stairways and elevator hoistway enclosures shall comply with Clauses 4.3.2.3.1 through 4.3.2.3.4.…” — what value is stated?', '["500 feet","1000 feet","420 feet","200 feet"]', 2, 'Clause 4.3.2.3 (GHBC-C-000837, page 184): For high-rise buildings of Risk Category III or IV in accordance with this Code and for all buildings that are more than 128 m (420 feet) in building height, enclosures for interior exit stairways and elevator hoistway enclosures shall comply with Clauses 4.3.2.3.1 through 4.3.2.3.4.', 'study', 'GHBC-C-000837', 'GHBC-REQ-001980', 184, 'd1f779b628ded1ad4c51dabfbd8584410d765a22e8e329478d1ddf08f5139378', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c54d8b4fb6bbf2d5', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3.1): “…2 as measured by the test method described in ASTM C1629/C______.…” — what value is stated?', '["2400 m","3000 m","1629 m","900 m"]', 2, 'Clause 4.3.2.3.1 (GHBC-C-000838, page 184): The wall assemblies making up the enclosures for interior exit stairways and elevator hoistway enclosures shall meet or exceed Soft Body Impact Classification Level 2 as measured by the test method described in ASTM C1629/C1629M.', 'study', 'GHBC-C-000838', 'GHBC-REQ-001981', 184, '69eb597120964ab5173e294dd9d788738cf4335a2755220b681b06c6c57ea9bf', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6d8b23df0dcec769', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3.2): “…2 as measured by the test method described in ASTM C1629/C______.…” — what value is stated?', '["3000 m","1629 m","900 m","2400 m"]', 1, 'Clause 4.3.2.3.2 (GHBC-C-000839, page 184): The wall assembly shall incorporate not fewer than two layers of impact-resistant construction board each of which meets or exceeds Hard Body Impact Classification Level 2 as measured by the test method described in ASTM C1629/C1629M.', 'study', 'GHBC-C-000839', 'GHBC-REQ-001984', 184, '0c32fa1d12a243c75821854f27779aa5ea9ccd919f43abfc965dec0e2d6ebac4', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d923abc467ee7695', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3.2): “…3 as measured by the test method described in ASTM C1629/C______.…” — what value is stated?', '["900 m","2400 m","3000 m","1629 m"]', 3, 'Clause 4.3.2.3.2 (GHBC-C-000839, page 184): The wall assembly shall incorporate not less than one layer of impact-resistant construction material that meets or exceeds Hard Body Impact Classification Level 3 as measured by the test method described in ASTM C1629/C1629M.', 'study', 'GHBC-C-000839', 'GHBC-REQ-001986', 184, '7d98ee244506c2fa7dca7505007f0dfb5d346cf970589d0f1f8762fb11a21428', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-95c047fc11d93136', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3.2): “…3 as measured by the test method described in ASTM C1629/C______.…” — what value is stated?', '["1629 m","900 m","2400 m","3000 m"]', 0, 'Clause 4.3.2.3.2 (GHBC-C-000839, page 184): The wall assembly incorporates multiple layers of any material, tested in tandem that meets or exceeds Hard Body Impact Classification Level 3 as measured by the test method described in ASTM C1629/C1629M.', 'study', 'GHBC-C-000839', 'GHBC-REQ-001988', 184, '63756b27abc4461283f1f70d52e926e04fbc2c564047c830274f38de04234f24', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cfcdeac9c60c944d', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.3.4): “…3, as measured by the test method described in ASTM C1629/C______, shall be permitted.…” — what value is stated?', '["3000 m","1629 m","900 m","2400 m"]', 1, 'Clause 4.3.2.3.4 (GHBC-C-000841, page 185): Any other wall assembly that provides impact resistance equivalent to that required by Clauses 4.3.2.3.1 and 4.3.2.3.2 for Hard Body Impact Classification Level 3, as measured by the test method described in ASTM C1629/C1629M, shall be permitted.', 'standard', 'GHBC-C-000841', 'GHBC-REQ-001990', 185, 'bc5704e2d1ea05fd77889b90acfb2f299c2b6deb4525895810a5a6cb9db7aafb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d892352b7e3a9782', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.2.4): “…For SI: ______ = ______, 1 pound per square foot (psf) = 0.0479 kW/m2 . a.…” — what value is stated?', '["457 mm","610 mm","304.8 mm","152.4 mm"]', 2, 'Clause 4.3.2.4 (GHBC-C-000842, page 185): For SI: 1 foot = 304.8 mm, 1 pound per square foot (psf) = 0.0479 kW/m2 . a.', 'standard', 'GHBC-C-000842', 'GHBC-REQ-001993', 185, 'baf38df0af23c5bc8a1293b299fa951482661596639d09d19bbf31931cfe5124', 'extracted', 1);
