INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bfd7b77576cb0d1d', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.3.1): “…Each sprinkler system zone in buildings that are more than ______ in building height shall be supplied by not fewer than two risers.…” — what value is stated?', '["200 feet","500 feet","1000 feet","420 feet"]', 3, 'Clause 4.3.3.1 (GHBC-C-000844, page 185): Each sprinkler system zone in buildings that are more than 128 m (420 feet) in building height shall be supplied by not fewer than two risers.', 'standard', 'GHBC-C-000844', 'GHBC-REQ-002002', 185, '0b5ec12e05fee3146e25ad546e268f79ce10eee5ca8f07895b48003b65393231', 'extracted', 1);
