INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b55cb4b9683f13f0', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.4.7): “…Easily identifiable______anually operable windows or panels shall be distributed around the perimeter of each floor at not more than 15 ______ intervals.…” — what value is stated?', '["240 mm","120 mm","356 mm","480 mm"]', 0, 'Clause 4.3.4.7 (GHBC-C-000855, page 186): Easily identifiable, manually operable windows or panels shall be distributed around the perimeter of each floor at not more than 15 240 mm (50-foot) intervals.', 'standard', 'GHBC-C-000855', 'GHBC-REQ-002026', 186, '6d24bfacec8f83f4f5c08e5a99db014a29bf501e68eea4f146645fc6f1b34099', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-85d8328696e17864', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.4.7): “…area of operable windows or panels shall be not less than ______ per 15 ______ of perimeter.…” — what value is stated?', '["7.43 m2","3.7 m2","1.86 m2","6 m2"]', 1, 'Clause 4.3.4.7 (GHBC-C-000855, page 186): The area of operable windows or panels shall be not less than 3.7 m2 (40 square feet) per 15 240 mm (50 linear feet) of perimeter.', 'standard', 'GHBC-C-000855', 'GHBC-REQ-002027', 186, 'a642104fd87fe775249df77a511e9d88ff4d866a30f6ba2b8aa2ed16f8497c3a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-abf5c710b8249c04', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.4.7): “…area of operable windows or panels shall be not less than ______ per 15 ______ of perimeter.…” — what value is stated?', '["120 mm","356 mm","480 mm","240 mm"]', 3, 'Clause 4.3.4.7 (GHBC-C-000855, page 186): The area of operable windows or panels shall be not less than 3.7 m2 (40 square feet) per 15 240 mm (50 linear feet) of perimeter.', 'standard', 'GHBC-C-000855', 'GHBC-REQ-002027', 186, 'a642104fd87fe775249df77a511e9d88ff4d866a30f6ba2b8aa2ed16f8497c3a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e24e8f4665c110c2', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.3.4.7): “…an exterior wall shall be permitted to be provided with (______ ) of venting area in lieu of the area specified in Item 1.…” — what value is stated?', '["0.19 m2","0.093 m2","0.28 m2","0.4 m2"]', 0, 'Clause 4.3.4.7 (GHBC-C-000855, page 186): In Group R-1 occupancies, each sleeping unit or suite having an exterior wall shall be permitted to be provided with (0.19 m2 ) of venting area in lieu of the area specified in Item 1.', 'standard', 'GHBC-C-000855', 'GHBC-REQ-002030', 186, 'd0e540dd63fb180555faf5218d119f1996797f3426a7e8d0ab7bc4ac0df4ce4b', 'extracted', 1);
