INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-782817e82f76a7b9', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.7.4.4.5.2): “…any care suite that contains sleeping rooms, of more than ______…” — what value is stated?', '["139.4 m2","186 m2","93 m2","46.5 m2"]', 2, 'Clause 4.7.4.4.5.2 (GHBC-C-000975, page 200): Any sleeping room, or any care suite that contains sleeping rooms, of more than 93 m2', 'standard', 'GHBC-C-000975', 'GHBC-REQ-002475', 200, '2a52951724a472d2ef1e899d67fe69adea69c9d4b7e7259bd20b09cb715e9b6f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-13192edd41ae124b', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.7.4.4.6.1): “…than sleeping rooms, shall have an area not greater than ______.…” — what value is stated?', '["1161 m2","610 m2","1860 m2","2323 m2"]', 0, 'Clause 4.7.4.4.6.1 (GHBC-C-000977, page 200): Care suites of rooms, other than sleeping rooms, shall have an area not greater than 1161 m2 (12,500 square feet).', 'standard', 'GHBC-C-000977', 'GHBC-REQ-002480', 200, 'd70173b44337207255c1fb9ca5473ac3c6b136903511631a426b8a8d7df391b2', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-eff8a9f71d4201c5', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.7.4.4.6.1): “…sleeping rooms shall be permitted to be not greater than ______ in area where an automatic smoke detection system is provided throughout the care suite in accordance with Clause 10.7.…” — what value is stated?', '["1394 m2","696 m2","2092 m2","2500 m2"]', 0, 'Clause 4.7.4.4.6.1 (GHBC-C-000977, page 200): EXCEPTIONS: Care suites not containing sleeping rooms shall be permitted to be not greater than 1394 m2 (15,000 square feet) in area where an automatic smoke detection system is provided throughout the care suite in accordance with Clause 10.7.', 'standard', 'GHBC-C-000977', 'GHBC-REQ-002481', 200, 'c979754dd5f94a79db25a04ccdbf3617117fd3dcd73ef3077b6f5e9c957cdde9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e7d2728051f1cd8d', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.7.4.4.6.2): “…other than sleeping rooms, with an area of more than ______ shall have not fewer than two exit access doors from the care suite located in accordance with this Code.…” — what value is stated?', '["372 m2","464 m2","232 m2","103 m2"]', 2, 'Clause 4.7.4.4.6.2 (GHBC-C-000978, page 200): Care suites, other than sleeping rooms, with an area of more than 232 m2 (2,500 square feet) shall have not fewer than two exit access doors from the care suite located in accordance with this Code.', 'standard', 'GHBC-C-000978', 'GHBC-REQ-002482', 200, '2ae38384c172cacfbf97125895e85383e7913fcbe677d1465114081be006215d', 'extracted', 1);
