INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a13038d9759e18cd', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.10.2.1): “…Stages of Type IB or III construction with a nominal ______ wood deck, provided that the stage is separated from other areas in accordance with Clause 4.10.2.4.…” — what value is stated?', '["51 mm","25.4 mm","76 mm","102 mm"]', 0, 'Clause 4.10.2.1 (GHBC-C-001035, page 206): Stages of Type IB or III construction with a nominal 51 mm (2-inch) wood deck, provided that the stage is separated from other areas in accordance with Clause 4.10.2.4.', 'standard', 'GHBC-C-001035', 'GHBC-REQ-002653', 206, '932e54fad185a11ae3f56892a635d6db71703fad7b3f1bc8e8ed475ec7154249', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c095496795724b2c', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.10.2.4): “…Where the stage height is greater than 15 ______, all portions of the stage shall be completely separated from the seating area by a proscenium wall with not less than a 2-hour fire-resistance rating extending……” — what value is stated?', '["356 mm","480 mm","240 mm","120 mm"]', 2, 'Clause 4.10.2.4 (GHBC-C-001038, page 207): Where the stage height is greater than 15 240 mm (50 feet), all portions of the stage shall be completely separated from the seating area by a proscenium wall with not less than a 2-hour fire-resistance rating extending continuously from the foundation to the roof.', 'standard', 'GHBC-C-001038', 'GHBC-REQ-002669', 207, 'a4ea77593553775d3503bce1a1030271d82b7addf6f2218490180de384002c44', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2f7cb30cd7155dc5', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.10.2.4): “…Where the stage height is greater than 15 ______, all portions of the stage shall be completely separated from the seating area by a proscenium wall with not less than a 2-hour fire-resistance rating extending……” — what value is stated?', '["25 feet","75 feet","100 feet","50 feet"]', 3, 'Clause 4.10.2.4 (GHBC-C-001038, page 207): Where the stage height is greater than 15 240 mm (50 feet), all portions of the stage shall be completely separated from the seating area by a proscenium wall with not less than a 2-hour fire-resistance rating extending continuously from the foundation to the roof.', 'standard', 'GHBC-C-001038', 'GHBC-REQ-002669', 207, 'a4ea77593553775d3503bce1a1030271d82b7addf6f2218490180de384002c44', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-53c55d482e6a0f45', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.10.2.5): “…designed to maintain the smoke level not less than ______ above the floor of the means of escape shall be required.…” — what value is stated?', '["3658 mm","1829 mm","914 mm","2743 mm"]', 1, 'Clause 4.10.2.5 (GHBC-C-001039, page 207): Facilities not utilizing the provisions of smoke-protected assembly seating in accordance with Clause 11.29.6.2, a smoke control system complying with Clause 10.9 or natural ventilation designed to maintain the smoke level not less than 1829 mm (6 feet) above the floor of the means of escape shall be required.', 'standard', 'GHBC-C-001039', 'GHBC-REQ-002672', 207, '4dd4ca17b041a3682fb1fe7ec2868c4d6d75fa552b19b6d412f757c5de6eabe8', 'extracted', 1);
