INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b58dcffacaf12e2c', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.10.2.6): “…Test Method 1 or Test Method 2, as appropriate, of ASTM E______ accordance with Clause 9.6 and the Ghana Fire Code.…” — what value is stated?', '["119 in","100 in","84 in","42 in"]', 2, 'Clause 4.10.2.6 (GHBC-C-001040, page 207): Combustible materials used in sets and scenery shall meet the fire propagation performance criteria of Test Method 1 or Test Method 2, as appropriate, of ASTM E84, in accordance with Clause 9.6 and the Ghana Fire Code.', 'standard', 'GHBC-C-001040', 'GHBC-REQ-002673', 207, 'd46b5cac2348729c8a2b3c46866e2cb65cc0bd76659f27b7a441053693fada9e', 'extracted', 1);
