INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6b0841a48ab758b9', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.22.3.2): “…Not less than ______ for each nonambulatory care recipient shall be provided within the aggregate area of corridors, care recipient rooms, treatment rooms, lounge or dining areas and other low-hazard areas within each……” — what value is stated?', '["4 m2","6 m2","2.8 m2","1.4 m2"]', 2, 'Clause 4.22.3.2 (GHBC-C-001303, page 239): Not less than 2.8 m2 (30 net square feet) for each nonambulatory care recipient shall be provided within the aggregate area of corridors, care recipient rooms, treatment rooms, lounge or dining areas and other low-hazard areas within each smoke compartment.', 'standard', 'GHBC-C-001303', 'GHBC-REQ-003474', 239, 'e5f67c46bca8bc27676db62ff1e78839afa03a28205d4775ce1ca49b35611a81', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8d9f5dc60f855e33', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.23.3): “…tornados in accordance with Figure 304.2(1) of ICC 500 is ______ph, 911 call stations, emergency operation centers and fire, rescue, ambulance and police stations shall comply with this Code and shall be provided with a……” — what value is stated?', '["125 m","360 m","500 m","250 m"]', 3, 'Clause 4.23.3 (GHBC-C-001310, page 240): In areas where the shelter design wind speed for tornados in accordance with Figure 304.2(1) of ICC 500 is 250 mph, 911 call stations, emergency operation centers and fire, rescue, ambulance and police stations shall comply with this Code and shall be provided with a storm shelter constructed in accordance with ICC 500.', 'standard', 'GHBC-C-001310', 'GHBC-REQ-003485', 240, 'cdf1b47b046220f76a54a94b4c88940933c721bc0616b4b4d1ffb9cf878003c7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-656dd1e781d4473c', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.23.4): “…areas where the shelter design wind speed for tornados is ______ph in accordance with…” — what value is stated?', '["250 m","125 m","360 m","500 m"]', 0, 'Clause 4.23.4 (GHBC-C-001311, page 240): In areas where the shelter design wind speed for tornados is 250 mph in accordance with', 'study', 'GHBC-C-001311', 'GHBC-REQ-003486', 240, 'f3a6a333242f8a5b0b7ef391742a328d94fd976e7f608a49bc1bbc26eb2da013', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2830240d4588275b', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.23.4.2): “…door of the shelter serving that building does not exceed ______.…” — what value is stated?', '["152 m","450 m","605 m","305 m"]', 3, 'Clause 4.23.4.2 (GHBC-C-001313, page 240): Storm shelters shall be located within the buildings they serve or shall be located where the maximum distance of travel from not fewer than one exterior door of each building to a door of the shelter serving that building does not exceed 305 m (1,000 feet).', 'standard', 'GHBC-C-001313', 'GHBC-REQ-003505', 240, '0620758c88a270af5fc5aa414d8724c91e11b9415140a6b9bfaf0448c6081bff', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8f2c9223d581fb84', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.23.4.2): “…door of the shelter serving that building does not exceed ______.…” — what value is stated?', '["420 feet","400 feet","1000 feet","500 feet"]', 2, 'Clause 4.23.4.2 (GHBC-C-001313, page 240): Storm shelters shall be located within the buildings they serve or shall be located where the maximum distance of travel from not fewer than one exterior door of each building to a door of the shelter serving that building does not exceed 305 m (1,000 feet).', 'standard', 'GHBC-C-001313', 'GHBC-REQ-003505', 240, '0620758c88a270af5fc5aa414d8724c91e11b9415140a6b9bfaf0448c6081bff', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b0785ee2b09e589f', NULL, NULL, 'threshold', 4, 'GS 1207:2018 Part 4 (Clause 4.24.1): “…inside all occupancies covered by this Code that exceed ______ in height or ______ in area shall comply with Clauses 4.24.2 through 4.24.5.…” — what value is stated?', '["6096 mm","3048 mm","1524 mm","4572 mm"]', 1, 'Clause 4.24.1 (GHBC-C-001314, page 240): Children‘s play structures installed inside all occupancies covered by this Code that exceed 3048 mm (10 feet) in height or 14 m2 (150 square feet) in area shall comply with Clauses 4.24.2 through 4.24.5.', 'standard', 'GHBC-C-001314', 'GHBC-REQ-003506', 240, '64817db5facc22ec663ce382713518c0b641db8a8982914080497f3db49cff03', 'extracted', 1);
