INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f9020448ca51454c', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3): “…means of access, the prescribed widths may be reduced by ______ in each case…” — what value is stated?', '["2 m","1 m","0.5 m","1.5 m"]', 1, 'Clause 5.3.3 (GHBC-C-001350, page 246): Note:  If the development is only on one side of the means of access, the prescribed widths may be reduced by 1m in each case', 'study', 'GHBC-C-001350', 'GHBC-REQ-003626', 246, 'f1755e2839510d45ca358f3ba2e42eaa2fab32675afa1b9067aea8a0ffcb2dee', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-242834767de602fe', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.2): “…shall be through paved pathway of width not less than ______, provided its length is not more than ______.…” — what value is stated?', '["0.75 m","2.25 m","3 m","1.5 m"]', 3, 'Clause 5.3.3.2 (GHBC-C-001352, page 247): The approach to the buildings from road/street/internal means of access shall be through paved pathway of width not less than 1.5m, provided its length is not more than 3.0m.', 'standard', 'GHBC-C-001352', 'GHBC-REQ-003629', 247, '382ed2d2a2fbf341f173fe27396a58915754228a3970942894c372d2603783eb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-242834767de602fe', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.2): “…shall be through paved pathway of width not less than ______, provided its length is not more than ______.…” — what value is stated?', '["1.5 m","4.5 m","6 m","3 m"]', 3, 'Clause 5.3.3.2 (GHBC-C-001352, page 247): The approach to the buildings from road/street/internal means of access shall be through paved pathway of width not less than 1.5m, provided its length is not more than 3.0m.', 'standard', 'GHBC-C-001352', 'GHBC-REQ-003629', 247, '382ed2d2a2fbf341f173fe27396a58915754228a3970942894c372d2603783eb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f9606f140e7427f2', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.2.1): “…housing scheme, the pedestrian pathway width shall be ______ subject to provisions of Clause 6.5.4.1(a).…” — what value is stated?', '["3 m","1.5 m","4.5 m","6 m"]', 0, 'Clause 5.3.3.2.1 (GHBC-C-001353, page 247): schemes for low income group and economically weaker Clause of society developed up to two storeyed row/cluster housing scheme, the pedestrian pathway width shall be 3m subject to provisions of Clause 6.5.4.1(a).', 'standard', 'GHBC-C-001353', 'GHBC-REQ-003630', 247, '82b4b6f1c7a813e98df11999a68cbd4b92978f7b223d286a2ca208b608957b0e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e4186822b0e87c58', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.2.1): “…pathway; the length of the pathway shall be not more than ______.…” — what value is stated?', '["80 m","100 m","50 m","25 m"]', 2, 'Clause 5.3.3.2.1 (GHBC-C-001353, page 247): The pedestrian pathway shall not serve more than 8 plots on each side of the pathway; the length of the pathway shall be not more than 50m.', 'study', 'GHBC-C-001353', 'GHBC-REQ-003631', 247, '798ffdc3e40a2a77a9a50f150df99ee166f6e762e2f8010dbe498eec8c0ec3de', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-df77866ff3a233ab', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.5): “…the case of plots facing street/means of access less than ______ in width, the plot boundary shall be shifted to be away by ______ from the central line of the street/means of access way of ______ width.…” — what value is stated?', '["9 m","4.5 m","2.25 m","7 m"]', 1, 'Clause 5.3.3.5 (GHBC-C-001355, page 247): In existing built-up areas in the case of plots facing street/means of access less than 4.5m in width, the plot boundary shall be shifted to be away by 2.25m from the central line of the street/means of access way of 4.5m width.', 'standard', 'GHBC-C-001355', 'GHBC-REQ-003633', 247, '4afd98b90dd158dade74d5e9242128b4c6a897b7d179c12be94c197bdad586e4', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-df77866ff3a233ab', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.5): “…the case of plots facing street/means of access less than ______ in width, the plot boundary shall be shifted to be away by ______ from the central line of the street/means of access way of ______ width.…” — what value is stated?', '["4.5 m","2.25 m","1.12 m","3.3 m"]', 1, 'Clause 5.3.3.5 (GHBC-C-001355, page 247): In existing built-up areas in the case of plots facing street/means of access less than 4.5m in width, the plot boundary shall be shifted to be away by 2.25m from the central line of the street/means of access way of 4.5m width.', 'standard', 'GHBC-C-001355', 'GHBC-REQ-003633', 247, '4afd98b90dd158dade74d5e9242128b4c6a897b7d179c12be94c197bdad586e4', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-df77866ff3a233ab', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.3.5): “…the case of plots facing street/means of access less than ______ in width, the plot boundary shall be shifted to be away by ______ from the central line of the street/means of access way of ______ width.…” — what value is stated?', '["9 m","4.5 m","2.25 m","7 m"]', 1, 'Clause 5.3.3.5 (GHBC-C-001355, page 247): In existing built-up areas in the case of plots facing street/means of access less than 4.5m in width, the plot boundary shall be shifted to be away by 2.25m from the central line of the street/means of access way of 4.5m width.', 'standard', 'GHBC-C-001355', 'GHBC-REQ-003633', 247, '4afd98b90dd158dade74d5e9242128b4c6a897b7d179c12be94c197bdad586e4', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b451f18efdad5320', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.4.2): “…No premises other than highway amenities like petrol pumps______otels, etc. shall have an access direct from highways and such other roads not less than ______ in width, which the Authority with the approval of the……” — what value is stated?', '["52 m","25 m","80 m","100 m"]', 0, 'Clause 5.3.4.2 (GHBC-C-001357, page 247): 5.3.5 Access from Highways/Important Roads No premises other than highway amenities like petrol pumps, motels, etc. shall have an access direct from highways and such other roads not less than 52m in width, which the Authority with the approval of the Highway Authority shall specify from time to time.', 'standard', 'GHBC-C-001357', 'GHBC-REQ-003636', 247, '2e53768c984f3e65e672205778a97fdbf75412f0d92bd38fff45d24f9bfe7a2b', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2ba9bbeac5e7179', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.6): “…street on which the building abuts shall not be less than ______ and one end of this street shall join another street not less than ______ in width. b) The approach to the building and open spaces on all its sides up to……” — what value is stated?', '["12 m","6 m","18 m","24 m"]', 0, 'Clause 5.3.6 (GHBC-C-001358, page 248): other than residential, the following additional provisions of means of access shall be ensured: a)  The width of the main street on which the building abuts shall not be less than 12m and one end of this street shall join another street not less than 12m in width. b)  The approach to the building and open spaces on all its sides up to 6m width and the layout for the same shall be done in consulta', 'study', 'GHBC-C-001358', 'GHBC-REQ-003641', 248, '8dc017364395debcdcceb9ea4cccb88d332f4235242ba4eda02538dd96c2e8b4', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2ba9bbeac5e7179', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.6): “…street on which the building abuts shall not be less than ______ and one end of this street shall join another street not less than ______ in width. b) The approach to the building and open spaces on all its sides up to……” — what value is stated?', '["12 m","6 m","18 m","24 m"]', 0, 'Clause 5.3.6 (GHBC-C-001358, page 248): other than residential, the following additional provisions of means of access shall be ensured: a)  The width of the main street on which the building abuts shall not be less than 12m and one end of this street shall join another street not less than 12m in width. b)  The approach to the building and open spaces on all its sides up to 6m width and the layout for the same shall be done in consulta', 'study', 'GHBC-C-001358', 'GHBC-REQ-003641', 248, '8dc017364395debcdcceb9ea4cccb88d332f4235242ba4eda02538dd96c2e8b4', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2ba9bbeac5e7179', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.6): “…street on which the building abuts shall not be less than ______ and one end of this street shall join another street not less than ______ in width. b) The approach to the building and open spaces on all its sides up to……” — what value is stated?', '["6 m","3 m","9 m","12 m"]', 0, 'Clause 5.3.6 (GHBC-C-001358, page 248): other than residential, the following additional provisions of means of access shall be ensured: a)  The width of the main street on which the building abuts shall not be less than 12m and one end of this street shall join another street not less than 12m in width. b)  The approach to the building and open spaces on all its sides up to 6m width and the layout for the same shall be done in consulta', 'study', 'GHBC-C-001358', 'GHBC-REQ-003641', 248, '8dc017364395debcdcceb9ea4cccb88d332f4235242ba4eda02538dd96c2e8b4', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1592ddd4e91de74b', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.6): “…the fire engine and in no case shall it measure less than ______.…” — what value is stated?', '["2.25 m","7 m","9 m","4.5 m"]', 3, 'Clause 5.3.6 (GHBC-C-001358, page 248): The said open space shall be kept free of obstructions and shall be motorable. c)  The main entrance to the plot shall be of adequate width to allow easy access to the fire engine and in no case shall it measure less than 4.5m.', 'standard', 'GHBC-C-001358', 'GHBC-REQ-003642', 248, 'dd92b5f665655b47640c375fb2a31634d2fdc3d253e3da5b91fa34b4ef7f593f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c490a5e5817e7251', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.6): “…wall is built over, the minimum clearance shall be ______.…” — what value is stated?', '["4.5 m","2.25 m","7 m","9 m"]', 0, 'Clause 5.3.6 (GHBC-C-001358, page 248): If the main entrance at the boundary wall is built over, the minimum clearance shall be 4.5m.', 'standard', 'GHBC-C-001358', 'GHBC-REQ-003644', 248, 'f02937caa5ea2d66732f6e48e2d37ea9ceff361619c78d4e60325830549c0c7b', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2fe14466bf007b22', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.7): “…giving access to plots and extending from 150 to ______ in length with an additional turning space at ______ will be allowed only in residential areas, provided culde-sacs would be permissible only on straight roads and……” — what value is stated?', '["137 m","414 m","551 m","275 m"]', 3, 'Clause 5.3.7 (GHBC-C-001359, page 248): Cul-de-sacs giving access to plots and extending from 150 to 275m in length with an additional turning space at 150m will be allowed only in residential areas, provided culde-sacs would be permissible only on straight roads and further provided the end of cul-desacs shall be higher in level than the level of the starting point of such dead end road.', 'standard', 'GHBC-C-001359', 'GHBC-REQ-003645', 248, '90865733e7da4748cb6620b9bc5a180f7758008f86c56991b1341e1335456b7e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2fe14466bf007b22', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.7): “…giving access to plots and extending from 150 to ______ in length with an additional turning space at ______ will be allowed only in residential areas, provided culde-sacs would be permissible only on straight roads and……” — what value is stated?', '["80 m","227 m","300 m","150 m"]', 3, 'Clause 5.3.7 (GHBC-C-001359, page 248): Cul-de-sacs giving access to plots and extending from 150 to 275m in length with an additional turning space at 150m will be allowed only in residential areas, provided culde-sacs would be permissible only on straight roads and further provided the end of cul-desacs shall be higher in level than the level of the starting point of such dead end road.', 'standard', 'GHBC-C-001359', 'GHBC-REQ-003645', 248, '90865733e7da4748cb6620b9bc5a180f7758008f86c56991b1341e1335456b7e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-710e2afaf4d0b231', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.7): “…The turning space in this case shall be not less than ______ in area, with no dimension less than ______.…” — what value is stated?', '["81 m","40 m","122 m","152 m"]', 0, 'Clause 5.3.7 (GHBC-C-001359, page 248): The turning space in this case shall be not less than 81 m in area, with no dimension less than 9m.', 'standard', 'GHBC-C-001359', 'GHBC-REQ-003646', 248, 'd27ca4aea6878bf27359ce2c6fdabef4cd72ed048bd403d784a4eab8e43814bd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-710e2afaf4d0b231', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.7): “…The turning space in this case shall be not less than ______ in area, with no dimension less than ______.…” — what value is stated?', '["9 m","4.5 m","13.2 m","18 m"]', 0, 'Clause 5.3.7 (GHBC-C-001359, page 248): The turning space in this case shall be not less than 81 m in area, with no dimension less than 9m.', 'standard', 'GHBC-C-001359', 'GHBC-REQ-003646', 248, 'd27ca4aea6878bf27359ce2c6fdabef4cd72ed048bd403d784a4eab8e43814bd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ec80c859ec31a761', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.3.9): “…The building line shall be set back at least ______ from internal means of access in a layout of buildings in a plot subject to provisions of Clause 5.6.2.1.…” — what value is stated?', '["4.5 m","6 m","3 m","1.5 m"]', 2, 'Clause 5.3.9 (GHBC-C-001361, page 248): The building line shall be set back at least 3m from internal means of access in a layout of buildings in a plot subject to provisions of Clause 5.6.2.1.', 'standard', 'GHBC-C-001361', 'GHBC-REQ-003648', 248, '94aa020975c32a18e2cd66b13e79dccd28e266599252a76838a901b9a61c0fdb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0c05b3f888e3c611', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.2): “…No recreational space shall generally be less than ______.…” — what value is stated?', '["929 m2","450 m2","220 m2","696 m2"]', 1, 'Clause 5.4.2 (GHBC-C-001364, page 249): No recreational space shall generally be less than 450 m2.', 'standard', 'GHBC-C-001364', 'GHBC-REQ-003655', 249, '8c267106bed55b05dfc55795573c6e4bac888a4f63847d63168d4370d571d1e3', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d55c826b73745b07', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.2.1): “…of such recreational space shall be not less than ______; if the average width of such recreational space is less than ______, the length thereof shall not exceed 2.5 times the average width.…” — what value is stated?', '["3.75 m","11.1 m","15 m","7.5 m"]', 3, 'Clause 5.4.2.1 (GHBC-C-001365, page 249): The minimum average dimension of such recreational space shall be not less than 7.5m; if the average width of such recreational space is less than 24m, the length thereof shall not exceed 2.5 times the average width.', 'study', 'GHBC-C-001365', 'GHBC-REQ-003656', 249, '8edfefc24ff9e885be462e836c817166bd423f569d99a7d5661e546d21973673', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d55c826b73745b07', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.2.1): “…of such recreational space shall be not less than ______; if the average width of such recreational space is less than ______, the length thereof shall not exceed 2.5 times the average width.…” — what value is stated?', '["12 m","35 m","49 m","24 m"]', 3, 'Clause 5.4.2.1 (GHBC-C-001365, page 249): The minimum average dimension of such recreational space shall be not less than 7.5m; if the average width of such recreational space is less than 24m, the length thereof shall not exceed 2.5 times the average width.', 'study', 'GHBC-C-001365', 'GHBC-REQ-003656', 249, '8edfefc24ff9e885be462e836c817166bd423f569d99a7d5661e546d21973673', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-40e86c61ba1de5f3', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.2.2): “…storeyed structure as pavilion or gymnasia up to ______ in area may be permitted; such area may be excluded from FAR calculations; no toilet block shall be permitted.…” — what value is stated?', '["25 m2","12 m2","37 m2","50 m2"]', 0, 'Clause 5.4.2.2 (GHBC-C-001366, page 249): storeyed structure as pavilion or gymnasia up to 25m2 in area may be permitted; such area may be excluded from FAR calculations; no toilet block shall be permitted.', 'standard', 'GHBC-C-001366', 'GHBC-REQ-003658', 249, '2279d8a66c567a8ca1fdd876e7921b0e14b265a36d8e34f72a4badd4629451cd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bcd7595be6b888c5', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.3): “…Further, the building line shall be at least ______ away from the boundary of recreational open space.…” — what value is stated?', '["4.5 m","6 m","3 m","1.5 m"]', 2, 'Clause 5.4.3 (GHBC-C-001367, page 249): Further, the building line shall be at least 3m away from the boundary of recreational open space.', 'standard', 'GHBC-C-001367', 'GHBC-REQ-003661', 249, '66284e60f8f15767596e87b728d6d7f9621edfe41c8fc9061f0b209bc935f482', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e3baac86d713a468', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.4): “…parking space; when such amenity open space exceeds ______, the excess area could be utilized for the construction of buildings for banks, canteens, welfare centres and such other common purposes considered necessary……” — what value is stated?', '["2500 m2","1500 m2","744 m2","2230 m2"]', 1, 'Clause 5.4.4 (GHBC-C-001368, page 249): In the case of sub-division of land in industrial zones of area 0.8 hectare or more, 5 percent of the total area shall be reserved as amenity open space which shall also serve as a general parking space; when such amenity open space exceeds 1500 m2, the excess area could be utilized for the construction of buildings for banks, canteens, welfare centres and such other common purposes considered nec', 'standard', 'GHBC-C-001368', 'GHBC-REQ-003662', 249, '412e113bc974ea55cc004fbda1f7c2993e8a2c30dcd40c5ba5c141f3a0623c38', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c81ad8d7dd55bfd2', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.4.4.1): “…shall be provided as an amenity open space to a maximum of ______.…” — what value is stated?', '["1256 m2","4645 m2","5000 m2","2500 m2"]', 3, 'Clause 5.4.4.1 (GHBC-C-001369, page 249): or more in area, 10 percent of the total area shall be provided as an amenity open space to a maximum of 2500 m2.', 'standard', 'GHBC-C-001369', 'GHBC-REQ-003663', 249, '8e7d4cd92f04439df99a1bd788c016f064a3b1424224db284d8fe8645b221a00', 'extracted', 1);
