INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6608e3a524040c41', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.5.7.3.1): “…basis of seating capacity of the building at the rate of ______ per seat.…” — what value is stated?', '["0.53 m2","1.5 m2","2 m2","1 m2"]', 3, 'Clause 5.5.7.3.1 (GHBC-C-001384, page 251): The minimum size of plot for assembly buildings/cinema theatres used for public entertainment and religious/social centres, with fixed seats shall be on the basis of seating capacity of the building at the rate of 1 m2 per seat.', 'standard', 'GHBC-C-001384', 'GHBC-REQ-003699', 251, '347fdc64b894fe2da3e7337e2f793b0e1984efc5e014a9f19c34047528079452', 'extracted', 1);
