INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-78a0161d83358fdc', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.1.1): “…subject to a minimum of ______ for cases (ii), (iii) and (iv) of Table 4.1, above. b) For streets less than ______ in width, the distance of the building (building line) shall be at least ______ from the centre line of……” — what value is stated?', '["11.1 m","15 m","7.5 m","3.75 m"]', 2, 'Clause 5.6.2.1.1 (GHBC-C-001391, page 251): subject to a minimum of 1.8m for cases (ii), (iii) and (iv) of Table 4.1, above. b) For streets less than 7.5m in width, the distance of the building (building line) shall be at least 5m from the centre line of the street See 5.3.3.5.', 'standard', 'GHBC-C-001391', 'GHBC-REQ-003709', 251, '48a339a23b13d7ddb3c3985746e78e76b8039ca0bcc1104cc2616eafe8e0bcdc', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-78a0161d83358fdc', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.1.1): “…subject to a minimum of ______ for cases (ii), (iii) and (iv) of Table 4.1, above. b) For streets less than ______ in width, the distance of the building (building line) shall be at least ______ from the centre line of……” — what value is stated?', '["7.5 m","10 m","5 m","2.5 m"]', 2, 'Clause 5.6.2.1.1 (GHBC-C-001391, page 251): subject to a minimum of 1.8m for cases (ii), (iii) and (iv) of Table 4.1, above. b) For streets less than 7.5m in width, the distance of the building (building line) shall be at least 5m from the centre line of the street See 5.3.3.5.', 'standard', 'GHBC-C-001391', 'GHBC-REQ-003709', 251, '48a339a23b13d7ddb3c3985746e78e76b8039ca0bcc1104cc2616eafe8e0bcdc', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ba8015e3b3e720ca', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.1.2): “…an integral part of the site, of an average width of ______ and at no place measuring less than ______, except that in the case of a back-to-back-site, the width of the rear open space shall be ______ throughout.…” — what value is stated?', '["6 m","3 m","1.5 m","4.5 m"]', 1, 'Clause 5.6.2.1.2 (GHBC-C-001392, page 252): a)  Every residential building shall have a rear open space, forming an integral part of the site, of an average width of 3m and at no place measuring less than 1.8m, except that in the case of a back-to-back-site, the width of the rear open space shall be 3m throughout.', 'study', 'GHBC-C-001392', 'GHBC-REQ-003711', 252, 'a8b5cedd50fb41d1036087982f4c9f46d17ea58bab971073298aaca9b67ff4a2', 'requires_review', 0);
