INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cf8ce18b45581a04', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.1.2): “…For plots of depth less than ______, for buildings up to ______ height, the rear open space may be reduced to ______. b) Rear Open Space to Extend Throughout the Rear Wall – The rear open space shall be co-extensive……” — what value is stated?', '["1.5 m","0.75 m","2.25 m","3 m"]', 0, 'Clause 5.6.2.1.2 (GHBC-C-001392, page 252): For plots of depth less than 9m, for buildings up to 7, in height, the rear open space may be reduced to 1.5m. b) Rear Open Space to Extend Throughout the Rear Wall – The rear open space shall be co-extensive with the entire face of the rear wall.', 'study', 'GHBC-C-001392', 'GHBC-REQ-003713', 252, '37a61aaf8f8e7796be94da6b95ff0783eedd179986febaf97148b3e65f1fd40e', 'requires_review', 0);
