INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8749079b0487b3fc', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.1.3): “…NOTE: For detached residential buildings up to ______ in height on plots with a frontage less than ______, one of the side open spaces may be reduced to ______.…” — what value is stated?', '["7 m","3.5 m","10.2 m","13.8 m"]', 0, 'Clause 5.6.2.1.3 (GHBC-C-001393, page 252): NOTE: For detached residential buildings up to 7m in height on plots with a frontage less than 12m, one of the side open spaces may be reduced to 1.5m.', 'study', 'GHBC-C-001393', 'GHBC-REQ-003717', 252, 'bb356fa94b27ca52648858a54d79f754177c834437f795f76421c7dce72ea592', 'requires_review', 0);
