INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6aba0d5150ff69a8', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.3.2): “…open spaces shall be as below: a) up to a height of ______, with one set-back, the open spaces at the ground level, shall made good to satisfy 5.6.2.3.1, through the set-backs at the upper levels; these set-backs shall……” — what value is stated?', '["49 m","24 m","12 m","35 m"]', 1, 'Clause 5.6.2.3.2 (GHBC-C-001397, page 253): For tower-like structures, as an alternative to 5.6.2.3., open spaces shall be as below: a)  up to a height of 24m, with one set-back, the open spaces at the ground level, shall made good to satisfy 5.6.2.3.1,  through the set-backs at the upper levels; these set-backs shall not be accessible from individual rooms/flats at these levels.', 'study', 'GHBC-C-001397', 'GHBC-REQ-003737', 253, 'd3ed409f4b70e414116c72485a63a2ceb692ae686a86bc4b87112b97a1a92fc5', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2f72b2057737b0c4', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.5): “…abut on an inner courtyard, whose minimum width shall be ______.…” — what value is stated?', '["6 m","3 m","1.5 m","4.5 m"]', 1, 'Clause 5.6.2.5 (GHBC-C-001399, page 253): a) Inner Courtyard – In case the whole of one side of every room excepting bath, WC and store room is not abutting on either the front, rear or side(s) open spaces, it shall abut on an inner courtyard, whose minimum width shall be 3m.', 'standard', 'GHBC-C-001399', 'GHBC-REQ-003739', 253, 'a276f675cf157090fb1d59eff8f6b90dc073b013cc67a9569279152320475f77', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e9c6feeb6d163a3a', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.5): “…values given below: Note 1 – For buildings of height above ______, a mechanical ventilation system shall be installed besides the provision of minimum ventilation shaft.…” — what value is stated?', '["30 m","15 m","45 m","60 m"]', 0, 'Clause 5.6.2.5 (GHBC-C-001399, page 253): Where only water closet and bath room are abutting on the interior courtyard, the size of the interior courtyard shall be in line with the provision for ventilation shaft as given in Clause 5.6.2.5(b)) b) Ventilation Shaft – For ventilating the spaces for water closets and bath rooms, if not opening on to front, side, rear and interior open spaces, these shall open on to the ventilation shaft, the', 'study', 'GHBC-C-001399', 'GHBC-REQ-003743', 253, '587ad23d84ef6777fa4694f11509c5be9346960be77fe5c7e436cddf64862e80', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ce377f4285317199', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.5): “…(as distinguished from its depth) shall be not less than ______.…” — what value is stated?', '["3.6 m","4.8 m","2.4 m","1.2 m"]', 2, 'Clause 5.6.2.5 (GHBC-C-001399, page 253): Note 2 – For fully air-conditioned residential buildings for lodging purposes, the ventilation shaft need not be insisted upon, provided the air-conditioning system works in an uninterrupted manner, also, provided there is an alternative source of power supply. c)  Outer Courtyard – The minimum width of the outer courtyard (as distinguished from its depth) shall be not less than 2.4m.', 'standard', 'GHBC-C-001399', 'GHBC-REQ-003744', 253, '1d4214c14a4d7cc5b8e50c7f3c2280e45ce956e0b618e4ba3f36135fd4b5663d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d874a3f126be3846', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.5): “…If the width of the outer courtyard is less than ______, it shall be treated as a notch and the provisions of outer courtyard shall not apply.…” — what value is stated?', '["2.4 m","1.2 m","3.6 m","4.8 m"]', 0, 'Clause 5.6.2.5 (GHBC-C-001399, page 253): If the width of the outer courtyard is less than 2.4m, it shall be treated as a notch and the provisions of outer courtyard shall not apply.', 'study', 'GHBC-C-001399', 'GHBC-REQ-003745', 253, '96efd4fd17b2c4116cb744377edbe62bf7389855089007d2008767174d819f51', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-332f92c13aa7aaa5', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.2.6.2): “…space shall be erected or raised to a height of more than ______.…” — what value is stated?', '["3 m","4 m","2 m","1 m"]', 2, 'Clause 5.6.2.6.2 (GHBC-C-001402, page 254): No boundary wall between such joint open air space shall be erected or raised to a height of more than 2.0m.', 'standard', 'GHBC-C-001402', 'GHBC-REQ-003751', 254, '817e46afb20192b3ed1f4749322fd9fb2e39c166081c7366b50cf17c81bbe494', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-69b1436ec11114ce', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______; b) Institutional Buildings – The open spaces around the building shall be not less than ______; and c) Assembly Buildings – The open space at front……” — what value is stated?', '["6 m","3 m","9 m","12 m"]', 0, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): shall be as below: a) Educational Buildings – Except for nursery schools, the open spaces around the building shall be not less than 6m; b) Institutional Buildings – The open spaces around the building shall be not less than 6m; and c) Assembly Buildings – The open space at front shall be not less than 12m and the other open spaces around the building shall be not less than 6m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003752', 254, '64465484b63cc15ec34b1c1ab1522fc581720aed863fed93493b3ea200a36b37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-69b1436ec11114ce', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______; b) Institutional Buildings – The open spaces around the building shall be not less than ______; and c) Assembly Buildings – The open space at front……” — what value is stated?', '["6 m","3 m","9 m","12 m"]', 0, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): shall be as below: a) Educational Buildings – Except for nursery schools, the open spaces around the building shall be not less than 6m; b) Institutional Buildings – The open spaces around the building shall be not less than 6m; and c) Assembly Buildings – The open space at front shall be not less than 12m and the other open spaces around the building shall be not less than 6m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003752', 254, '64465484b63cc15ec34b1c1ab1522fc581720aed863fed93493b3ea200a36b37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-69b1436ec11114ce', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______; b) Institutional Buildings – The open spaces around the building shall be not less than ______; and c) Assembly Buildings – The open space at front……” — what value is stated?', '["12 m","6 m","18 m","24 m"]', 0, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): shall be as below: a) Educational Buildings – Except for nursery schools, the open spaces around the building shall be not less than 6m; b) Institutional Buildings – The open spaces around the building shall be not less than 6m; and c) Assembly Buildings – The open space at front shall be not less than 12m and the other open spaces around the building shall be not less than 6m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003752', 254, '64465484b63cc15ec34b1c1ab1522fc581720aed863fed93493b3ea200a36b37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-69b1436ec11114ce', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______; b) Institutional Buildings – The open spaces around the building shall be not less than ______; and c) Assembly Buildings – The open space at front……” — what value is stated?', '["6 m","3 m","9 m","12 m"]', 0, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): shall be as below: a) Educational Buildings – Except for nursery schools, the open spaces around the building shall be not less than 6m; b) Institutional Buildings – The open spaces around the building shall be not less than 6m; and c) Assembly Buildings – The open space at front shall be not less than 12m and the other open spaces around the building shall be not less than 6m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003752', 254, '64465484b63cc15ec34b1c1ab1522fc581720aed863fed93493b3ea200a36b37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f01c62bd51e3b8ca', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______. d) Business______ercantile and Storage Buildings – The open spaces around the building shall be not less than ______.…” — what value is stated?', '["18 m","24 m","12 m","6 m"]', 2, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): Note – However, if assembly buildings are permitted in purely residential zones, the open spaces around the building shall be not less than 12m. d) Business, Mercantile and Storage Buildings – The open spaces around the building shall be not less than 4.5m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003753', 254, '17c276dec1da6fafc3a77e5d40cf3d367faabc0a2ae8193f1f862b7f30169f25', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f01c62bd51e3b8ca', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…the open spaces around the building shall be not less than ______. d) Business______ercantile and Storage Buildings – The open spaces around the building shall be not less than ______.…” — what value is stated?', '["7 m","9 m","4.5 m","2.25 m"]', 2, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): Note – However, if assembly buildings are permitted in purely residential zones, the open spaces around the building shall be not less than 12m. d) Business, Mercantile and Storage Buildings – The open spaces around the building shall be not less than 4.5m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003753', 254, '17c276dec1da6fafc3a77e5d40cf3d367faabc0a2ae8193f1f862b7f30169f25', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c14cfeedd84ff724', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…The open spaces around the building shall be not less than ______ for heights up to ______, with an increase of the open spaces of ______ for every increase of ______ or fraction thereof in height above ______.…” — what value is stated?', '["2.25 m","7 m","9 m","4.5 m"]', 3, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): Where these occur in a purely residential zone or in a residential with shops line zone, the open spaces may be relaxed. e) Industrial Buildings – The open spaces around the building shall be not less than 4.5m for heights up to 16m, with an increase of the open spaces of 0.25m for every increase of 1m or fraction thereof in height above 16m.', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003754', 254, 'd5f301551121c471fdaa247f3849d2318dc8a7317d51089c4a9157d814e5f261', 'extracted', 1);
