INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ba60b6434a8ee27c', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…industrial plots in the city, namely plots less than ______ in width______ the city, namely plots less than ______ in width, and with appropriate setbacks from certain streets and highways, shall be applicable. f)……” — what value is stated?', '["7.5 m","22.7 m","30 m","15 m"]', 3, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): Note – Special rules for narrow industrial plots in the city, namely plots less than 15m in width, in the city, namely plots less than 15m in width, and with appropriate setbacks from certain streets and highways, shall be applicable. f) Hazardous Occupancies – The open spaces around the building shall be as specified for industrial buildings (see 5.6.2.1(e)).', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003755', 254, 'd1bbfe7460863b3f2719e3b28dbb45c4e147c1eaaa4dd8649a9a476c21a677b9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ba60b6434a8ee27c', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.3.1): “…industrial plots in the city, namely plots less than ______ in width______ the city, namely plots less than ______ in width, and with appropriate setbacks from certain streets and highways, shall be applicable. f)……” — what value is stated?', '["7.5 m","22.7 m","30 m","15 m"]', 3, 'Clause 5.6.3.1 (GHBC-C-001404, page 254): Note – Special rules for narrow industrial plots in the city, namely plots less than 15m in width, in the city, namely plots less than 15m in width, and with appropriate setbacks from certain streets and highways, shall be applicable. f) Hazardous Occupancies – The open spaces around the building shall be as specified for industrial buildings (see 5.6.2.1(e)).', 'standard', 'GHBC-C-001404', 'GHBC-REQ-003755', 254, 'd1bbfe7460863b3f2719e3b28dbb45c4e147c1eaaa4dd8649a9a476c21a677b9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0924638bee44dffa', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.6.4.1): “…as below: a) cornice, roof or weather shade not more than ______ wide; b) sunshades over windows/ventilators or other openings not more than ______ wide; c) canopy at first floor level, but not to be used as a sit out……” — what value is stated?', '["0.75 m","0.38 m","1.12 m","1.5 m"]', 0, 'Clause 5.6.4.1 (GHBC-C-001406, page 254): Every open space provided either interior or exterior shall be kept free from any erection thereon and shall be open to the sky, except as below: a) cornice, roof or weather shade not more than 0.75m wide; b) sunshades over windows/ventilators or other openings not more than 0.75m wide; c) canopy at first floor level, but not to be used as a sit out with clearance of 1.5m between the plot boundary', 'standard', 'GHBC-C-001406', 'GHBC-REQ-003756', 254, 'c32ebbf9cb823afd6ee76d1389816f820e62d39af30b10f50811e7fdcc7da832', 'extracted', 1);
