INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f131db31eae4043c', NULL, NULL, 'threshold', 5, 'GS 1207:2018 Part 5 (Clause 5.16.2.1): “…have an initial solar reflectance value of not less than ______ accordance with ASTM E1918 or ASTM C1549.…” — what value is stated?', '["0.15 in","0.45 in","0.6 in","0.3 in"]', 3, 'Clause 5.16.2.1 (GHBC-C-001487, page 273): Hardscape materials shall have an initial solar reflectance value of not less than 0.30 in accordance with ASTM E1918 or ASTM C1549.', 'standard', 'GHBC-C-001487', 'GHBC-REQ-004218', 273, '03b82fad6cebb223004135b2652e74b461eb3774ce421461a606f7ebbea82983', 'extracted', 1);
