INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e1497ed0bfeba5aa', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.4.3): “…non-combustible materials and shall not extend more than ______ above the allowable building height where of combustible materials (Part 16 for additional requirements).…” — what value is stated?', '["9144 mm","10000 mm","6096 mm","3048 mm"]', 2, 'Clause 6.4.3 (GHBC-C-001512, page 279): EXCEPTIONS: Towers, spires, steeples and other roof structures shall be constructed of materials consistent with the required type of construction of the building except where other construction is permitted by Clause 16.10.2.4. Such structures shall not be used for habitation or storage. The structures shall be unlimited in height where of non-combustible materials and shall not extend more than ', 'study', 'GHBC-C-001512', 'GHBC-REQ-004391', 279, '1f28dccd6a7eb9fcaa7eaee798776e776e0d6bd0e52b2fc90024307b974f5c8d', 'requires_review', 0);
