INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1ed6d106a4dd63fb', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.2.1): “…(see Table 6.5.1) and of Type 1 construction shall be ______.…” — what value is stated?', '["9 m","4.5 m","13.2 m","18 m"]', 0, 'Clause 6.5.2.1 (GHBC-C-001516, page 283): The minimum fire separation on all sides of buildings of unlimited areas (see Table 6.5.1) and of Type 1 construction shall be 9m.', 'standard', 'GHBC-C-001516', 'GHBC-REQ-004409', 283, '01bf88880e3f613de26b48f4a0ae839845b7255cafc63e07fde61a1e341e7472', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d1953ed77183ad49', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.3): “…fronting on a street or public space not less than ______ in width accessible to a public street.…” — what value is stated?', '["13.2 m","18 m","9 m","4.5 m"]', 2, 'Clause 6.5.3 (GHBC-C-001517, page 283): The area limits shall apply to all buildings fronting on a street or public space not less than 9m in width accessible to a public street.', 'standard', 'GHBC-C-001517', 'GHBC-REQ-004410', 283, '98d5f427e9777215a2bcb34bc24688a472df196709ce4080178de4351b259008', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8eaff7d59654b42e', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.4.1): “…street and may be continued to this height to a depth of ______ along the narrower street subject to conformity of this Code and…” — what value is stated?', '["12 m","35 m","49 m","24 m"]', 3, 'Clause 6.5.4.1 (GHBC-C-001519, page 283): b) if a building abuts on two or more streets of different widths, the building shall be deemed to face upon the street that has the greater width and the height of the building shall be regulated by the width of that street and may be continued to this height to a depth of 24m along the narrower street subject to conformity of this Code and', 'standard', 'GHBC-C-001519', 'GHBC-REQ-004414', 283, '84ecb260f796361891b16aae33215b376ef8673c6ba74d21256d7cdd65e8c159', 'extracted', 1);
