INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c6325f51c70c4afc', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.4.2.1): “…and d) chimneys and parapet walls not exceeding ______ in height.…” — what value is stated?', '["0.5 m","1.5 m","2 m","1 m"]', 3, 'Clause 6.5.4.2.1 (GHBC-C-001521, page 283): a) roofs tanks and their supports; b) ventilating, airconditioning, lift rooms and similar service equipment; c) roof structures other than pent-houses; and d) chimneys and parapet walls not exceeding 1m in height.', 'standard', 'GHBC-C-001521', 'GHBC-REQ-004418', 283, 'a78effba4aa045cab3cf15aa2f5d5bd7562fa78cbb0fa49d37c8a18a2c44de9a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c0451dcb46110144', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.4.2.1): “…cabin or substation, watchman‘s booth of maximum size of ______ with minimum width or b) diameter of ______, pump house, garbage shaft, space required for location of fire hydrants, electric fittings and water tank. c)……” — what value is stated?', '["3.2 m2","1.6 m2","0.77 m2","2.32 m2"]', 1, 'Clause 6.5.4.2.1 (GHBC-C-001521, page 283): a) a basement or cellar and space under a building constructed on stilts and used as a parking space, and air-conditioning plant room used as accessory to the principal use; electric cabin or substation, watchman‘s booth of maximum size of 1.6m2 with minimum width or b) diameter of 1.2m, pump house, garbage shaft, space required for location of fire hydrants, electric fittings and water tank. c) p', 'standard', 'GHBC-C-001521', 'GHBC-REQ-004425', 283, 'acf6578fdfcf78048024e22c42c4a77add9fa4a479c292016f7cd923dc9d3847', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-eade7d8d3e7feda5', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.4.2.1): “…cabin or substation, watchman‘s booth of maximum size of ______ with minimum width or b) diameter of ______, pump house, garbage shaft, space required for location of fire hydrants, electric fittings and water tank. c)……” — what value is stated?', '["1.8 m","2.4 m","1.2 m","0.6 m"]', 2, 'Clause 6.5.4.2.1 (GHBC-C-001521, page 283): a) a basement or cellar and space under a building constructed on stilts and used as a parking space, and air-conditioning plant room used as accessory to the principal use; electric cabin or substation, watchman‘s booth of maximum size of 1.6m2 with minimum width or b) diameter of 1.2m, pump house, garbage shaft, space required for location of fire hydrants, electric fittings and water tank. c) p', 'standard', 'GHBC-C-001521', 'GHBC-REQ-004425', 283, 'acf6578fdfcf78048024e22c42c4a77add9fa4a479c292016f7cd923dc9d3847', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8d72f2178e5e575c', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.5.4.2.2): “…2 and Type 3 construction designed for industrial, business______ercantile, low or moderate hazard storage occupancies may be erected ______ higher than specified in Table 6.5.1 when equipped with an approved one-source……” — what value is stated?', '["3 m","9 m","12 m","6 m"]', 3, 'Clause 6.5.4.2.2 (GHBC-C-001522, page 284): sprinkler equipment is a requirement in accordance with Part 3 Use and Occupancy, all structures of Type 1, Type 2 and Type 3 construction designed for industrial, business, mercantile, low or moderate hazard storage occupancies may be erected 6m higher than specified in Table 6.5.1 when equipped with an approved one-source automatic sprinkler system.', 'standard', 'GHBC-C-001522', 'GHBC-REQ-004427', 284, '2b0e260c640c4308b4269706cbf321abae1c888dcfb1d5cefad5d679545d20ec', 'extracted', 1);
