INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-588edf138b69fe15', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.10): “…The chimneys shall be built at least ______ above flat roofs, provided the top of the chimney is not below the top of the adjacent parapet wall.…” — what value is stated?', '["1.8 m","0.9 m","0.45 m","1.3 m"]', 1, 'Clause 6.6.10 (GHBC-C-001566, page 288): The chimneys shall be built at least 0.9m above flat roofs, provided the top of the chimney is not below the top of the adjacent parapet wall.', 'standard', 'GHBC-C-001566', 'GHBC-REQ-004496', 288, 'b39dc3b3256310da938e30447537fe703c44c81baffe22fb6899cfacd8ac329f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1caa8188bb401f79', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.10): “…of sloping roofs, the chimney top shall not be less than ______ above the ridge of the roof in which the chimney penetrates.…” — what value is stated?', '["0.3 m","0.9 m","1.2 m","0.6 m"]', 3, 'Clause 6.6.10 (GHBC-C-001566, page 288): In the case of sloping roofs, the chimney top shall not be less than 0.6m above the ridge of the roof in which the chimney penetrates.', 'study', 'GHBC-C-001566', 'GHBC-REQ-004497', 288, '21495781b44c54baad2bf2da3ca393667b75ed4697dcd1b03230a4bc5908c723', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6876aca347df8206', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.11): “…terraces, balcony, verandah, etc. shall not be less than ______ and not more than ______ in height from the finished floor level.…” — what value is stated?', '["1.05 m","0.51 m","1.5 m","2.1 m"]', 0, 'Clause 6.6.11 (GHBC-C-001567, page 288): Parapet walls and handrails provided on the edges of roof terraces, balcony, verandah, etc. shall not be less than 1.05m and not more than 1.20m in height from the finished floor level.', 'study', 'GHBC-C-001567', 'GHBC-REQ-004498', 288, 'b53615d9ea06ee2ee80a61d5685c21ba5aa6d6553582105a9e3501200a6221ae', 'requires_review', 0);
