INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ce3d2587f88f9a6b', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.12): “…the divided space of any floor shall not be less than ______ and the distance from the farthest space in a cabin to any exit shall not be more than ______.…” — what value is stated?', '["0.75 m","0.38 m","1.12 m","1.5 m"]', 0, 'Clause 6.6.12 (GHBC-C-001568, page 288): The clear passages within the divided space of any floor shall not be less than 0.75m and the distance from the farthest space in a cabin to any exit shall not be more than 18.5m.', 'study', 'GHBC-C-001568', 'GHBC-REQ-004500', 288, '7a3aa128b41d9c2e082bd2078456ef38196eecf65dbe42aa1ad4f306f6ed5786', 'requires_review', 0);
