INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e5afeb8ce95b1cb5', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.14.2): “…b) be constructed to a height not less than ______ above the surrounding ground level, to form a parapet or kerb and to prevent surface water from flowing into well, and shall be surrounded with a paving constructed of……” — what value is stated?', '["0.5 m","1.5 m","2 m","1 m"]', 3, 'Clause 6.6.14.2 (GHBC-C-001573, page 289): b) be constructed to a height not less than 1m above the surrounding ground level, to form a parapet or kerb and to prevent surface water from flowing into well, and shall be surrounded with a paving constructed of impervious material which shall extend for a distance of not less than 1.8m in every direction from the parapet from the kerb forming the well head and the upper surface of such a pavin', 'standard', 'GHBC-C-001573', 'GHBC-REQ-004515', 289, '73cb437ed19949158f3d73d4caca76f587fdbc026288d7f668329eb4c0f38239', 'extracted', 1);
