INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-018dccda06a10d5c', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.14.2): “…the well rendered impervious for a depth of not less than ______ measured from the level of the…” — what value is stated?', '["0.9 m","2.7 m","3.6 m","1.8 m"]', 3, 'Clause 6.6.14.2 (GHBC-C-001573, page 289): d) have the interior surface of the lining or walls of the well rendered impervious for a depth of not less than 1.8m measured from the level of the', 'study', 'GHBC-C-001573', 'GHBC-REQ-004518', 289, '1ed5d9f20b2b444975be7279d29816225c693fcb72623670a9292628bb02d05e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-37a0b8a8fc94323c', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.1): “…A subsoil dispersion system shall not be closer than ______ from any source of drinking water, such as well, to mitigate the possibility of bacterial pollution of water supply.…” — what value is stated?', '["35 m","18 m","9 m","28 m"]', 1, 'Clause 6.6.15.1 (GHBC-C-001575, page 289): Location of Septic Tanks and Subsurface Absorption Systems A subsoil dispersion system shall not be closer than 18m from any source of drinking water, such as well, to mitigate the possibility of bacterial pollution of water supply.', 'study', 'GHBC-C-001575', 'GHBC-REQ-004521', 289, 'cb7aef850c39bdf67c2f76f1f1b3275e12c93d9415f52b754150ddc123320c68', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bcd14ed40b42a45d', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.1): “…building as economically feasible but not closer than ______, to avoid damage to the structures.…” — what value is stated?', '["6 m","3 m","9 m","12 m"]', 0, 'Clause 6.6.15.1 (GHBC-C-001575, page 289): It shall also be far removed from the nearest habitable building as economically feasible but not closer than 6m, to avoid damage to the structures.', 'standard', 'GHBC-C-001575', 'GHBC-REQ-004522', 289, 'e9e5fb7e76224304ce2212c6340f9ff336d16a5728ab364694c431bab7fdf4ad', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0181ab388b0aea1f', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…Septic Tanks – Septic tanks shall have a minimum width of ______, a minimum depth of ______ below the water level and a minimum liquid capacity of ______3.…” — what value is stated?', '["1500 mm","750 mm","381 mm","1118 mm"]', 1, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): a)  Dimensions of Septic Tanks – Septic tanks shall have a minimum width of 750mm, a minimum depth of 1 m below the water level and a minimum liquid capacity of 1m3.', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004523', 289, '9727ca2239843a653343eef42b06a10d6b434ccff409415979972a9bb37d156d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3bfe6aafc0cebc6c', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…Septic Tanks – Septic tanks shall have a minimum width of ______, a minimum depth of ______ below the water level and a minimum liquid capacity of ______3.…” — what value is stated?', '["2 m","1 m","0.5 m","1.5 m"]', 1, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): a)  Dimensions of Septic Tanks – Septic tanks shall have a minimum width of 750mm, a minimum depth of 1 m below the water level and a minimum liquid capacity of 1m3.', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004523', 289, '9727ca2239843a653343eef42b06a10d6b434ccff409415979972a9bb37d156d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-24ce28ac9380c644', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…d) The minimum nominal diameter of the pipe shall be ______.…” — what value is stated?', '["100 mm","50 mm","150 mm","200 mm"]', 0, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): The length of tanks shall be 2 to 4 times the width. b)  Septic tanks may be constructed of brickwork, stone masonry, concrete or other suitable materials as approved by the Authority. c) Under no circumstances shall effluent from a septic tank be allowed into an open channel drain or body of water without adequate treatment. d) The minimum nominal diameter of the pipe shall be 100 mm.', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004524', 289, 'f3778fd755cad1a8f620037cbcbaf5528301675c7c7a8cefc3c162c468e2b75a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bb3adf3cd4212eea', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…the ventilating pipe may extend to a height of about ______, when the septic tank is at least ______ away from the nearest building and to a height of ______ above the top of the building when it is located closer than……” — what value is stated?', '["4 m","2 m","1 m","3 m"]', 1, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): Generally, the ventilating pipe may extend to a height of about 2m, when the septic tank is at least 15 m away from the nearest building and to a height of 2m above the top of the building when it is located closer than 15m; g) When the disposal of septic tank effluent is to a seepage pit, the seepage pit may be of any suitable shape with the least crossclauseal dimension of 900mm and not less tha', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004529', 289, '7cad52ff35e17850d6b0c31045476020ec395ef5c59470df3e1390f71326e32c', 'extracted', 1);
