INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ccfeafefb17fd37a', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…The inlet pipe may be taken down a depth of ______ from the top as an antimosquito measure; and h) When the disposal of the septic tank effluent is to a dispersion trench, the dispersion trench shall be 500 to ______……” — what value is stated?', '["1370 mm","1800 mm","900 mm","450 mm"]', 2, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): The inlet pipe may be taken down a depth of 900mm from the top as an antimosquito measure; and h) When the disposal of the septic tank effluent is to a dispersion trench, the dispersion trench shall be 500 to 1000mm deep and 300 to 1000mm wide excavated to a slight gradient and shall be provided with 150 to 250mm of washed gravel or crushed stones.', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004535', 289, '130a6794531df48ff524bab5d7b9c5100aac20c1e9140d049d46f66bc89f1f0e', 'extracted', 1);
