INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e9329dea2f568872', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…and shall have a minimum internal diameter of 75 to ______.…” — what value is stated?', '["150 mm","200 mm","100 mm","50 mm"]', 2, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): Open jointed pipes placed inside the trench shall be made of unglazed earthenware clay or concrete and shall have a minimum internal diameter of 75 to 100 mm.', 'standard', 'GHBC-C-001576', 'GHBC-REQ-004536', 289, '4b13564c07737cb821e67cf4a6acb4f9606c40d52c248dde715b280e91c9079e', 'extracted', 1);
