INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-81555caf21ae2eda', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.15.2): “…Each dispersion trench shall not be longer than ______ and trenches shall not be placed closer than ______.…” — what value is stated?', '["1.8 m","0.9 m","2.7 m","3.6 m"]', 0, 'Clause 6.6.15.2 (GHBC-C-001576, page 289): Each dispersion trench shall not be longer than 30m and trenches shall not be placed closer than 1.8 m.', 'study', 'GHBC-C-001576', 'GHBC-REQ-004537', 289, '0375e0ae90d312dfa350f8e01a5663c88ddcb8d7b438cd6acca11ec262600d72', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b51ab696770f6c43', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.16): “…In the case of multi-storeyed______ulti-family dwelling apartments constructed by existing and proposed Real Estate or Apartment Owners Associations, Limited companies and proposed housing societies, an office-cumletter……” — what value is stated?', '["3 m","1.5 m","4.5 m","6 m"]', 0, 'Clause 6.6.16 (GHBC-C-001577, page 290): In the case of multi-storeyed, multi-family dwelling apartments constructed by existing and proposed Real Estate or Apartment Owners Associations, Limited companies and proposed housing societies, an office-cumletter box room of dimension 3.6 x 3m shall be provided on the ground floor.', 'standard', 'GHBC-C-001577', 'GHBC-REQ-004538', 290, '7c6d8ea2245bdffe958b18428fd64d0f7c1cfa87110620c0e2c2ba9214af5c85', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-27db88eac500e627', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.16): “…maximum size of the office-cum-letter box room shall be ______.…” — what value is stated?', '["37 m2","20 m2","10 m2","30 m2"]', 1, 'Clause 6.6.16 (GHBC-C-001577, page 290): In case the number of flats is more than 20, the maximum size of the office-cum-letter box room shall be 20 m2.', 'standard', 'GHBC-C-001577', 'GHBC-REQ-004539', 290, '047afe1ab5ae7aa5ee667482e14818bde441716ece201c41811d06933d8096bb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5be66ea8b350fe58', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.6.17): “…For all buildings above ______ in height and in special occupancies, like educational, assembly______stitutional______dustrial, storage, hazardous and mixed occupancies with any of the aforesaid occupancies having area……” — what value is stated?', '["22.7 m","30 m","15 m","7.5 m"]', 2, 'Clause 6.6.17 (GHBC-C-001579, page 290): For all buildings above 15m in height and in special occupancies, like educational, assembly, institutional, industrial, storage, hazardous and mixed occupancies with any of the aforesaid occupancies having area more than 500 m2 on each floor, provision shall be made for an independent and ventilated meter (service) room, as per requirements of electric (service) supply undertakings on the ground ', 'standard', 'GHBC-C-001579', 'GHBC-REQ-004541', 290, '8015fa42b1a7a82678d6793097785933b365225acaf65a634db7d6b6ccf51518', 'extracted', 1);
