INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2a68aeb39604f7fb', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.10.9): “…The area of a Group B, F, H-______ or S building not more than two stories above grade plane shall not be limited where the building is equipped throughout with an automatic sprinkler system in accordance with Clause……” — what value is stated?', '["-4 m","-3.5 m","-5 m","-3 m"]', 2, 'Clause 6.10.9 (GHBC-C-001644, page 303): The area of a Group B, F, H-5, M or S building not more than two stories above grade plane shall not be limited where the building is equipped throughout with an automatic sprinkler system in accordance with Clause 10.33.1.1, and is surrounded and adjoined by public ways or yards not less than 18 288 mm (60 feet) in width, provided all of the following criteria are met:', 'study', 'GHBC-C-001644', 'GHBC-REQ-004798', 303, 'ee6e38a59236de9b069b8fbe540aeab7849fed7ad92a44ba20f6ce947e91dada', 'requires_review', 0);
