INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-be2cb5fede9d5bd3', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause null): “…For SI: 1 square foot = ______ , 1 pound per square inch (psi) = 6.9 kPa, 1 British thermal unit (Btu) per hour = 0.293 watts,1 horsepower = 746 watts, 1 gallon = 3.785 L, 1 cubic foot = ______…” — what value is stated?', '["0.19 m2","0.2 m2","0.0929 m2","0.035 m2"]', 2, 'Clause null (GHBC-C-001665, page 307): For SI: 1 square foot = 0.0929 m2 , 1 pound per square inch (psi) = 6.9 kPa, 1 British thermal unit (Btu) per hour = 0.293 watts,1 horsepower = 746 watts, 1 gallon = 3.785 L, 1 cubic foot = 0.0283 m', 'study', 'GHBC-C-001665', 'GHBC-REQ-004877', 307, '6ec26a93938bf458ec57c8fbb4efc21c5d3c1034d4f31ffb11e34d093efe07d4', 'requires_review', 0);
