INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-86348fe38c05235f', NULL, NULL, 'threshold', 6, 'GS 1207:2018 Part 6 (Clause 6.13.3): “…room and toilet room having a total area of not more than ______ and mechanical equipment rooms incidental to the operation of the building.…” — what value is stated?', '["139.4 m2","186 m2","93 m2","46.5 m2"]', 2, 'Clause 6.13.3 (GHBC-C-001674, page 309): The Group S-2 enclosed parking garage is used exclusively for the parking or storage of private motor vehicles, but shall be permitted to contain an office, waiting room and toilet room having a total area of not more than 93 m2 (1,000 square feet) and mechanical equipment rooms incidental to the operation of the building.', 'standard', 'GHBC-C-001674', 'GHBC-REQ-004931', 309, '9290645d7aa5f4f3f5bd215f07e6f33665f314790162afee532e9e271a25b328', 'extracted', 1);
