INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e9bf341e33582e6b', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.4.7): “…reinforcement ties are permitted to project not more than ______ into the protection.…” — what value is stated?', '["12.7 mm","6.4 mm","19.05 mm","25.4 mm"]', 0, 'Clause 8.4.7 (GHBC-C-001743, page 322): Thickness of protection for concrete or masonry reinforcement shall be measured to the outside of the reinforcement except that stirrups and spiral reinforcement ties are permitted to project not more than 12.7 mm (0.5-inch) into the protection.', 'standard', 'GHBC-C-001743', 'GHBC-REQ-005172', 322, 'e3ac3c3d63b1524c58d6be6cb92d197f6f17ca094d0de10687acfa97b975e746', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-03745dc083dacdd3', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.4.9): “…adequate to provide full protection, but not less than ______ from the finished floor.…” — what value is stated?', '["762 mm","2286 mm","3048 mm","1524 mm"]', 3, 'Clause 8.4.9 (GHBC-C-001745, page 323): Where the fire protective covering of a structural member is subject to impact damage from moving vehicles, the handling of merchandise or other activity, the fire protective covering shall be protected by corner guards or by a substantial jacket of metal or other noncombustible material to a height adequate to provide full protection, but not less than 1524 mm (5 feet) from the finished floor.', 'standard', 'GHBC-C-001745', 'GHBC-REQ-005174', 323, '4a1282afe49f1e52f4654b0ee73d8964012c9b3d33c6a2ca1df88cd13ca2b0f3', 'extracted', 1);
