INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-98bcfd6692b9156c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.1): “…plot or dedicated for public use, shall be not less than ______ in width and shall have access from a street by a posted fire lane in accordance with the Ghana Fire Code.…” — what value is stated?', '["7620 mm","9144 mm","4572 mm","16000 mm"]', 1, 'Clause 8.5.8.1 (GHBC-C-001768, page 328): The unoccupied space shall be on the same plot or dedicated for public use, shall be not less than 30 feet (9144 mm) in width and shall have access from a street by a posted fire lane in accordance with the Ghana Fire Code.', 'standard', 'GHBC-C-001768', 'GHBC-REQ-005280', 328, 'e86e1b16b395a25ce3b75cdb1158f2295e1e9100702fb141b0e3d1889dc51920', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6c747de4e63c6fa7', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.5): “…exterior of the buildings where the openings are within ______ of each other horizontally and the opening in the lower storey is not a protected opening with a fire protection rating of not less than 3/4 hour.…” — what value is stated?', '["2286 mm","3048 mm","1524 mm","762 mm"]', 2, 'Clause 8.5.8.5 (GHBC-C-001772, page 329): Openings in exterior walls in adjacent stories shall be separated vertically to protect against fire spread on the exterior of the buildings where the openings are within 1524 mm (5 feet) of each other horizontally and the opening in the lower storey is not a protected opening with a fire protection rating of not less than 3/4 hour.', 'standard', 'GHBC-C-001772', 'GHBC-REQ-005290', 329, '4131ce4ea44c8aa83980d450e69d75dd9107b87047576f54f8b04e71306c9596', 'extracted', 1);
