INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7ee58ae4581bd48c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.5): “…Such openings shall be separated vertically not less than ______ by spandrel girders, exterior walls or other similar assemblies that have a fire-resistance rating of not less than 1 hour, rated for exposure to fire……” — what value is stated?', '["1524 mm","762 mm","381 mm","1118 mm"]', 1, 'Clause 8.5.8.5 (GHBC-C-001772, page 329): Such openings shall be separated vertically not less than 914 mm (3 feet) by spandrel girders, exterior walls or other similar assemblies that have a fire-resistance rating of not less than 1 hour, rated for exposure to fire from both sides, or by flame barriers that extend horizontally not less than 762 mm (30 inches) beyond the exterior wall.', 'standard', 'GHBC-C-001772', 'GHBC-REQ-005291', 329, 'c7100f3cd86b8ec743371edbbb0869bc2a611836c0a084b12f0e005f9965e18f', 'extracted', 1);
