INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f4f2ae18c8983614', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.6): “…hour shall be provided in every opening that is less than ______ vertically above the roof of an adjacent building or structure based on assuming an imaginary line between them.…” — what value is stated?', '["2286 mm","7010 mm","9144 mm","4572 mm"]', 3, 'Clause 8.5.8.6 (GHBC-C-001773, page 329): For buildings on the same plot, opening protectives having a fire protection rating of not less than 3/4 hour shall be provided in every opening that is less than 4572 mm (15 feet) vertically above the roof of an adjacent building or structure based on assuming an imaginary line between them.', 'standard', 'GHBC-C-001773', 'GHBC-REQ-005301', 329, 'e9a6c047853bd940ecbc4db25ab6ef09016a85b1bdfa8d9bac8cd4acba635e14', 'extracted', 1);
