INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6f3d67e9f6d9133e', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.6): “…imaginary line to each building or structure are less than ______.…” — what value is stated?', '["8 feet","23 feet","30 feet","15 feet"]', 3, 'Clause 8.5.8.6 (GHBC-C-001773, page 329): The opening protectives are required where the fire separation distances from the imaginary line to each building or structure are less than 4572 mm (15 feet).', 'standard', 'GHBC-C-001773', 'GHBC-REQ-005302', 329, 'd463502d4ba306e57eb909bcc507c8ac81a90a0365b5952d0a40ade13fbbf145', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d131ff95c8e1774a', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.6): “…rating of not less than 1 hour for a minimum distance of ______ from the exterior wall facing the imaginary line and the entire length and span of the supporting elements for the fireresistance-rated roof assembly has a……” — what value is stated?', '["3048 mm","1524 mm","4572 mm","6096 mm"]', 0, 'Clause 8.5.8.6 (GHBC-C-001773, page 329): Opening protectives are not required where the roof assembly of the adjacent building or structure has a fire-resistance rating of not less than 1 hour for a minimum distance of 3048 mm (10 feet) from the exterior wall facing the imaginary line and the entire length and span of the supporting elements for the fireresistance-rated roof assembly has a fire-resistance rating of not less than 1 hour.', 'standard', 'GHBC-C-001773', 'GHBC-REQ-005305', 329, 'f12200ca69dec9f9b67562fec2624b47b7c926a26bbca06b2f9f337b096f74b5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-00b68cb12c6429d2', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.8.6): “…rating of not less than 1 hour for a minimum distance of ______ from the exterior wall facing the imaginary line and the entire length and span of the supporting elements for the fireresistance-rated roof assembly has a……” — what value is stated?', '["20 feet","10 feet","5 feet","15 feet"]', 1, 'Clause 8.5.8.6 (GHBC-C-001773, page 329): Opening protectives are not required where the roof assembly of the adjacent building or structure has a fire-resistance rating of not less than 1 hour for a minimum distance of 3048 mm (10 feet) from the exterior wall facing the imaginary line and the entire length and span of the supporting elements for the fireresistance-rated roof assembly has a fire-resistance rating of not less than 1 hour.', 'standard', 'GHBC-C-001773', 'GHBC-REQ-005305', 329, 'f12200ca69dec9f9b67562fec2624b47b7c926a26bbca06b2f9f337b096f74b5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-947032c7ad8aedc2', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11): “…The building has an area of not more than ______ on any floor.…” — what value is stated?', '["186 m2","93 m2","46.5 m2","139.4 m2"]', 1, 'Clause 8.5.11 (GHBC-C-001777, page 330): The building has an area of not more than 1,000 square feet (93 m2) on any floor.', 'study', 'GHBC-C-001777', 'GHBC-REQ-005318', 330, '68cfe5b8889c500b2381c82fb15b78931bda5e1c19daa0b42f10409134c71953', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4110c2097eb92c3b', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11): “…1-hour fire-resistance-rated construction for a width of ______ for Groups R and U and ______ for other occupancies______easured from the interior side of the wall.…” — what value is stated?', '["610 mm","1830 mm","2440 mm","1220 mm"]', 3, 'Clause 8.5.11 (GHBC-C-001777, page 330): Where the roof/ceiling framing elements are parallel to the walls, such framing and elements supporting such framing shall not be of less than 1-hour fire-resistance-rated construction for a width of 1220 mm (4 feet) for Groups R and U and 3048 mm (10 feet) for other occupancies, measured from the interior side of the wall.', 'study', 'GHBC-C-001777', 'GHBC-REQ-005324', 330, '236ced3cab77dcf5f7d521e87c178edf58065a6099ce8ebd6e677dc42b6b80be', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-de87ceac09fdeac3', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11): “…1-hour fire-resistance-rated construction for a width of ______ for Groups R and U and ______ for other occupancies______easured from the interior side of the wall.…” — what value is stated?', '["4 feet","2 feet","6 feet","8 feet"]', 0, 'Clause 8.5.11 (GHBC-C-001777, page 330): Where the roof/ceiling framing elements are parallel to the walls, such framing and elements supporting such framing shall not be of less than 1-hour fire-resistance-rated construction for a width of 1220 mm (4 feet) for Groups R and U and 3048 mm (10 feet) for other occupancies, measured from the interior side of the wall.', 'study', 'GHBC-C-001777', 'GHBC-REQ-005324', 330, '236ced3cab77dcf5f7d521e87c178edf58065a6099ce8ebd6e677dc42b6b80be', 'requires_review', 0);
