INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a2abc17d93c7e4bb', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…surface, shall have noncombustible faces for the uppermost ____________cluding counterflashing and coping materials.…” — what value is stated?', '["457 mm","229 mm","686 mm","914 mm"]', 0, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): Parapets shall have the same fire-resistance rating as that required for the supporting wall, and on any side adjacent to a roof surface, shall have noncombustible faces for the uppermost 457 mm (18 inches), including counterflashing and coping materials.', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005340', 330, '256e7a58222a0f067cb4fcf60e40f32baeb7ad9dd39efd73c9e24a5b65a0d2d5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a1942e38c9881d0c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…surface, shall have noncombustible faces for the uppermost ____________cluding counterflashing and coping materials.…” — what value is stated?', '["36 in","18 in","9 in","27 in"]', 1, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): Parapets shall have the same fire-resistance rating as that required for the supporting wall, and on any side adjacent to a roof surface, shall have noncombustible faces for the uppermost 457 mm (18 inches), including counterflashing and coping materials.', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005340', 330, '256e7a58222a0f067cb4fcf60e40f32baeb7ad9dd39efd73c9e24a5b65a0d2d5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-66c005f8d7a507c5', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…The height of the parapet shall be not less than ______ above the point where the roof surface and the wall intersect.…” — what value is stated?', '["1524 mm","762 mm","381 mm","1118 mm"]', 1, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): The height of the parapet shall be not less than 762 mm (30 inches) above the point where the roof surface and the wall intersect.', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005341', 330, '883703ea6936ef50499b1494b6ab2e2baf308bd81bfd022312652a32420a6fc9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-03fa03bf2fecf10c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…The height of the parapet shall be not less than ______ above the point where the roof surface and the wall intersect.…” — what value is stated?', '["60 in","30 in","15 in","45 in"]', 1, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): The height of the parapet shall be not less than 762 mm (30 inches) above the point where the roof surface and the wall intersect.', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005341', 330, '883703ea6936ef50499b1494b6ab2e2baf308bd81bfd022312652a32420a6fc9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a3e26a32e1547a48', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…is required, but the height shall be not less than ______.…” — what value is stated?', '["762 mm","381 mm","1118 mm","1524 mm"]', 0, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): Where the roof slopes toward a parapet at a slope greater than two units vertical in 12 units horizontal (16.7percent slope), the parapet shall extend to the same height as any portion of the roof within a fire separation distance where protection of wall openings is required, but the height shall be not less than 762 mm (30 inches).', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005342', 330, '35bd2f29c7344325eca1f75b4dee968e9e71b0b042be68489a5e6f39e203d0a1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f95b3679adc66383', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.5.11.1): “…is required, but the height shall be not less than ______.…” — what value is stated?', '["15 in","45 in","60 in","30 in"]', 3, 'Clause 8.5.11.1 (GHBC-C-001778, page 330): Where the roof slopes toward a parapet at a slope greater than two units vertical in 12 units horizontal (16.7percent slope), the parapet shall extend to the same height as any portion of the roof within a fire separation distance where protection of wall openings is required, but the height shall be not less than 762 mm (30 inches).', 'standard', 'GHBC-C-001778', 'GHBC-REQ-005342', 330, '35bd2f29c7344325eca1f75b4dee968e9e71b0b042be68489a5e6f39e203d0a1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b10e5a576f2332ff', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.2): “…Ghana Fire Code, floor and roof sheathing not exceeding 3/______ thickness shall be permitted to be continuous through the wall assemblies of light frame construction.…” — what value is stated?', '["4 in","2 in","6 in","8 in"]', 0, 'Clause 8.6.2 (GHBC-C-001781, page 331): EXCEPTIONS: In Seismic Design Categories D through F, where double fire walls are used in accordance with the Ghana Fire Code, floor and roof sheathing not exceeding 3/4 inch (19.05 mm) thickness shall be permitted to be continuous through the wall assemblies of light frame construction.', 'standard', 'GHBC-C-001781', 'GHBC-REQ-005351', 331, '028446590c67f6e781fe6745a688fb16519a60b00f139f11648156c13c05e301', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-64238830dbc3b8e6', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.2): “…Ghana Fire Code, floor and roof sheathing not exceeding 3/______ thickness shall be permitted to be continuous through the wall assemblies of light frame construction.…” — what value is stated?', '["9.53 mm","29 mm","38 mm","19.05 mm"]', 3, 'Clause 8.6.2 (GHBC-C-001781, page 331): EXCEPTIONS: In Seismic Design Categories D through F, where double fire walls are used in accordance with the Ghana Fire Code, floor and roof sheathing not exceeding 3/4 inch (19.05 mm) thickness shall be permitted to be continuous through the wall assemblies of light frame construction.', 'standard', 'GHBC-C-001781', 'GHBC-REQ-005351', 331, '028446590c67f6e781fe6745a688fb16519a60b00f139f11648156c13c05e301', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f9c05e6401270736', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.5): “…wall to exterior wall and shall extend not less than ______ beyond the exterior surface of exterior walls.…” — what value is stated?', '["914 mm","457 mm","229 mm","686 mm"]', 1, 'Clause 8.6.5 (GHBC-C-001784, page 331): Fire walls shall be continuous from exterior wall to exterior wall and shall extend not less than 457 mm (18 inches) beyond the exterior surface of exterior walls.', 'standard', 'GHBC-C-001784', 'GHBC-REQ-005356', 331, '706cdcec9b4302e5a7c17414ea87ecd05df87a066848623b681be857895dd7d7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-edda8054f0888ad6', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.5): “…wall to exterior wall and shall extend not less than ______ beyond the exterior surface of exterior walls.…” — what value is stated?', '["18 in","9 in","27 in","36 in"]', 0, 'Clause 8.6.5 (GHBC-C-001784, page 331): Fire walls shall be continuous from exterior wall to exterior wall and shall extend not less than 457 mm (18 inches) beyond the exterior surface of exterior walls.', 'standard', 'GHBC-C-001784', 'GHBC-REQ-005356', 331, '706cdcec9b4302e5a7c17414ea87ecd05df87a066848623b681be857895dd7d7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7e79605bb5a49f58', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.5): “…than 1 hour for a horizontal distance of not less than ______ on both sides of the fire wall.…” — what value is stated?', '["1220 mm","610 mm","1830 mm","2440 mm"]', 0, 'Clause 8.6.5 (GHBC-C-001784, page 331): Fire walls shall be permitted to terminate at the interior surface of combustible exterior sheathing or siding provided that the exterior wall has a fire-resistance rating of not less than 1 hour for a horizontal distance of not less than 1220 mm (4 feet) on both sides of the fire wall.', 'standard', 'GHBC-C-001784', 'GHBC-REQ-005359', 331, '231a942bb77c1c532de46a50915f231dc685198bd1f424a44695dd1ba39b8fc1', 'extracted', 1);
