INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a5b20d490e5e487d', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.7): “…fire wall from opposite sides shall not have less than a ______ distance between embedded ends.…” — what value is stated?', '["153 mm","204 mm","102 mm","51 mm"]', 2, 'Clause 8.6.7 (GHBC-C-001790, page 333): Adjacent combustible members entering into a concrete or masonry fire wall from opposite sides shall not have less than a 102 mm (4inch) distance between embedded ends.', 'study', 'GHBC-C-001790', 'GHBC-REQ-005426', 333, 'e1e5c73953a02893e5486a412a3dcba42f714eaad88e2fcc9c0f1cdfe833ea34', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-06d381df2e85c2e0', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.7): “…fire wall from opposite sides shall not have less than a ______ distance between embedded ends.…” — what value is stated?', '["2 in","6 in","8 in","4 in"]', 3, 'Clause 8.6.7 (GHBC-C-001790, page 333): Adjacent combustible members entering into a concrete or masonry fire wall from opposite sides shall not have less than a 102 mm (4inch) distance between embedded ends.', 'study', 'GHBC-C-001790', 'GHBC-REQ-005426', 333, 'e1e5c73953a02893e5486a412a3dcba42f714eaad88e2fcc9c0f1cdfe833ea34', 'requires_review', 0);
