INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fa60bfb861ced967', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.7): “…thickness of the wall and for a distance not less than ______ above, below and between the structural members, with noncombustible materials approved for fireblocking.…” — what value is stated?', '["2 in","6 in","8 in","4 in"]', 3, 'Clause 8.6.7 (GHBC-C-001790, page 333): Where combustible members frame into hollow walls or walls of hollow units, hollow spaces shall be solidly filled for the full thickness of the wall and for a distance not less than 102 mm (4 inches) above, below and between the structural members, with noncombustible materials approved for fireblocking.', 'standard', 'GHBC-C-001790', 'GHBC-REQ-005427', 333, '31980c4b44aec2e34bb02596f0ddf6775493da943a89e9516aebfd2c5e09becb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0488901d851328dd', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.8): “…in accordance with Clause 8.16 and shall not exceed ______.…” — what value is stated?', '["23 m2","30 m2","15 m2","7.5 m2"]', 2, 'Clause 8.6.8 (GHBC-C-001791, page 333): Each opening through a fire wall shall be protected in accordance with Clause 8.16 and shall not exceed 15 m2 (156 square feet).', 'study', 'GHBC-C-001791', 'GHBC-REQ-005428', 333, '84cc2485bbaf1f6e60553edf8ca0bb8acfd5479ac982f0be23b36d24cb492dd1', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2c990efcb064e4dd', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.6.8): “…Openings shall not be limited to ______ where both buildings are equipped…” — what value is stated?', '["15 m2","7.5 m2","23 m2","30 m2"]', 0, 'Clause 8.6.8 (GHBC-C-001791, page 333): Openings shall not be limited to 15 m2 (156 square feet) where both buildings are equipped', 'study', 'GHBC-C-001791', 'GHBC-REQ-005434', 333, '9d69def6927691dc12c661a9c38b0f790bb055c5ca5ececd237f41cced535e27', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-31e858c988616228', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.5.1): “…construction for 1-hour fire barriers required by Table ______ buildings of Types IIB, IIIB and VB construction is not required to be fireresistance rated unless required by other clauses of this Code.…” — what value is stated?', '["509 in","119 in","716 in","408.3 in"]', 0, 'Clause 8.7.5.1 (GHBC-C-001810, page 335): Supporting construction for 1-hour fire barriers required by Table 509 in buildings of Types IIB, IIIB and VB construction is not required to be fireresistance rated unless required by other clauses of this Code.', 'standard', 'GHBC-C-001810', 'GHBC-REQ-005467', 335, '63a184d534e5f77f5b22e0c40c571e90ba71a360f8de8121a6d2e9773b42a0bc', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1979245689bc231c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.6): “…the maximum area of any single opening shall not exceed ______.…” — what value is stated?', '["15 m2","7.5 m2","23 m2","30 m2"]', 0, 'Clause 8.7.6 (GHBC-C-001811, page 335): Openings shall be limited to a maximum aggregate width of 25 percent of the length of the wall, and the maximum area of any single opening shall not exceed 15 m2 (156 square feet).', 'study', 'GHBC-C-001811', 'GHBC-REQ-005469', 335, 'ef9a2b2f8688616e2ff37ea257a94c38fbc8adfb1a13277f53ac8a98e8d63f93', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0782929f34128a50', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.6): “…Openings shall not be limited to ______ where adjoining floor areas are equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1.…” — what value is stated?', '["30 m2","15 m2","7.5 m2","23 m2"]', 1, 'Clause 8.7.6 (GHBC-C-001811, page 335): Openings shall not be limited to 15 m2 (156 square feet) where adjoining floor areas are equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1.', 'study', 'GHBC-C-001811', 'GHBC-REQ-005473', 335, 'e70669e430e2c84e5e802edaa3dba088fae6c0d94cf2e08fcfac66184381fc5a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-92738fa80e22299b', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.6): “…Openings shall not be limited to ______ or an aggregate width of 25 percent of the length of the wall where the opening protective is a fire door serving enclosures for exit access stairways and ramps, and interior exit……” — what value is stated?', '["15 m2","7.5 m2","23 m2","30 m2"]', 0, 'Clause 8.7.6 (GHBC-C-001811, page 335): Openings shall not be limited to 15 m2 (156 square feet) or an aggregate width of 25 percent of the length of the wall where the opening protective is a fire door serving enclosures for exit access stairways and ramps, and interior exit stairways and ramps.', 'study', 'GHBC-C-001811', 'GHBC-REQ-005475', 335, '4fe223e7bba409d36909a1c7fc55c6f6b0fdfdfdf94735d6485eff10a420e4cb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-63b871f437adf387', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.6): “…Openings shall not be limited to ______ or an aggregate width of 25 percent of the length of the wall where the opening protective has been tested in accordance with ASTM E119 and has a minimum fireresistance rating not……” — what value is stated?', '["30 m2","15 m2","7.5 m2","23 m2"]', 1, 'Clause 8.7.6 (GHBC-C-001811, page 335): Openings shall not be limited to 15 m2 (156 square feet) or an aggregate width of 25 percent of the length of the wall where the opening protective has been tested in accordance with ASTM E119 and has a minimum fireresistance rating not less than the fireresistance rating of the wall.', 'study', 'GHBC-C-001811', 'GHBC-REQ-005477', 335, 'a440889bda9ab49797a2214684319e29643764063e0f6b5e6fb45d72123af647', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d1ffb95b2e78777e', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.7.6): “…Openings shall not be limited to ______ or an aggregate width of 25 percent of the length of the wall where the opening protective is a fire door assembly in a fire barrier separating an enclosure for exit access……” — what value is stated?', '["30 m2","15 m2","7.5 m2","23 m2"]', 1, 'Clause 8.7.6 (GHBC-C-001811, page 335): Openings shall not be limited to 15 m2 (156 square feet) or an aggregate width of 25 percent of the length of the wall where the opening protective is a fire door assembly in a fire barrier separating an enclosure for exit access stairways and ramps, and interior exit stairways and ramps from an exit passageway in accordance with Clause 11.23.3.1.', 'study', 'GHBC-C-001811', 'GHBC-REQ-005481', 335, 'ba2f9df5568630afa9392f01f4b8fc85c682989a908f7566dd4ed1b251b82e15', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d9c3a691f6efb1fb', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.8.4): “…______cluding automatic sprinklers installed in the space between the top of the fire partition and underside of the floor or roof sheathing, deck or slab above.…” — what value is stated?', '["2 in","1 in","3 in","4 in"]', 0, 'Clause 8.8.4 (GHBC-C-001820, page 337): 10.3.3.1.2, including automatic sprinklers installed in the space between the top of the fire partition and underside of the floor or roof sheathing, deck or slab above.', 'standard', 'GHBC-C-001820', 'GHBC-REQ-005520', 337, 'a7771109bdf5739ebf4ea431b15ee9e2c9cb555267b92f79b023a82091a78e0f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9477636e7a84d261', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.8.4.1): “…four stories in height in buildings not exceeding ______ in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding ______ or above every two dwelling units, whichever is……” — what value is stated?', '["60 feet","30 feet","85 feet","120 feet"]', 0, 'Clause 8.8.4.1 (GHBC-C-001821, page 337): In Group R-2 occupancies up to and including four stories in height in buildings not exceeding 60 feet (18 288 mm) in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding 279 m2 (3,000 square feet) or above every two dwelling units, whichever is smaller.', 'standard', 'GHBC-C-001821', 'GHBC-REQ-005539', 337, '11035fdc3e025c2f2d6d36f35898356325bf00bcc89377407cf008d7518c7d9e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6fdc0db62610719c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.8.4.1): “…four stories in height in buildings not exceeding ______ in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding ______ or above every two dwelling units, whichever is……” — what value is stated?', '["440 mm","576 mm","288 mm","144 mm"]', 2, 'Clause 8.8.4.1 (GHBC-C-001821, page 337): In Group R-2 occupancies up to and including four stories in height in buildings not exceeding 60 feet (18 288 mm) in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding 279 m2 (3,000 square feet) or above every two dwelling units, whichever is smaller.', 'standard', 'GHBC-C-001821', 'GHBC-REQ-005539', 337, '11035fdc3e025c2f2d6d36f35898356325bf00bcc89377407cf008d7518c7d9e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cd7224fd36e0c276', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.8.4.1): “…four stories in height in buildings not exceeding ______ in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding ______ or above every two dwelling units, whichever is……” — what value is stated?', '["139.4 m2","450 m2","610 m2","279 m2"]', 3, 'Clause 8.8.4.1 (GHBC-C-001821, page 337): In Group R-2 occupancies up to and including four stories in height in buildings not exceeding 60 feet (18 288 mm) in height above grade plane, the attic space shall be subdivided by draftstops into areas not exceeding 279 m2 (3,000 square feet) or above every two dwelling units, whichever is smaller.', 'standard', 'GHBC-C-001821', 'GHBC-REQ-005539', 337, '11035fdc3e025c2f2d6d36f35898356325bf00bcc89377407cf008d7518c7d9e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1ffa45d851c8814a', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.9.3): “…EXCEPTIONS: Smoke barriers constructed of minimum ______ steel in Group I-3 buildings.…” — what value is stated?', '["2.5 mm","1.2 mm","3.76 mm","5 mm"]', 0, 'Clause 8.9.3 (GHBC-C-001829, page 338): EXCEPTIONS: Smoke barriers constructed of minimum 2.5 mm (0.10-inch-thick) steel in Group I-3 buildings.', 'standard', 'GHBC-C-001829', 'GHBC-REQ-005552', 338, '69be7fd55baf147fa1155f12495d78e0723a64ed18e2dc2e6febe4c6860f5e58', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fcf8d8785d8ed9e8', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.9.5): “…shall not have a center mullion or undercuts in excess of ______, louvers or grilles.…” — what value is stated?', '["38 mm","19.1 mm","9.53 mm","29 mm"]', 1, 'Clause 8.9.5 (GHBC-C-001832, page 339): The doors shall be close fitting within operational tolerances, and shall not have a center mullion or undercuts in excess of 19.1 mm (3/4 inch), louvers or grilles.', 'study', 'GHBC-C-001832', 'GHBC-REQ-005568', 339, 'cccfaee7ae6fffc549a2d52ff6a6b695b25c1a255754cad637b928de774b0fe5', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fec824b02b00bea6', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.9.5): “…shall not have a center mullion or undercuts in excess of ______, louvers or grilles.…” — what value is stated?', '["8 in","4 in","2 in","6 in"]', 1, 'Clause 8.9.5 (GHBC-C-001832, page 339): The doors shall be close fitting within operational tolerances, and shall not have a center mullion or undercuts in excess of 19.1 mm (3/4 inch), louvers or grilles.', 'study', 'GHBC-C-001832', 'GHBC-REQ-005568', 339, 'cccfaee7ae6fffc549a2d52ff6a6b695b25c1a255754cad637b928de774b0fe5', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ff1086c0b5609b03', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.10.5.2.2): “…The air leakage rate of the door assembly shall not exceed [______3/(s • m2)] (3.0 cubic feet per minute per square foot) of door opening at 24.9 Pa (______) of water for both the ambient temperature test and the……” — what value is stated?', '["0.1 in","0.047 in","0.15 in","0.2 in"]', 0, 'Clause 8.10.5.2.2 (GHBC-C-001845, page 340): The air leakage rate of the door assembly shall not exceed [0.015424 m3/(s • m2)] (3.0 cubic feet per minute per square foot) of door opening at 24.9 Pa (0.10 inch) of water for both the ambient temperature test and the elevated temperature exposure test.', 'study', 'GHBC-C-001845', 'GHBC-REQ-005589', 340, 'c43e9271718005d074b16756bd4da5ced7342792803e218add84b4e51955ea5d', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2b5cd25be6b5a5eb', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.12.1.3.2): “…The shutter shall operate at a speed of not more than ______ per minute (______/s) and shall be equipped with a sensitive leading edge to arrest its progress where in contact with any obstacle, and to continue its……” — what value is stated?', '["60 feet","30 feet","15 feet","40 feet"]', 1, 'Clause 8.12.1.3.2 (GHBC-C-001873, page 342): The shutter shall operate at a speed of not more than 30 feet per minute (152.4 mm/s) and shall be equipped with a sensitive leading edge to arrest its progress where in contact with any obstacle, and to continue its progress on release therefrom.', 'standard', 'GHBC-C-001873', 'GHBC-REQ-005639', 342, '14d103136301c7f74e084988665762d57f6ae0a5da8c145810cfa3278c22a658', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9f38a2a31407be2f', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.12.1.3.2): “…The shutter shall operate at a speed of not more than ______ per minute (______/s) and shall be equipped with a sensitive leading edge to arrest its progress where in contact with any obstacle, and to continue its……” — what value is stated?', '["229 mm","304.8 mm","152.4 mm","76 mm"]', 2, 'Clause 8.12.1.3.2 (GHBC-C-001873, page 342): The shutter shall operate at a speed of not more than 30 feet per minute (152.4 mm/s) and shall be equipped with a sensitive leading edge to arrest its progress where in contact with any obstacle, and to continue its progress on release therefrom.', 'standard', 'GHBC-C-001873', 'GHBC-REQ-005639', 342, '14d103136301c7f74e084988665762d57f6ae0a5da8c145810cfa3278c22a658', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-67d1e4d2d451a21e', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.14.4.1): “…or masonry walls where the penetrating item is a maximum ______ nominal diameter and the area of the opening through the wall does not exceed ______, concrete, grout or mortar is permitted where installed the full……” — what value is stated?', '["304 mm","152 mm","76 mm","229 mm"]', 1, 'Clause 8.14.4.1 (GHBC-C-001920, page 347): In concrete or masonry walls where the penetrating item is a maximum 152 mm (6-inch) nominal diameter and the area of the opening through the wall does not exceed 0.0929 m2 (144 square inches), concrete, grout or mortar is permitted where installed the full thickness of the wall or the thickness required to maintain the fireresistance rating.', 'standard', 'GHBC-C-001920', 'GHBC-REQ-005762', 347, '857fcefd8b3c562b05b65bdd43f81da37d85fc51d0440ebdeb652e5859fbcaca', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6083350506e610f4', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.14.4.1): “…or masonry walls where the penetrating item is a maximum ______ nominal diameter and the area of the opening through the wall does not exceed ______, concrete, grout or mortar is permitted where installed the full……” — what value is stated?', '["0.19 m2","0.2 m2","0.0929 m2","0.035 m2"]', 2, 'Clause 8.14.4.1 (GHBC-C-001920, page 347): In concrete or masonry walls where the penetrating item is a maximum 152 mm (6-inch) nominal diameter and the area of the opening through the wall does not exceed 0.0929 m2 (144 square inches), concrete, grout or mortar is permitted where installed the full thickness of the wall or the thickness required to maintain the fireresistance rating.', 'standard', 'GHBC-C-001920', 'GHBC-REQ-005762', 347, '857fcefd8b3c562b05b65bdd43f81da37d85fc51d0440ebdeb652e5859fbcaca', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-45a7c81393a53382', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.14.4.1): “…under a minimum positive pressure differential of 2.49 Pa (______) of water at the location of the penetration for the time period equivalent to the fire-resistance rating of the construction penetrated…” — what value is stated?', '["0.01 in","0.005 in","0.016 in","0.02 in"]', 0, 'Clause 8.14.4.1 (GHBC-C-001920, page 347): The material used to fill the annular space shall prevent the passage of flame and hot gases sufficient to ignite cotton waste when subjected to ASTM E119 time-temperature fire conditions under a minimum positive pressure differential of 2.49 Pa (0.01 inch) of water at the location of the penetration for the time period equivalent to the fire-resistance rating of the construction penetrated', 'standard', 'GHBC-C-001920', 'GHBC-REQ-005764', 347, '34ae0f42e376eaa9108e7851ccfff8dae846d26a94bd4fd7bc9a9265cce99a0f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-46f89365d22503ff', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.14.4.1.1): “…with a minimum positive pressure differential of 2.49 Pa (______) of water and shall have an F rating of not less than the required fireresistance rating of the wall penetrated.…” — what value is stated?', '["0.016 in","0.02 in","0.01 in","0.005 in"]', 2, 'Clause 8.14.4.1.1 (GHBC-C-001921, page 347): Through penetrations shall be protected by an approved penetration firestop system installed as tested in accordance with ASTM E814, with a minimum positive pressure differential of 2.49 Pa (0.01 inch) of water and shall have an F rating of not less than the required fireresistance rating of the wall penetrated.', 'standard', 'GHBC-C-001921', 'GHBC-REQ-005768', 347, '8878149f43aef199b5a6d79b11be5eee818275477823826af5c18e4d239ceba0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-942565f3823a4ade', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.14.4.2): “…by steel electrical boxes that do not exceed 0.0 ______ in area, provided that the aggregate area of the openings through the membrane does not exceed ______ in any ______ (100…” — what value is stated?', '["103 m2","50 m2","140 m2","200 m2"]', 0, 'Clause 8.14.4.2 (GHBC-C-001922, page 347): Membrane penetrations of maximum 2-hour fire-resistance-rated walls and partitions by steel electrical boxes that do not exceed 0.0 103 m2 (16 square inches) in area, provided that the aggregate area of the openings through the membrane does not exceed 0.0645 m2 (100 square inches) in any 9.29 m2 (100', 'standard', 'GHBC-C-001922', 'GHBC-REQ-005773', 347, '097552a0f694b20ce51473d744bd6d42ab85add370cfe45ca160a077ae23a0ba', 'extracted', 1);
