INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8a8b34f89321ec12', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.1): “…Viewports that require a hole not larger than ______ in diameter through the door, have not less than a ______ glass disc and the holder is of metal that will not melt out where subject to temperatures of 927°C……” — what value is stated?', '["1 in","0.5 in","1.5 in","2 in"]', 0, 'Clause 8.16.2.2.1 (GHBC-C-001956, page 356): Viewports that require a hole not larger than 25 mm (1 inch) in diameter through the door, have not less than a 6.4 mm (0.25-inch-thick) glass disc and the holder is of metal that will not melt out where subject to temperatures of 927°C (1,700°F).', 'standard', 'GHBC-C-001956', 'GHBC-REQ-005968', 356, '9677a9fde900fa0138b973c15a1f9b2adde2861c2da2e841213897d75c5fd2d6', 'extracted', 1);
