INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-763233e17b636859', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.1.1): “…not exceed 3.0 cubic feet per minute per square foot (______3/s × m2) of door opening at ______ of water for both the ambient temperature and elevated temperature tests.…” — what value is stated?', '["0.2 in","0.1 in","0.047 in","0.15 in"]', 1, 'Clause 8.16.2.2.1.1 (GHBC-C-001957, page 357): The air leakage rate of the door assembly shall not exceed 3.0 cubic feet per minute per square foot (0.01524 m3/s × m2) of door opening at 0.10 inch (24.9 Pa) of water for both the ambient temperature and elevated temperature tests.', 'study', 'GHBC-C-001957', 'GHBC-REQ-005976', 357, 'a52e59817bf3257c4f30e7f2ab270d4ffebef5f3ab10064a7fbd08b14fc4ed7f', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7e262f80c926fdab', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.2): “…required to have a minimum fire protection rating of ______inutes where located in other fire partitions having a fire-resistance rating of 0.5 hour in accordance with Table 8.16.1(2) shall be tested in accordance with……” — what value is stated?', '["40 m","20 m","10 m","30 m"]', 1, 'Clause 8.16.2.2.2 (GHBC-C-001958, page 357): Fire door assemblies required to have a minimum fire protection rating of 20 minutes where located in other fire partitions having a fire-resistance rating of 0.5 hour in accordance with Table 8.16.1(2) shall be tested in accordance with the Ghana Fire Code, with the hose stream test.', 'study', 'GHBC-C-001958', 'GHBC-REQ-005979', 357, 'bde4c61eeb11f2b96798803361d4ebac7e49fd4b4d2fbad8400da5ba0aec534e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0d26d632e1c9b02c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.3): “…of not more than 250oC (450oF) above ambient at the end of ______inutes of standard fire test exposure.…” — what value is stated?', '["30 m","15 m","45 m","60 m"]', 0, 'Clause 8.16.2.2.3 (GHBC-C-001959, page 357): Fire door assemblies in interior exit stairways and ramps and exit passageways shall have a maximum transmitted temperature rise of not more than 250oC (450oF) above ambient at the end of 30 minutes of standard fire test exposure.', 'study', 'GHBC-C-001959', 'GHBC-REQ-005981', 357, 'e217a92ff123255b0c746e35742c84a3f2eaa94e3c69bcac7e29db2e79ec67e1', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6af71d47e17885e4', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.3.1): “…glazing in excess of 100 square inches (______) is not permitted.…” — what value is stated?', '["0.0929 m2","0.065 m2","0.035 m2","0.093 m2"]', 1, 'Clause 8.16.2.2.3.1 (GHBC-C-001960, page 357): Fire-protection-rated glazing in excess of 100 square inches (0.065 m2) is not permitted.', 'study', 'GHBC-C-001960', 'GHBC-REQ-005983', 357, '10a705ae07c525cf4802a72fd7f20121e8338e2735d2493493c60c64039cf74a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7323e3439b83694f', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.2.3.1): “…Fireresistance-rated glazing in excess of ______ shall be permitted in fire doors.…” — what value is stated?', '["0.0929 m2","0.065 m2","0.035 m2","0.093 m2"]', 1, 'Clause 8.16.2.2.3.1 (GHBC-C-001960, page 357): Fireresistance-rated glazing in excess of 0.065 m2 (100 square inches) shall be permitted in fire doors.', 'study', 'GHBC-C-001960', 'GHBC-REQ-005984', 357, 'ea2cd9b82c33d266bc7e8492d802e13e1796a1d8c20e857a77995d53be64d168', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-05e40ae792404554', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.5.1.2.1): “…serving as horizontal exits in fire walls where limited to ______).…” — what value is stated?', '["0.035 m2","0.093 m2","0.0929 m2","0.065 m2"]', 3, 'Clause 8.16.2.5.1.2.1 (GHBC-C-001967, page 357): Fire-protection-rated glazing shall be permitted as vision panels in self-closing swinging fire door assemblies serving as horizontal exits in fire walls where limited to 0.065 m2).', 'study', 'GHBC-C-001967', 'GHBC-REQ-005996', 357, 'f0917ef2f3c71d33a8520e5ac27110a83ca1887b3d42afaef1403794324e744d', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-babfac7580d0791d', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.5.1.2.2): “…for installation in fire barriers, where limited to ______.…” — what value is stated?', '["0.035 m2","0.093 m2","0.0929 m2","0.065 m2"]', 3, 'Clause 8.16.2.5.1.2.2 (GHBC-C-001968, page 358): Fire-protection-rated glazing shall be permitted in fire doors having a 11/2-hour fire protection rating intended for installation in fire barriers, where limited to 0.065 m2 (100 square inches).', 'standard', 'GHBC-C-001968', 'GHBC-REQ-005998', 358, '856b973457ff25214e46e3508fe8ec5e233aef5641d0d9945e71ba1faa69c9eb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a651257ca4ace368', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.5.3): “…shall have a minimum fire-protection-rated glazing of ______inutes and shall be exempt from the hose stream test.…” — what value is stated?', '["20 m","10 m","30 m","40 m"]', 0, 'Clause 8.16.2.5.3 (GHBC-C-001970, page 358): In a 20-minute fire door assembly, the glazing material in the door itself shall have a minimum fire-protection-rated glazing of 20 minutes and shall be exempt from the hose stream test.', 'standard', 'GHBC-C-001970', 'GHBC-REQ-006002', 358, 'f6bd60e2244c8366d0f3dcc365d746dec99e56ce3c1783e29c7b111436ff46f5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c4d067a3260edb54', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.7): “…by distinguishing marks or letters not less than ______ high.…” — what value is stated?', '["229 mm","304 mm","152 mm","76 mm"]', 2, 'Clause 8.16.2.7 (GHBC-C-001979, page 359): Where fire shutters of the swinging type are installed in exterior openings, not less than one row in every three vertical rows shall be arranged to be readily opened from the outside, and shall be identified by distinguishing marks or letters not less than 152 mm (6 inches) high.', 'standard', 'GHBC-C-001979', 'GHBC-REQ-006040', 359, 'c5bb603ecabed93c4ce3391096b0e7b22cbaf247de6df016117651c4eca280db', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cf9e7e08178205d1', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.2.7): “…by distinguishing marks or letters not less than ______ high.…” — what value is stated?', '["6 in","3 in","9 in","12 in"]', 0, 'Clause 8.16.2.7 (GHBC-C-001979, page 359): Where fire shutters of the swinging type are installed in exterior openings, not less than one row in every three vertical rows shall be arranged to be readily opened from the outside, and shall be identified by distinguishing marks or letters not less than 152 mm (6 inches) high.', 'standard', 'GHBC-C-001979', 'GHBC-REQ-006040', 359, 'c5bb603ecabed93c4ce3391096b0e7b22cbaf247de6df016117651c4eca280db', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a887962be566c497', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.1.1): “…Within the first ______inutes of a test, the pressure in the furnace shall be adjusted so not less than two-thirds of the test specimen is above the neutral pressure plane, and the neutral pressure plane shall be……” — what value is stated?', '["20 m","10 m","5 m","15 m"]', 1, 'Clause 8.16.3.1.1 (GHBC-C-001989, page 360): Within the first 10 minutes of a test, the pressure in the furnace shall be adjusted so not less than two-thirds of the test specimen is above the neutral pressure plane, and the neutral pressure plane shall be maintained at that height for the balance of the test.', 'study', 'GHBC-C-001989', 'GHBC-REQ-006066', 360, 'd378c1dca5e35426019cae0d809f0f06e96a985470cf3579a4abbdbfa51cda83', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ce49bc355cdfc33d', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.1.2): “…or in exterior walls with a fire separation distance of ______ or less pursuant to Clause 8.5 shall be tested with both faces exposed to the furnace, and the assigned fire protection rating shall be the shortest……” — what value is stated?', '["20 feet","10 feet","5 feet","15 feet"]', 1, 'Clause 8.16.3.1.2 (GHBC-C-001990, page 360): Nonsymmetrical fire-protection-rated glazing systems in fire partitions, fire barriers or in exterior walls with a fire separation distance of 10 feet (3048 mm) or less pursuant to Clause 8.5 shall be tested with both faces exposed to the furnace, and the assigned fire protection rating shall be the shortest duration obtained from the two tests conducted in compliance with the Ghana Fire Code.', 'study', 'GHBC-C-001990', 'GHBC-REQ-006067', 360, '4e99882c07127b05c4c6c73bb78131475c68909001d8ddf731f3b5ca01a236ae', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bc0377c9ba393dbf', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.1.2): “…or in exterior walls with a fire separation distance of ______ or less pursuant to Clause 8.5 shall be tested with both faces exposed to the furnace, and the assigned fire protection rating shall be the shortest……” — what value is stated?', '["4572 mm","6096 mm","3048 mm","1524 mm"]', 2, 'Clause 8.16.3.1.2 (GHBC-C-001990, page 360): Nonsymmetrical fire-protection-rated glazing systems in fire partitions, fire barriers or in exterior walls with a fire separation distance of 10 feet (3048 mm) or less pursuant to Clause 8.5 shall be tested with both faces exposed to the furnace, and the assigned fire protection rating shall be the shortest duration obtained from the two tests conducted in compliance with the Ghana Fire Code.', 'study', 'GHBC-C-001990', 'GHBC-REQ-006067', 360, '4e99882c07127b05c4c6c73bb78131475c68909001d8ddf731f3b5ca01a236ae', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e3f9fa80195f0dc0', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.2.1.1): “…Fire-protection-rated glazing requiring ______inute opening protection in accordance with…” — what value is stated?', '["90 m","45 m","22.7 m","70 m"]', 1, 'Clause 8.16.3.2.1.1 (GHBC-C-001993, page 360): Fire-protection-rated glazing requiring 45minute opening protection in accordance with', 'study', 'GHBC-C-001993', 'GHBC-REQ-006071', 360, 'd739a42395cf608ea8ffa37ed2e75c2e45b9075b45934a0902a5f1ea256364de', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b69211c672561f2f', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.3.1): “…Metal mullions that exceed a nominal height of ______ shall be protected with materials to afford the same fire-resistance rating as required for the wall construction in which the protective is located.…” — what value is stated?', '["6 feet","18 feet","24 feet","12 feet"]', 3, 'Clause 8.16.3.3.1 (GHBC-C-001997, page 361): Metal mullions that exceed a nominal height of 12 feet (3658 mm) shall be protected with materials to afford the same fire-resistance rating as required for the wall construction in which the protective is located.', 'standard', 'GHBC-C-001997', 'GHBC-REQ-006078', 361, 'd3f9788769cd2ec07e79ae3c9da8837ab945474414e8124dabf32985ac3abdc5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7bc77c4b0316442c', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.16.3.3.1): “…Metal mullions that exceed a nominal height of ______ shall be protected with materials to afford the same fire-resistance rating as required for the wall construction in which the protective is located.…” — what value is stated?', '["1829 mm","5486 mm","7315 mm","3658 mm"]', 3, 'Clause 8.16.3.3.1 (GHBC-C-001997, page 361): Metal mullions that exceed a nominal height of 12 feet (3658 mm) shall be protected with materials to afford the same fire-resistance rating as required for the wall construction in which the protective is located.', 'standard', 'GHBC-C-001997', 'GHBC-REQ-006078', 361, 'd3f9788769cd2ec07e79ae3c9da8837ab945474414e8124dabf32985ac3abdc5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-862ef736c168d22b', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.2.2): “…acceptable closure performance when subjected to ______ per minute (______ps) velocity across the face of the damper during this Code fire exposure test.…” — what value is stated?', '["150 feet","75 feet","200 feet","300 feet"]', 0, 'Clause 8.17.2.2 (GHBC-C-002011, page 362): Corridor dampers shall demonstrate acceptable closure performance when subjected to 150 feet per minute (0.76 mps) velocity across the face of the damper during this Code fire exposure test.', 'standard', 'GHBC-C-002011', 'GHBC-REQ-006113', 362, '912da6d07b4a2572252873f79ddac0dab55f101565f01c1f4dd9fa8a4fcca199', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4dcec36b2e8fa6f5', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.2.2): “…acceptable closure performance when subjected to ______ per minute (______ps) velocity across the face of the damper during this Code fire exposure test.…” — what value is stated?', '["1.5 m","0.76 m","0.38 m","1.15 m"]', 1, 'Clause 8.17.2.2 (GHBC-C-002011, page 362): Corridor dampers shall demonstrate acceptable closure performance when subjected to 150 feet per minute (0.76 mps) velocity across the face of the damper during this Code fire exposure test.', 'standard', 'GHBC-C-002011', 'GHBC-REQ-006113', 362, '912da6d07b4a2572252873f79ddac0dab55f101565f01c1f4dd9fa8a4fcca199', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-03ead2669cedceb5', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.3.3.2): “…The detector or tubes within the duct shall be within ______ of the damper.…” — what value is stated?', '["5 feet","3 feet","8 feet","10 feet"]', 0, 'Clause 8.17.3.3.2 (GHBC-C-002019, page 363): The detector or tubes within the duct shall be within 5 feet (1524 mm) of the damper.', 'study', 'GHBC-C-002019', 'GHBC-REQ-006136', 363, 'a35be98496bf842f4b2c8a54e6008e8a2d43c9760e7c84ecce06d5051b554df0', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-221b16c19237f4dd', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.3.3.2): “…The detector or tubes within the duct shall be within ______ of the damper.…” — what value is stated?', '["762 mm","2286 mm","3048 mm","1524 mm"]', 3, 'Clause 8.17.3.3.2 (GHBC-C-002019, page 363): The detector or tubes within the duct shall be within 5 feet (1524 mm) of the damper.', 'study', 'GHBC-C-002019', 'GHBC-REQ-006136', 363, 'a35be98496bf842f4b2c8a54e6008e8a2d43c9760e7c84ecce06d5051b554df0', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5b1e01b97ecd5faf', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.3.3.2): “…in a wall, a spot-type detector shall be installed within ______ horizontally of the damper.…” — what value is stated?', '["5 feet","3 feet","8 feet","10 feet"]', 0, 'Clause 8.17.3.3.2 (GHBC-C-002019, page 363): Where a smoke damper is installed within an air transfer opening in a wall, a spot-type detector shall be installed within 5 feet (1524 mm) horizontally of the damper.', 'study', 'GHBC-C-002019', 'GHBC-REQ-006144', 363, '491b1b50f49a057e19bbdbd6a4de7f39dc7504b06d70ac236e4cfbe62d6205e9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-478913dbcb3f52f9', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.3.3.2): “…in a wall, a spot-type detector shall be installed within ______ horizontally of the damper.…” — what value is stated?', '["762 mm","2286 mm","3048 mm","1524 mm"]', 3, 'Clause 8.17.3.3.2 (GHBC-C-002019, page 363): Where a smoke damper is installed within an air transfer opening in a wall, a spot-type detector shall be installed within 5 feet (1524 mm) horizontally of the damper.', 'study', 'GHBC-C-002019', 'GHBC-REQ-006144', 363, '491b1b50f49a057e19bbdbd6a4de7f39dc7504b06d70ac236e4cfbe62d6205e9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-29b1150106188702', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.4): “…on the exterior by a label having letters not less than ______ in height reading: FIRE/SMOKE DAMPER, SMOKE DAMPER or FIRE DAMPER.…” — what value is stated?', '["25.4 mm","12.7 mm","6.4 mm","19.05 mm"]', 1, 'Clause 8.17.4 (GHBC-C-002022, page 364): Access points shall be permanently identified on the exterior by a label having letters not less than 12.7 mm (1/2 inch) in height reading: FIRE/SMOKE DAMPER, SMOKE DAMPER or FIRE DAMPER.', 'standard', 'GHBC-C-002022', 'GHBC-REQ-006159', 364, '60b18eb84e1a2ae7a48b1b96835eec086ad7ef0476606230e8022ee9b7530ce7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-600d5f82b48cad8d', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.17.4): “…on the exterior by a label having letters not less than ______ in height reading: FIRE/SMOKE DAMPER, SMOKE DAMPER or FIRE DAMPER.…” — what value is stated?', '["4 in","2 in","1 in","3 in"]', 1, 'Clause 8.17.4 (GHBC-C-002022, page 364): Access points shall be permanently identified on the exterior by a label having letters not less than 12.7 mm (1/2 inch) in height reading: FIRE/SMOKE DAMPER, SMOKE DAMPER or FIRE DAMPER.', 'standard', 'GHBC-C-002022', 'GHBC-REQ-006159', 364, '60b18eb84e1a2ae7a48b1b96835eec086ad7ef0476606230e8022ee9b7530ce7', 'extracted', 1);
