INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fa027c0a4e652790', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.18.2.7): “…that open spaces under the flooring shall not exceed ______ in area and such space shall be filled solidly under permanent partitions so that communication under the flooring between adjoining rooms shall not occur.…” — what value is stated?', '["18.6 m2","9.3 m2","4.65 m2","14 m2"]', 1, 'Clause 8.18.2.7 (GHBC-C-002052, page 370): Where wood sleepers are used for laying wood flooring on masonry or concrete fire-resistancerated floors, the space between the floor slab and the underside of the wood flooring shall be filled with an approved material to resist the free passage of flame and products of combustion or fireblocked in such a manner that open spaces under the flooring shall not exceed 9.3 m2 (100 square feet) in area', 'study', 'GHBC-C-002052', 'GHBC-REQ-006366', 370, '1d8d59fee246eee2e62d8c7c05abc32e165a0a68b4194b42966aec272b63570b', 'requires_review', 0);
