INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2b909d6791533c1a', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.18.3.1): “…Draftstopping materials shall be not less than ______ gypsum board, 3/8-inch (______) wood structural panel, ______ particleboard, 25-mm (1-inch) nominal timber, cement fiberboard, batts or blankets of mineral wool or……” — what value is stated?', '["25.4 mm","12.7 mm","6.4 mm","19.05 mm"]', 1, 'Clause 8.18.3.1 (GHBC-C-002054, page 370): Draftstopping materials shall be not less than 12.7 mm (1/2-inch) gypsum board, 3/8-inch (9.5 mm) wood structural panel, 9.5 mm (3/8-inch) particleboard, 25-mm (1-inch) nominal timber, cement fiberboard, batts or blankets of mineral wool or glass fiber, or other approved materials adequately supported.', 'standard', 'GHBC-C-002054', 'GHBC-REQ-006375', 370, 'cbd4ad79896e44eb1af2a2bf8e8ceb2d3c7606551ebc8ac8af8ea75d9a57054a', 'extracted', 1);
