INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f05b17b965592478', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.21.1.4): “…A minimum cover of ______ for slabs and ______ for beams is required for any aggregate concrete 3.…” — what value is stated?', '["19.1 mm","9.53 mm","29 mm","38 mm"]', 0, 'Clause 8.21.1.4 (GHBC-C-002080, page 397): A minimum cover of 19.1 mm (3/4 inch) for slabs and 25 mm (1 inch) for beams is required for any aggregate concrete 3.', 'study', 'GHBC-C-002080', 'GHBC-REQ-006538', 397, '5b95dece41cb75d1fa3e413444a40da703226c83cb06278230959e480960e818', 'requires_review', 0);
