INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5602883997038762', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.21.1.4): “…required ultimate moment capacity for members less than ______ in cross-clauseal area and 65 percent for larger members.…” — what value is stated?', '["0.226 m2","0.093 m2","0.305 m2","0.46 m2"]', 0, 'Clause 8.21.1.4 (GHBC-C-002080, page 397): For the purpose of establishing a fireresistance rating, tendons having a clear covering less than that set forth in Table 8.21.1(1) shall not contribute more than 50 percent of the required ultimate moment capacity for members less than 0.226 m2 (350 square inches) in cross-clauseal area and 65 percent for larger members.', 'study', 'GHBC-C-002080', 'GHBC-REQ-006539', 397, 'eed1dc4b14b8c990faebf48e06a56f1639167745cb7381fea7762dfe562b6ef8', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9b8001c76a3e457f', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.2.1.1.3): “…cross clauses shall be that determined at a distance 2t or ______, whichever is less, from the point of minimum thickness, where t is the minimum thickness.…” — what value is stated?', '["12 in","6 in","3 in","9 in"]', 1, 'Clause 8.22.2.1.1.3 (GHBC-C-002086, page 399): The thickness of panels with tapered cross clauses shall be that determined at a distance 2t or 6 inches (152 mm), whichever is less, from the point of minimum thickness, where t is the minimum thickness.', 'standard', 'GHBC-C-002086', 'GHBC-REQ-006556', 399, '73054eaa4b2c81807209860c85b0a0b055d351846e75c1afa14c8f59095e2168', 'extracted', 1);
