INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-983345d03945db69', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.2.1.4): “…of Portland cement-sand plaster, provided that it is 5/______ or less in thickness, shall be permitted to be included in determining the equivalent thickness of the masonry for use in Table 8.22.3.2.…” — what value is stated?', '["4 in","12 in","16 in","8 in"]', 3, 'Clause 8.22.2.1.4 (GHBC-C-002093, page 401): The actual thickness of Portland cement-sand plaster, provided that it is 5/8 inch or less in thickness, shall be permitted to be included in determining the equivalent thickness of the masonry for use in Table 8.22.3.2.', 'standard', 'GHBC-C-002093', 'GHBC-REQ-006588', 401, '2bcc2e766243c8488e34d2f5be99291f416f7801b3e9bf36c088a1555f3200dd', 'extracted', 1);
