INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-33f38ce1be32332a', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.6.2.3): “…exterior wall with a fire separation distance greater than ______, the wall is assigned a rating dependent on the interior membrane and the framing as described in Tables 8.22.6.2(1) and 8.22.6.2(2).…” — what value is stated?', '["4572 mm","6096 mm","3048 mm","1524 mm"]', 2, 'Clause 8.22.6.2.3 (GHBC-C-002172, page 433): For an exterior wall with a fire separation distance greater than 3048 mm (10 feet), the wall is assigned a rating dependent on the interior membrane and the framing as described in Tables 8.22.6.2(1) and 8.22.6.2(2).', 'study', 'GHBC-C-002172', 'GHBC-REQ-006974', 433, '8fb5315d5cc5e68eef0652e691fffd42d90b3228403af78b08f0b7fdadb63f8a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2efd7c4bd9ad71a4', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.6.2.3): “…exterior wall with a fire separation distance greater than ______, the wall is assigned a rating dependent on the interior membrane and the framing as described in Tables 8.22.6.2(1) and 8.22.6.2(2).…” — what value is stated?', '["15 feet","20 feet","10 feet","5 feet"]', 2, 'Clause 8.22.6.2.3 (GHBC-C-002172, page 433): For an exterior wall with a fire separation distance greater than 3048 mm (10 feet), the wall is assigned a rating dependent on the interior membrane and the framing as described in Tables 8.22.6.2(1) and 8.22.6.2(2).', 'study', 'GHBC-C-002172', 'GHBC-REQ-006974', 433, '8fb5315d5cc5e68eef0652e691fffd42d90b3228403af78b08f0b7fdadb63f8a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e389605dc604d23b', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.6.2.3): “…walls with a fire separation distance greater than ______ shall consist of sheathing, sheathing paper and siding as described in Table 8.22.6.2(3).…” — what value is stated?', '["1524 mm","4572 mm","6096 mm","3048 mm"]', 3, 'Clause 8.22.6.2.3 (GHBC-C-002172, page 433): The membrane on the outside of the nonfireexposed side of exterior walls with a fire separation distance greater than 3048 mm (10 feet) shall consist of sheathing, sheathing paper and siding as described in Table 8.22.6.2(3).', 'study', 'GHBC-C-002172', 'GHBC-REQ-006975', 433, '183291344d8ea398c7160cd43ba166251d6273df23100f442765d6c57e16ecf5', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6dce3d0ec5e62535', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.6.2.3): “…walls with a fire separation distance greater than ______ shall consist of sheathing, sheathing paper and siding as described in Table 8.22.6.2(3).…” — what value is stated?', '["5 feet","15 feet","20 feet","10 feet"]', 3, 'Clause 8.22.6.2.3 (GHBC-C-002172, page 433): The membrane on the outside of the nonfireexposed side of exterior walls with a fire separation distance greater than 3048 mm (10 feet) shall consist of sheathing, sheathing paper and siding as described in Table 8.22.6.2(3).', 'study', 'GHBC-C-002172', 'GHBC-REQ-006975', 433, '183291344d8ea398c7160cd43ba166251d6273df23100f442765d6c57e16ecf5', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-56745fbedb5cee57', NULL, NULL, 'threshold', 8, 'GS 1207:2018 Part 8 (Clause 8.22.6.2.4): “…contribution to fire resistance of not less than ______inutes in Table 8.22.6.2(1).…” — what value is stated?', '["30 m","15 m","7.5 m","22.7 m"]', 1, 'Clause 8.22.6.2.4 (GHBC-C-002173, page 433): contribution to fire resistance of not less than 15 minutes in Table 8.22.6.2(1).', 'study', 'GHBC-C-002173', 'GHBC-REQ-006978', 433, '5ca0e9246641ad7ad97cc4cb100d9c67e5161720d2c55b21b804da342a83171f', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-79b072d45d1f19e2', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.1.1): “…shall be subject to the appropriate requirements in part ______ addition to requirements in this Clause.…” — what value is stated?', '["4.3 in","6 in","3 in","1.5 in"]', 2, 'Clause 9.1.1 (GHBC-C-002176, page 434): Where a wall or ceiling assembly is required to provide a certain fireresistance, a flame-spread rating or a sound transmission class rating, the wall or ceiling finishing shall be subject to the appropriate requirements in part 3 in addition to requirements in this Clause.', 'standard', 'GHBC-C-002176', 'GHBC-REQ-006983', 434, 'fec28bb616a5a5a4a274c89cf6442be15943bf332983e658c16f483ac099beb9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-eef02e83bad03521', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.1.1.1): “…total smoke released throughout the test shall not exceed ______ .…” — what value is stated?', '["2090 m2","1000 m2","500 m2","1500 m2"]', 1, 'Clause 9.3.1.1.1 (GHBC-C-002186, page 434): The total smoke released throughout the test shall not exceed 1,000 m2 .', 'study', 'GHBC-C-002186', 'GHBC-REQ-007009', 434, 'd490b253963af365d61033f64aa6ad4c220272c4ab5a55ad81a1f1954f669c2f', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5b0e844f4a72e21b', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.2): “…Materials having a thickness less than ______ applied directly to the surface of walls or ceilings shall not be required to be tested.…” — what value is stated?', '["0.455 mm","1.4 mm","1.8 mm","0.9 mm"]', 3, 'Clause 9.3.2 (GHBC-C-002189, page 435): Materials having a thickness less than 0.9 mm (0.036 inch) applied directly to the surface of walls or ceilings shall not be required to be tested.', 'study', 'GHBC-C-002189', 'GHBC-REQ-007019', 435, '2a662160ab248dbec6aa1e4034612cd7412c3cd0870847db1e5ab4fd74115900', 'requires_review', 0);
