INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1b2757277b68b810', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.14): “…temperatures of 93°C for not less than ______inutes.…” — what value is stated?', '["15 m","45 m","60 m","30 m"]', 3, 'Clause 9.3.14 (GHBC-C-002204, page 437): temperatures of 93°C for not less than 30 minutes.', 'study', 'GHBC-C-002204', 'GHBC-REQ-007083', 437, 'cb73ac5e4061dae5d73847aaf1b43aa436fa0be005f990a8871ae2221de76c28', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6dcab629c1d4a5ee', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.15): “…such construction or to furring strips not exceeding ______, applied directly against such surfaces.…” — what value is stated?', '["22 mm","65 mm","89 mm","44 mm"]', 3, 'Clause 9.3.15 (GHBC-C-002205, page 437): Where walls, ceilings or structural elements are required by any provision in this Code to be of fire-resistance-rated or noncombustible construction, the interior finish material shall be applied directly against such construction or to furring strips not exceeding 44 mm, applied directly against such surfaces.', 'standard', 'GHBC-C-002205', 'GHBC-REQ-007087', 437, '73a0e59b88d7af1051c7fd700008851989a37e6450e0eea64d6727801670c3b8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9d846af4b6761cdb', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.15.1.1): “…Be fire blocked at not greater than ______ in every direction in accordance with Clause 8.18.…” — what value is stated?', '["1219 mm","3657 mm","4572 mm","2438 mm"]', 3, 'Clause 9.3.15.1.1 (GHBC-C-002206, page 438): Be fire blocked at not greater than 2438 mm in every direction in accordance with Clause 8.18.', 'standard', 'GHBC-C-002206', 'GHBC-REQ-007094', 438, 'eb630affe2a890ae32674e019359371cdc02c18567dc37d1d64bed5a2f236a49', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-caa3a6c5a0859337', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.3.15.4): “…wall or ceiling finish material that is not more than ______ thick shall be applied directly onto the wall, ceiling or structural element without the use of furring strips and shall not be suspended away from the……” — what value is stated?', '["6.4 mm","3.2 mm","9.53 mm","12.732 mm"]', 0, 'Clause 9.3.15.4 (GHBC-C-002210, page 438): An interior wall or ceiling finish material that is not more than 6.4 mm thick shall be applied directly onto the wall, ceiling or structural element without the use of furring strips and shall not be suspended away from the building element to which that finish material it is applied.', 'study', 'GHBC-C-002210', 'GHBC-REQ-007108', 438, '4491937a2b230e5d6ffb3fdaa3fa711468181c0aac56ee725f42c82f4de981ee', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-292e38759c22375b', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.4.4.2): “…and I-3 and not less than Class II in Groups A, B, E, H, I-______, R-1, R-2 and S.…” — what value is stated?', '["-4 m","-1 m","-5 m","-3.5 m"]', 0, 'Clause 9.4.4.2 (GHBC-C-002216, page 439): The minimum critical radiant flux shall be not less than Class I in Groups I-1, I-2 and I-3 and not less than Class II in Groups A, B, E, H, I-4, M, R-1, R-2 and S.', 'standard', 'GHBC-C-002216', 'GHBC-REQ-007127', 439, '15e5a5e009b1c84da79b7ea21d957c221f479e7ecffee6cd4fa9a710a00d50f4', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-dcf9f76f7e8db98f', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.5.1.3): “…Combustible insulating boards not more than ______ thick and covered with finish flooring are permitted where attached directly to2 a noncombustible floor assembly or to wood subflooring attached to sleepers as provided……” — what value is stated?', '["25.4 mm","12.7 mm","6.4 mm","19.05 mm"]', 1, 'Clause 9.5.1.3 (GHBC-C-002220, page 440): Combustible insulating boards not more than 12.7 mm (1 / inch) thick and covered with finish flooring are permitted where attached directly to2 a noncombustible floor assembly or to wood subflooring attached to sleepers as provided for in Clause 9.5.1.1.', 'standard', 'GHBC-C-002220', 'GHBC-REQ-007134', 440, '7fa908b2a80e3c3f12bdd49685114c639fcc4bd55af78f1b0433cad2bd3ee753', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e378814776e36294', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.6.8): “…Interior floor-wall base that is ______ or less in height shall be tested in accordance with Clause 9.4.2 and shall be not less than Class II.…” — what value is stated?', '["76 mm","229 mm","304 mm","152 mm"]', 3, 'Clause 9.6.8 (GHBC-C-002228, page 441): Interior floor-wall base that is 152 mm (6 inches) or less in height shall be tested in accordance with Clause 9.4.2 and shall be not less than Class II.', 'standard', 'GHBC-C-002228', 'GHBC-REQ-007164', 441, '39fee6a9055ad238d843fcc0ea4d95f61bf83a0562c183bbec9075385fef43c3', 'extracted', 1);
