INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-95c2c80582b42cdb', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.10.1): “…shall be subject to the appropriate requirements in Clause ______ addition to requirements in this Clause.…” — what value is stated?', '["3.1 in","1.5 in","5 in","6.2 in"]', 0, 'Clause 9.10.1 (GHBC-C-002235, page 441): Where a wall or ceiling assembly is required to provide a certain fire-resistance, a flamespread rating or a sound transmission class rating, the wall or ceiling finishing shall be subject to the appropriate requirements in Clause 3.1 in addition to requirements in this Clause.', 'standard', 'GHBC-C-002235', 'GHBC-REQ-007174', 441, '68c14ff6ccd0e7b262603101fb28af13607d1de32c56635fc330b619da1dc645', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6126bd885e1582c6', NULL, NULL, 'threshold', 9, 'GS 1207:2018 Part 9 (Clause 9.10.2.1): “…finish shall be provided to a height of not less than ______ above the floor in shower stalls, ______ above the rims of bathtubs equipped with showers and ______ above the rims of bathtubs not equipped with showers.…” — what value is stated?', '["1.8 m","0.9 m","2.7 m","3.6 m"]', 0, 'Clause 9.10.2.1 (GHBC-C-002237, page 442): Waterproof finish shall be provided to a height of not less than 1.8m above the floor in shower stalls, 1.2m above the rims of bathtubs equipped with showers and 400mm above the rims of bathtubs not equipped with showers.', 'standard', 'GHBC-C-002237', 'GHBC-REQ-007175', 442, '68f8ab7f903117c8e1207438ce50ba080e75c69df83b790f2ccbe9dab8dc8132', 'extracted', 1);
