INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9aa7fe69c5fafd41', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.3.2.11.3): “…stories with an occupant load of 30 or more located 16 ______ or more above the lowest level of fire department vehicle access______easured to the finished floor.…” — what value is stated?', '["120 feet","55 feet","28 feet","85 feet"]', 1, 'Clause 10.3.2.11.3 (GHBC-C-002309, page 451): An automatic sprinkler system shall be installed throughout buildings that have one or more stories with an occupant load of 30 or more located 16 764 mm (55 feet) or more above the lowest level of fire department vehicle access, measured to the finished floor.', 'study', 'GHBC-C-002309', 'GHBC-REQ-007399', 451, 'f607fe552f41a27b3fa9175c29f633b4d9183e0a559ee331dbda39d6c6108b83', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0360d8983dbb8b54', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.3.2.11.3): “…largest cross- clauseal diameter of the duct is less than ______.…” — what value is stated?', '["254 mm","127 mm","381 mm","508 mm"]', 0, 'Clause 10.3.2.11.3 (GHBC-C-002309, page 451): EXCEPTIONS: Ducts where the largest cross- clauseal diameter of the duct is less than 254 mm (10 inches).', 'study', 'GHBC-C-002309', 'GHBC-REQ-007407', 451, '43941ef312a466822a20aa278a00fd3934f49afbb9726db5458b8005ec8889fd', 'requires_review', 0);
