INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8fc7cdd1779da402', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.3.3.1.1.2): “…shall not be required in bathrooms that do not exceed ______ in area and are located within individual dwelling units or sleeping units, provided that walls and ceilings______cluding the walls and ceilings behind a……” — what value is stated?', '["2.5 m","7.5 m","10 m","5 m"]', 3, 'Clause 10.3.3.1.1.2 (GHBC-C-002316, page 452): In Group R occupancies sprinklers shall not be required in bathrooms that do not exceed 5 m (255 square feet) in area and are located within individual dwelling units or sleeping units, provided that walls and ceilings, including the walls and ceilings behind a shower enclosure or tub, are of noncombustible or limitedcombustible materials with a 15-minute thermal barrier rating.', 'study', 'GHBC-C-002316', 'GHBC-REQ-007431', 452, '4a890766006dc3a8e1aa08d78007c5ab0f2171fd775bccec15cf2100c175e52c', 'requires_review', 0);
