INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-237bb0988b2181f5', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.7.2.18): “…Where the lowest level of a structure is more than 18 ______ below the finished floor of the lowest level of exit discharge, the structure shall be equipped throughout with a manual fire alarm system______cluding an……” — what value is stated?', '["85 feet","120 feet","60 feet","30 feet"]', 2, 'Clause 10.7.2.18 (GHBC-C-002486, page 475): Where the lowest level of a structure is more than 18 288 mm (60 feet) below the finished floor of the lowest level of exit discharge, the structure shall be equipped throughout with a manual fire alarm system, including an emergency voice/alarm communication system installed in accordance with Clause 10.7.5.2.2.', 'standard', 'GHBC-C-002486', 'GHBC-REQ-008106', 475, '928ba5b00a467d622237e5540e262c574e4436e3f2feb98cb83a155251da6e46', 'extracted', 1);
