INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-611eba0daa469e65', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.7.4.2.1): “…Manual fire alarm boxes shall be located not more than ______ from the entrance to each exit.…” — what value is stated?', '["5 feet","3 feet","8 feet","10 feet"]', 0, 'Clause 10.7.4.2.1 (GHBC-C-002502, page 477): Manual fire alarm boxes shall be located not more than 1524 mm (5 feet) from the entrance to each exit.', 'standard', 'GHBC-C-002502', 'GHBC-REQ-008170', 477, '0df40e04c8a2922e7708862a5ecb559b1e53494f165bba040aad9907b2ec7e86', 'extracted', 1);
