INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f6ae2fd420e06abd', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.7.4.3.1): “…other than specific fire safety functions noted in Clause ______ areas where ambient conditions prohibit the installation of smoke detectors, an automatic sprinkler system installed in such areas in accordance with……” — what value is stated?', '["6 in","3 in","1.5 in","4.3 in"]', 1, 'Clause 10.7.4.3.1 (GHBC-C-002509, page 478): For conditions other than specific fire safety functions noted in Clause 10.7.3, in areas where ambient conditions prohibit the installation of smoke detectors, an automatic sprinkler system installed in such areas in accordance with Clause 10.3.3.1.1 or 10.3.3.1.2 and that is connected to the fire alarm system shall be approved as automatic heat detection.', 'standard', 'GHBC-C-002509', 'GHBC-REQ-008185', 478, '34db8715ea10159c2e9a88e716f49f6d944e862b1db939246ac71824214eb76d', 'extracted', 1);
