INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-61cd636c641cd023', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.4.6): “…of the fire event for a period of not less than either ______inutes or 1.5 times the calculated escape time, whichever is greater.…” — what value is stated?', '["20 m","10 m","30 m","40 m"]', 0, 'Clause 10.9.4.6 (GHBC-C-002549, page 482): All portions of active or engineered smoke control systems shall be capable of continued operation after detection of the fire event for a period of not less than either 20 minutes or 1.5 times the calculated escape time, whichever is greater.', 'standard', 'GHBC-C-002549', 'GHBC-REQ-008334', 482, 'ca308a73b3a235c389d6b6052f10ffd664e301cb49dc8f05ab306f8745e05736', 'extracted', 1);
