INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c1f8c44ff97c8970', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.7.1): “…Airflow toward the fire shall not exceed ______ per minute (______/s).…” — what value is stated?', '["1.5 m","2.05 m","1.02 m","0.51 m"]', 2, 'Clause 10.9.7.1 (GHBC-C-002562, page 484): Airflow toward the fire shall not exceed 200 feet per minute (1.02 m/s).', 'study', 'GHBC-C-002562', 'GHBC-REQ-008406', 484, '2c5640ef7ab3ee9f9d2b292f79e64f5dc72ca136a6e1e8be6bea3c6ee9644f70', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f0a794fddac3deff', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.8.1): “…smoke layer interface shall be maintained not less than ______ above a walking surface that forms a portion of a required Escape system within the smoke zone.…” — what value is stated?', '["1829 mm","914 mm","2743 mm","3658 mm"]', 0, 'Clause 10.9.8.1 (GHBC-C-002564, page 484): The height of the lowest horizontal surface of the smoke layer interface shall be maintained not less than 1829 mm (6 feet) above a walking surface that forms a portion of a required Escape system within the smoke zone.', 'standard', 'GHBC-C-002564', 'GHBC-REQ-008410', 484, 'ffe7f1f660171e1965dcbefc153ab5324186acc8b21452c4aeb535fef464d456', 'extracted', 1);
