INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e2f9baf25536c195', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.13.1): “…paint-grade steel enclosure having a minimum thickness of ______ (No. 22 gage).…” — what value is stated?', '["0.7534 mm","0.378 mm","1.14 mm","1.5 mm"]', 0, 'Clause 10.9.13.1 (GHBC-C-002587, page 486): Tubing and connected devices shall be completely enclosed within a galvanized or paint-grade steel enclosure having a minimum thickness of 0.7534 mm (0.0296 inch) (No. 22 gage).', 'standard', 'GHBC-C-002587', 'GHBC-REQ-008480', 486, '5d7de0aae2ef1db0cf26dc60dad4ff35d19d0a288dd43b927757ae84c3928fc1', 'extracted', 1);
