INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-952a5dd6adffbb47', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.13.3): “…at three times the operating pressure for not less than ______inutes without any noticeable loss in gauge pressure prior to final connection to devices.…” — what value is stated?', '["60 m","30 m","15 m","45 m"]', 1, 'Clause 10.9.13.3 (GHBC-C-002589, page 487): Control air tubing shall be tested at three times the operating pressure for not less than 30 minutes without any noticeable loss in gauge pressure prior to final connection to devices.', 'standard', 'GHBC-C-002589', 'GHBC-REQ-008490', 487, '490a65efc82a382b88d7a5008dfaa16abd9de7376762c5102edf9178ed6b81c0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f725945d81efd149', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.16): “…complying with Clause ______ high-rise buildings or buildings with smoke-protected assembly seating.…” — what value is stated?', '["10.11 in","5 in","15 in","20 in"]', 0, 'Clause 10.9.16 (GHBC-C-002592, page 487): complying with Clause 10.11 in high-rise buildings or buildings with smoke-protected assembly seating.', 'standard', 'GHBC-C-002592', 'GHBC-REQ-008495', 487, '9782a3fa42456f0753a61019d31bd60cca7ad92df719c69c1496238aa3fd275c', 'extracted', 1);
