INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-91b4636d63fdb937', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.20.1): “…to the vestibule but shall not have a width of less than ______ and shall not have a length of less than ______ in the direction of Escape travel.…” — what value is stated?', '["1676 mm","2210 mm","1118 mm","559 mm"]', 2, 'Clause 10.9.20.1 (GHBC-C-002613, page 490): The minimum dimension of the vestibule shall be not less than the required width of the corridor leading to the vestibule but shall not have a width of less than 1118 mm (44 inches) and shall not have a length of less than 1829 mm (72 inches) in the direction of Escape travel.', 'study', 'GHBC-C-002613', 'GHBC-REQ-008576', 490, '2caaf408330afb5aade835819acfe374b9e09a448bdd982ddc8ecc50425f1e6f', 'requires_review', 0);
