INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-deb2ec280a3a5d34', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.20.4.2): “…be located at the top of the smoke trap but not more than ______ down from the top of the trap, and shall be entirely within the smoke trap area.…” — what value is stated?', '["152 mm","76 mm","229 mm","304 mm"]', 0, 'Clause 10.9.20.4.2 (GHBC-C-002622, page 491): The top of the exhaust register shall be located at the top of the smoke trap but not more than 152 mm (6 inches) down from the top of the trap, and shall be entirely within the smoke trap area.', 'standard', 'GHBC-C-002622', 'GHBC-REQ-008598', 491, '10aefdc35e65de07f23f9ea4bf24a2ce6c7e426c7518f01b02afca96870257fd', 'extracted', 1);
