INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-95f7a31f57dda359', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.20.4.3): “…The vestibule ceiling shall be not less than ______ higher than the door opening into the vestibule to serve as a smoke and heat trap and to provide an upward-moving air column.…” — what value is stated?', '["508 mm","254 mm","762 mm","1016 mm"]', 0, 'Clause 10.9.20.4.3 (GHBC-C-002624, page 491): The vestibule ceiling shall be not less than 20 inches (508 mm) higher than the door opening into the vestibule to serve as a smoke and heat trap and to provide an upward-moving air column.', 'standard', 'GHBC-C-002624', 'GHBC-REQ-008604', 491, '60cde83a2182966bcb14ffe17d77170110ef9aa0f9ac7cc75106d0bd4563159b', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0cab235c674eed3f', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.20.4.4): “…air to maintain a minimum positive pressure of 25 Pa (______ of water) in the shaft relative to the vestibule with all doors closed.…” — what value is stated?', '["0.15 in","0.2 in","0.1 in","0.047 in"]', 2, 'Clause 10.9.20.4.4 (GHBC-C-002625, page 491): The stairway or ramp shaft shall be provided with a dampered relief opening and supplied with sufficient air to maintain a minimum positive pressure of 25 Pa (0.10 inch of water) in the shaft relative to the vestibule with all doors closed.', 'standard', 'GHBC-C-002625', 'GHBC-REQ-008607', 491, 'cf177f7c5ffd4269ae1e119b154b4463dd2c9670fdf7aeb1f54d6f97e4a1945d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-86bead5cd46c0e05', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.20.5): “…stairway or ramp is pressurized to not less than 25 Pa (______ of water) and not more than 87 Pa (______ of water) in the shaft relative to the building measured with all interior exit stairway and ramp doors closed……” — what value is stated?', '["0.1 in","0.047 in","0.15 in","0.2 in"]', 0, 'Clause 10.9.20.5 (GHBC-C-002626, page 491): Where the building is equipped throughout with an automatic sprinkler system in accordance with Clause 10.3.3.1.1, the vestibule is not required, provided that each interior exit stairway or ramp is pressurized to not less than 25 Pa (0.10 inch of water) and not more than 87 Pa (0.35 inches of water) in the shaft relative to the building measured with all interior exit stairway and ramp doors clos', 'standard', 'GHBC-C-002626', 'GHBC-REQ-008609', 491, 'b96fbca4a2f28b9f1d291a139f6778f81962f1c1011b60c9f4b68c397cf54258', 'extracted', 1);
