INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-524ad2992c1c7a69', NULL, NULL, 'threshold', 10, 'GS 1207:2018 Part 10 (Clause 10.9.21.1): “…to maintain a minimum positive pressure of 25 Pa (______ of water) and a maximum positive pressure of 67 Pa (______ of water) with respect to adjacent occupied space on all floors.…” — what value is stated?', '["0.25 in","0.128 in","0.375 in","0.5 in"]', 0, 'Clause 10.9.21.1 (GHBC-C-002632, page 492): Elevator hoistways shall be pressurized to maintain a minimum positive pressure of 25 Pa (0.10 inch of water) and a maximum positive pressure of 67 Pa (0.25 inch of water) with respect to adjacent occupied space on all floors.', 'standard', 'GHBC-C-002632', 'GHBC-REQ-008637', 492, '3ac1c3a3237e1e6210e6e691ad378f13de4fcdbcc1313e9d88a88d5789b45d8c', 'extracted', 1);
