INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7a523f1b239d1a91', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.3.5): “…with Clause 11.11.5, the minimum depth of the tread is ______ and not less than one handrail complying with Clause 11.14 is provided within ______ of the centreline of the normal path of escape travel on the stair.…” — what value is stated?', '["660 mm","330 mm","160 mm","500 mm"]', 1, 'Clause 11.3.5 (GHBC-C-002744, page 504): A stair with a single riser or with two risers and a tread is permitted at locations not required to be accessible by Part 11 where the risers and treads comply with Clause 11.11.5, the minimum depth of the tread is 330 mm (13 inches) and not less than one handrail complying with Clause 11.14 is provided within 762 mm (30 inches) of the centreline of the normal path of escape travel on the stair.', 'standard', 'GHBC-C-002744', 'GHBC-REQ-008978', 504, '39c49f9b7c6ac2e9b976016bbc7f9e787edbee2203bd7e18a17acdf7a2400657', 'extracted', 1);
