INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4a587369ea6828b8', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.3.5): “…seating that has a difference in elevation less than ______ at locations not required to be accessible by Part 12, provided that the risers and treads comply with Clause 11.29.14 and the aisle is provided with a……” — what value is stated?', '["152.4 mm","457 mm","610 mm","305 mm"]', 3, 'Clause 11.3.5 (GHBC-C-002744, page 504): A step is permitted in aisles serving seating that has a difference in elevation less than 305 mm (12 inches) at locations not required to be accessible by Part 12, provided that the risers and treads comply with Clause 11.29.14 and the aisle is provided with a handrail complying with Clause 11.29.16.', 'standard', 'GHBC-C-002744', 'GHBC-REQ-008980', 504, '2d1328e995f476da5fc092ce94139741623362dea573b5f9f2a5448ed8ff9ef0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fca91629b83afce0', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.3.5): “…seating that has a difference in elevation less than ______ at locations not required to be accessible by Part 12, provided that the risers and treads comply with Clause 11.29.14 and the aisle is provided with a……” — what value is stated?', '["24 in","12 in","6 in","18 in"]', 1, 'Clause 11.3.5 (GHBC-C-002744, page 504): A step is permitted in aisles serving seating that has a difference in elevation less than 305 mm (12 inches) at locations not required to be accessible by Part 12, provided that the risers and treads comply with Clause 11.29.14 and the aisle is provided with a handrail complying with Clause 11.29.16.', 'standard', 'GHBC-C-002744', 'GHBC-REQ-008980', 504, '2d1328e995f476da5fc092ce94139741623362dea573b5f9f2a5448ed8ff9ef0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-776282e91dfaacbb', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.1.1): “…Door hardware which does not intrude more than ______ into this width may be ignored.…” — what value is stated?', '["50 mm","150 mm","200 mm","100 mm"]', 3, 'Clause 11.4.1.1 (GHBC-C-002749, page 505): Door hardware which does not intrude more than 100 mm into this width may be ignored.', 'study', 'GHBC-C-002749', 'GHBC-REQ-009000', 505, '493335b344e9066a49635a8119c2ba02d0db15bdadeaf92216533ebc1a186e49', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d72da444f6e59d2c', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.1.1): “…(ii) an escape route is the width at ______ above floor level when defined by walls (handrails fixed to walls which do not intrude more than ______ into this width may be ignored) or elsewhere the minimum width of……” — what value is stated?', '["750 mm","2286 mm","3048 mm","1500 mm"]', 3, 'Clause 11.4.1.1 (GHBC-C-002749, page 505): (ii) an escape route is the width at 1500 mm above floor level when defined by walls (handrails fixed to walls which do not intrude more than 100 mm into this width may be ignored) or elsewhere the minimum width of passage available between any fixed obstructions; and', 'standard', 'GHBC-C-002749', 'GHBC-REQ-009003', 505, '686d01cb819acb72545e87a26d6fa7e34db2c3635a62918200e6626dabb36661', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d72da444f6e59d2c', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.1.1): “…(ii) an escape route is the width at ______ above floor level when defined by walls (handrails fixed to walls which do not intrude more than ______ into this width may be ignored) or elsewhere the minimum width of……” — what value is stated?', '["50 mm","150 mm","200 mm","100 mm"]', 3, 'Clause 11.4.1.1 (GHBC-C-002749, page 505): (ii) an escape route is the width at 1500 mm above floor level when defined by walls (handrails fixed to walls which do not intrude more than 100 mm into this width may be ignored) or elsewhere the minimum width of passage available between any fixed obstructions; and', 'standard', 'GHBC-C-002749', 'GHBC-REQ-009003', 505, '686d01cb819acb72545e87a26d6fa7e34db2c3635a62918200e6626dabb36661', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5e5a54a04dcd5e07', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.1.1): “…(strings and handrails intruding not more than ______ and ______ respectively may be ignored).…” — what value is stated?', '["15 mm","45 mm","60 mm","30 mm"]', 3, 'Clause 11.4.1.1 (GHBC-C-002749, page 505): (iii) a stairway is the clear width between the walls or balustrades, (strings and handrails intruding not more than 30 mm and 100 mm respectively may be ignored).', 'standard', 'GHBC-C-002749', 'GHBC-REQ-009004', 505, '46df761688f7103efaa475a08d4c508c2f54046f7228c12294eeb71403b9c361', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5e5a54a04dcd5e07', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.1.1): “…(strings and handrails intruding not more than ______ and ______ respectively may be ignored).…” — what value is stated?', '["50 mm","150 mm","200 mm","100 mm"]', 3, 'Clause 11.4.1.1 (GHBC-C-002749, page 505): (iii) a stairway is the clear width between the walls or balustrades, (strings and handrails intruding not more than 30 mm and 100 mm respectively may be ignored).', 'standard', 'GHBC-C-002749', 'GHBC-REQ-009004', 505, '46df761688f7103efaa475a08d4c508c2f54046f7228c12294eeb71403b9c361', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-21a0205151213d0a', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.5): “…Note: For SI: ______ = ______, 1 square foot = ______. a.…” — what value is stated?', '["610 mm","304.8 mm","152.4 mm","457 mm"]', 1, 'Clause 11.4.5 (GHBC-C-002756, page 506): Note: For SI: 1 foot = 304.8 mm, 1 square foot = 0.0929 m2. a.', 'study', 'GHBC-C-002756', 'GHBC-REQ-009019', 506, '93a9c13ab43b609efa1fe8d133690eeb190e57dc288348a81191d4515b85b6ea', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-20cd3cc405b6e25d', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.5): “…Note: For SI: ______ = ______, 1 square foot = ______. a.…” — what value is stated?', '["0.035 m2","0.19 m2","0.2 m2","0.0929 m2"]', 3, 'Clause 11.4.5 (GHBC-C-002756, page 506): Note: For SI: 1 foot = 304.8 mm, 1 square foot = 0.0929 m2. a.', 'study', 'GHBC-C-002756', 'GHBC-REQ-009019', 506, '93a9c13ab43b609efa1fe8d133690eeb190e57dc288348a81191d4515b85b6ea', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-231ed1bf50217105', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.5.1): “…and the occupant load does not exceed one occupant per ______ of occupiable floor space.…” — what value is stated?', '["0.65 m2","0.305 m2","1 m2","1.25 m2"]', 0, 'Clause 11.4.5.1 (GHBC-C-002757, page 506): occupancies in Table 11.4.5, provided that all other requirements of the Code are met based on such modified number and the occupant load does not exceed one occupant per 0.65 m2 (7 square feet) of occupiable floor space.', 'study', 'GHBC-C-002757', 'GHBC-REQ-009023', 506, '60527ea82717dcf723828e20433d7073604a8b7737dc89591d9085c332921c45', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d1a1e326349df4b4', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.6): “…less than the number of seats based on one person for each ______ of seating length.…” — what value is stated?', '["914 mm","457 mm","229 mm","686 mm"]', 1, 'Clause 11.4.6 (GHBC-C-002758, page 507): For areas having fixed seating without dividing arms, the occupant load shall be not less than the number of seats based on one person for each 457 mm (18 inches) of seating length.', 'standard', 'GHBC-C-002758', 'GHBC-REQ-009029', 507, '541f496fa7fd2bfc74a16e0601857c427f0fa71af8572dacfe5effc9e9c8e90c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-baed1dd147a60631', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.6): “…less than the number of seats based on one person for each ______ of seating length.…” — what value is stated?', '["36 in","18 in","9 in","27 in"]', 1, 'Clause 11.4.6 (GHBC-C-002758, page 507): For areas having fixed seating without dividing arms, the occupant load shall be not less than the number of seats based on one person for each 457 mm (18 inches) of seating length.', 'standard', 'GHBC-C-002758', 'GHBC-REQ-009029', 507, '541f496fa7fd2bfc74a16e0601857c427f0fa71af8572dacfe5effc9e9c8e90c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7a05d1d64608252c', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.6): “…of seating booths shall be based on one person for each ______ of booth seat length measured at the backrest of the seating booth.…” — what value is stated?', '["305 mm","915 mm","1220 mm","610 mm"]', 3, 'Clause 11.4.6 (GHBC-C-002758, page 507): The occupant load of seating booths shall be based on one person for each 610 mm (24 inches) of booth seat length measured at the backrest of the seating booth.', 'standard', 'GHBC-C-002758', 'GHBC-REQ-009030', 507, 'b38a9f646e40d07c5755e309bd7fd65cb27d4ef49e43747849941831ca4141ab', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2591ead1c3bf4f5', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.6): “…of seating booths shall be based on one person for each ______ of booth seat length measured at the backrest of the seating booth.…” — what value is stated?', '["36 in","48 in","24 in","12 in"]', 2, 'Clause 11.4.6 (GHBC-C-002758, page 507): The occupant load of seating booths shall be based on one person for each 610 mm (24 inches) of booth seat length measured at the backrest of the seating booth.', 'standard', 'GHBC-C-002758', 'GHBC-REQ-009030', 507, 'b38a9f646e40d07c5755e309bd7fd65cb27d4ef49e43747849941831ca4141ab', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5971ebacd4a7be0b', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.4.8): “…actual occupant load, but not less than one occupant per ______ of gross occupiable floor space.…” — what value is stated?', '["7.43 m2","9.3 m2","4.65 m2","2.32 m2"]', 2, 'Clause 11.4.8 (GHBC-C-002760, page 507): Where approved by the building official, the occupant load for concentrated business use areas shall be the actual occupant load, but not less than one occupant per 4.65 m2 (50 square feet) of gross occupiable floor space.', 'standard', 'GHBC-C-002760', 'GHBC-REQ-009040', 507, 'c752a0aeda1588c0c1a139e88f24d1b25f9f819cd712b59bd6256701f01c0e12', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-557d54e992a49c51', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…The capacity______ inches, of means of escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of ______ per occupant.…” — what value is stated?', '["7.6 mm","3.8 mm","11.16 mm","15.2 mm"]', 0, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): The capacity, in inches, of means of escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of 7.6 mm (0.3 inch) per occupant.', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009048', 508, '73be89dbec9e9c6af3968d3d8ac9b8f7d2a7179c4f8fe3e55dfca642ff133b1c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a5a91af2058af1ef', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…The capacity______ inches, of means of escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of ______ per occupant.…” — what value is stated?', '["0.3 in","0.15 in","0.45 in","0.6 in"]', 0, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): The capacity, in inches, of means of escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of 7.6 mm (0.3 inch) per occupant.', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009048', 508, '73be89dbec9e9c6af3968d3d8ac9b8f7d2a7179c4f8fe3e55dfca642ff133b1c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8beceeaa2e79f7e8', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…For other than Group H and I-2 occupancies, the capacity______ inches, of means of Escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of……” — what value is stated?', '["7.6 mm","10.01 mm","5.1 mm","2.54 mm"]', 2, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): For other than Group H and I-2 occupancies, the capacity, in inches, of means of Escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of 5.1 mm (0.2 inch) per occupant in buildings equipped throughout with an automatic sprinkler system installed in accordance with Clause 10.3.3.1.1 or 10.3..3.1.2 and an emergency voice/', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009052', 508, 'eb7e5b5873af70866dbdccc9371b88275fd81128cd650cbfcd93ec17c54d7d37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3d4b5598b9f8be1c', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…For other than Group H and I-2 occupancies, the capacity______ inches, of means of Escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of……” — what value is stated?', '["0.1 in","0.3 in","0.375 in","0.2 in"]', 3, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): For other than Group H and I-2 occupancies, the capacity, in inches, of means of Escape stairways shall be calculated by multiplying the occupant load served by such stairways by a means of escape capacity factor of 5.1 mm (0.2 inch) per occupant in buildings equipped throughout with an automatic sprinkler system installed in accordance with Clause 10.3.3.1.1 or 10.3..3.1.2 and an emergency voice/', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009052', 508, 'eb7e5b5873af70866dbdccc9371b88275fd81128cd650cbfcd93ec17c54d7d37', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3905b17df2668639', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…shall be permitted to use the capacity factors in Table ______dicated for stepped aisles for exit access or exit stairways where the entire path for means of escape from the seating to the exit discharge is provided……” — what value is stated?', '["12.1 in","6.2 in","3.1 in","9.3 in"]', 1, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): Facilities with smoke-protected assembly seating shall be permitted to use the capacity factors in Table 11.29.6.2 indicated for stepped aisles for exit access or exit stairways where the entire path for means of escape from the seating to the exit discharge is provided with a smoke control system complying with Clause 10.9.', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009054', 508, 'af6e6c5896283137646541b42f3823b07758af2977f971ab7ab677d0e88ffb50', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-483d788c5d0da1d0', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.1): “…shall be permitted to the capacity factors in Clause ______dicated for stepped aisles for exit access or exit stairways where the entire path for means of escape from the seating to the exit discharge is open to the……” — what value is stated?', '["6.3 in","3.1 in","9.5 in","13 in"]', 0, 'Clause 11.5.3.1 (GHBC-C-002765, page 508): Facilities with open-air assembly seating shall be permitted to the capacity factors in Clause 11.29.6.3 indicated for stepped aisles for exit access or exit stairways where the entire path for means of escape from the seating to the exit discharge is open to the outdoors.', 'standard', 'GHBC-C-002765', 'GHBC-REQ-009056', 508, 'cc9f61de4eb0c130f029cd553ec8163387dfcb5894862f3ae9a953484e39b72f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d3870fee93b3189a', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.2): “…The capacity______ inches, of means of escape components other than stairways shall be calculated by multiplying the occupant load served by such component by a means of escape capacity factor of ______ per occupant.…” — what value is stated?', '["5.1 mm","2.54 mm","7.6 mm","10.01 mm"]', 0, 'Clause 11.5.3.2 (GHBC-C-002766, page 508): The capacity, in inches, of means of escape components other than stairways shall be calculated by multiplying the occupant load served by such component by a means of escape capacity factor of 5.1 mm (0.2 inch) per occupant.', 'standard', 'GHBC-C-002766', 'GHBC-REQ-009057', 508, '610a34149b1de763b3ef405696f92a36a90116f1f80e860bfb8fa4ee35454a39', 'extracted', 1);
