INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-782b24d5c36fe671', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.5.3.2): “…For other than Group H and I-2 occupancies, the capacity______ inches, of means of Escape components other than stairways shall be calculated by multiplying the occupant load served by such component by a means of……” — what value is stated?', '["7.6 mm","3.8 mm","1.9 mm","5.6 mm"]', 1, 'Clause 11.5.3.2 (GHBC-C-002766, page 508): For other than Group H and I-2 occupancies, the capacity, in inches, of means of Escape components other than stairways shall be calculated by multiplying the occupant load served by such component by a means of escape capacity factor of 3.8 mm (0.15 inch) per occupant in buildings equipped throughout with anautomatic sprinkler system installed in accordance with Clause 10.3.3.1.1 or 10.3.3.1.2 an', 'standard', 'GHBC-C-002766', 'GHBC-REQ-009060', 508, 'fe4f789473cdc9c9dfaf1dca5cd955721c675304138cd04dd2de7c640d00be82', 'extracted', 1);
