INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f4fb2da7117b76a8', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.6.2.2.1): “…Two exit access doorways are required in boiler______cinerator and furnace rooms where the area is over ______ and any fuel-fired equipment exceeds 422 000 KJ (400,000 British thermal units (Btu)) input capacity.…” — what value is stated?', '["46 m2","23 m2","70 m2","92.9 m2"]', 0, 'Clause 11.6.2.2.1 (GHBC-C-002779, page 510): Two exit access doorways are required in boiler, incinerator and furnace rooms where the area is over 46 m2 (500 square feet) and any fuel-fired equipment exceeds 422 000 KJ (400,000 British thermal units (Btu)) input capacity.', 'standard', 'GHBC-C-002779', 'GHBC-REQ-009108', 510, '9161f72fef2d28f03d9ab26cf06599b7eccc654bf41b6fb03fb21af9980dbe3e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e92887873e0a64e4', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.6.2.2.2): “…Machinery rooms larger than ______ shall have not less than two exits or exit access doorways.…” — what value is stated?', '["46.5 m2","139.4 m2","186 m2","93 m2"]', 3, 'Clause 11.6.2.2.2 (GHBC-C-002780, page 511): Machinery rooms larger than 93 m2 (1,000 square feet) shall have not less than two exits or exit access doorways.', 'standard', 'GHBC-C-002780', 'GHBC-REQ-009112', 511, 'db4d149f111304cf4674ee48820e60271755cd0c6a6f5ea003b4257ec7f6ebb0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c6ddc36103b76ad0', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.6.2.2.2): “…All portions of machinery rooms shall be within 45 ______ of an exit or exit access doorway.…” — what value is stated?', '["1499 mm","720 mm","356 mm","1067 mm"]', 1, 'Clause 11.6.2.2.2 (GHBC-C-002780, page 511): All portions of machinery rooms shall be within 45 720 mm (150 feet) of an exit or exit access doorway.', 'standard', 'GHBC-C-002780', 'GHBC-REQ-009115', 511, '53ebade6355d966b18d33b4ab2a8e6ec5161ed59fe5fc604804ce7ccdc9b60dd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9e2c1d2b6ea19ebd', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.6.2.2.2): “…All portions of machinery rooms shall be within 45 ______ of an exit or exit access doorway.…” — what value is stated?', '["150 feet","75 feet","200 feet","300 feet"]', 0, 'Clause 11.6.2.2.2 (GHBC-C-002780, page 511): All portions of machinery rooms shall be within 45 720 mm (150 feet) of an exit or exit access doorway.', 'standard', 'GHBC-C-002780', 'GHBC-REQ-009115', 511, '53ebade6355d966b18d33b4ab2a8e6ec5161ed59fe5fc604804ce7ccdc9b60dd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4317706573cd2525', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.6.2.2.3): “…Rooms or spaces having a floor area larger than ______, containing a refrigerant evapourator and maintained at a temperature below 20°C (68°F), shall have access to not less than two exits or exit access doorways.…” — what value is stated?', '["139.4 m2","186 m2","93 m2","46.5 m2"]', 2, 'Clause 11.6.2.2.3 (GHBC-C-002781, page 511): Rooms or spaces having a floor area larger than 93 m2 (1,000 square feet), containing a refrigerant evapourator and maintained at a temperature below 20°C (68°F), shall have access to not less than two exits or exit access doorways.', 'standard', 'GHBC-C-002781', 'GHBC-REQ-009119', 511, '26b380a17481f7c00b4579cec72cdd66f0bdef06dcec045f1d6c6afacca2e99d', 'extracted', 1);
