INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-677211c39a44ed13', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.9.7.2): “…extend vertically from the ground to a point not less than ______ above the floor level of the area for assisted rescue or to the roof line, whichever is lower.…” — what value is stated?', '["15 feet","20 feet","10 feet","5 feet"]', 2, 'Clause 11.9.7.2 (GHBC-C-002824, page 518): The fire-resistance-rated construction shall extend vertically from the ground to a point not less than 3048 mm (10 feet) above the floor level of the area for assisted rescue or to the roof line, whichever is lower.', 'standard', 'GHBC-C-002824', 'GHBC-REQ-009355', 518, '7668cf9d3c7dfaa22d3842f99893f5d4d1e83ac780e6cc36e8fcde9fbc3a6a98', 'extracted', 1);
