INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d9402ffe3a53da3f', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.1.4.1.2): “…coverage in areas within the building that are within 22 ______ of the revolving doors. 4. There is an actuation of a manual control switch______ an approved location and clearly identified, that reduces the breakout……” — what value is stated?', '["440 mm","1230 mm","1753 mm","860 mm"]', 3, 'Clause 11.10.1.4.1.2 (GHBC-C-002841, page 523): EXCEPTIONS: A breakout force in excess of 801 N (180 pounds) is permitted if the breakout force is reduced to not more than 578 N (130 pounds) when not less than one of the following conditions is satisfied: 1. There is a power failure or power is removed to the device holding the door wings in position. 2. There is an actuation of the automatic sprinkler system where such system is provided. 3. T', 'standard', 'GHBC-C-002841', 'GHBC-REQ-009494', 523, 'e3b7727d9201d7f7c7c675573af65b5287ffc273f7c6f6cf322aaa0c01d90cf7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-834655e287d7b531', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.1.4.1.2): “…coverage in areas within the building that are within 22 ______ of the revolving doors. 4. There is an actuation of a manual control switch______ an approved location and clearly identified, that reduces the breakout……” — what value is stated?', '["40 feet","120 feet","150 feet","75 feet"]', 3, 'Clause 11.10.1.4.1.2 (GHBC-C-002841, page 523): EXCEPTIONS: A breakout force in excess of 801 N (180 pounds) is permitted if the breakout force is reduced to not more than 578 N (130 pounds) when not less than one of the following conditions is satisfied: 1. There is a power failure or power is removed to the device holding the door wings in position. 2. There is an actuation of the automatic sprinkler system where such system is provided. 3. T', 'standard', 'GHBC-C-002841', 'GHBC-REQ-009494', 523, 'e3b7727d9201d7f7c7c675573af65b5287ffc273f7c6f6cf322aaa0c01d90cf7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6b126886a8af544f', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.1.4.2): “…a multiple-leaf opening shall be exempt from the minimum ______ single-leaf requirement of Clause 11.10.1.1, provided that a minimum ______ clear opening is provided when the two biparting leaves meeting in the center……” — what value is stated?', '["813 mm","406 mm","1219 mm","1676 mm"]', 0, 'Clause 11.10.1.4.2 (GHBC-C-002842, page 523): For a biparting door in the emergency breakout mode, a door leaf located within a multiple-leaf opening shall be exempt from the minimum 813 mm (32-inch) single-leaf requirement of Clause 11.10.1.1, provided that a minimum 813 mm (32-inch) clear opening is provided when the two biparting leaves meeting in the center are broken out.', 'standard', 'GHBC-C-002842', 'GHBC-REQ-009507', 523, '20ea94cd675a7864bc12d6e33b90467ceb59a95240395fcbb4617fdc81bcdd9a', 'extracted', 1);
