INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-347b5ee997006629', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.1.5): “…landing at an exterior doorway shall be not more than 73/______ below the top of the threshold, provided the door, other than an exterior storm or screen door, does not swing over the landing.…” — what value is stated?', '["8 in","4 in","2 in","6 in"]', 1, 'Clause 11.10.1.5 (GHBC-C-002845, page 524): In Group R-3 occupancies not required to be Accessible units, Type A units or Type B units, the landing at an exterior doorway shall be not more than 73/4 inches (197 mm) below the top of the threshold, provided the door, other than an exterior storm or screen door, does not swing over the landing.', 'standard', 'GHBC-C-002845', 'GHBC-REQ-009548', 524, 'b987d3ea68781a77242a5203b9f67f220b1099c026e4826c6611c09b9ddad6a1', 'extracted', 1);
