INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6764d4d229294bb4', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.1.10): “…rooms with equipment rated 1,200 amperes or more and over ______ wide, and that contain overcurrent devices, switching devices or control devices with exit or exit access doors, shall be equipped with panic hardware or……” — what value is stated?', '["1829 mm","914 mm","2743 mm","3658 mm"]', 0, 'Clause 11.10.1.10 (GHBC-C-002860, page 530): Electrical rooms with equipment rated 1,200 amperes or more and over 1829 mm (6 feet) wide, and that contain overcurrent devices, switching devices or control devices with exit or exit access doors, shall be equipped with panic hardware or fire exit hardware.', 'standard', 'GHBC-C-002860', 'GHBC-REQ-009733', 530, '92bbf8f6b80ab7dc1206a213538c362145def0890f95016ee29e8ecded6386de', 'extracted', 1);
