INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9fc32db71feeda9c', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.10.2.1): “…public is present, and where safe dispersal areas based on ______ per occupant are located between the fence and enclosed space.…” — what value is stated?', '["0.28 m2","0.093 m2","0.4 m2","0.56 m2"]', 0, 'Clause 11.10.2.1 (GHBC-C-002864, page 531): Panic hardware is not required on gates surrounding stadiums where such gates are under constant immediate supervision while the public is present, and where safe dispersal areas based on 0.28 m2 (3 square feet) per occupant are located between the fence and enclosed space.', 'standard', 'GHBC-C-002864', 'GHBC-REQ-009747', 531, '5efd53f2a5c37a3133c2ced1dc8fc18918578c2e7250f796c54aed0d8c43aa44', 'extracted', 1);
