INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9bb5b9011bbce275', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.11.5.5.1): “…edge (nosings) of treads shall project not more than ______ beyond the tread below.…” — what value is stated?', '["2 in","6 in","8 in","4 in"]', 3, 'Clause 11.11.5.5.1 (GHBC-C-002882, page 534): The leading edge (nosings) of treads shall project not more than 32 mm (11/4 inches) beyond the tread below.', 'standard', 'GHBC-C-002882', 'GHBC-REQ-009851', 534, 'daec08a7b88023d9a442460a6eace1787b8c474e87cb7893f1d9b9bea142097c', 'extracted', 1);
