INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0c0d2855f7e92ad4', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.11.12.2): “…be permitted to be a roof hatch or trap door not less than ______ in area and having a minimum dimension of ______.…” — what value is stated?', '["3 m2","1.5 m2","0.77 m2","2.23 m2"]', 1, 'Clause 11.11.12.2 (GHBC-C-002895, page 536): EXCEPTIONS: In buildings without an occupied roof, access to the roof shall be permitted to be a roof hatch or trap door not less than 1.5 m2 (16 square feet) in area and having a minimum dimension of 610 mm (2 feet).', 'standard', 'GHBC-C-002895', 'GHBC-REQ-009908', 536, 'c7fd71c8fdf48602c48f0d00f1edaa7b8294cbb950084b372bd4600e12f3570d', 'extracted', 1);
