INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2988cf72902237d7', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.11.15): “…or elevated facility observation stations not more than ______ with not more than three occupants and for access to unoccupied roofs.…” — what value is stated?', '["11.2 m2","37 m2","46 m2","23 m2"]', 3, 'Clause 11.11.15 (GHBC-C-002899, page 537): Ships ladders are permitted to be used in Group I-3 as a component of a means of escape to and from control rooms or elevated facility observation stations not more than 23 m2 (250 square feet) with not more than three occupants and for access to unoccupied roofs.', 'standard', 'GHBC-C-002899', 'GHBC-REQ-009923', 537, '4e99bab011767aa8da9cc551588f31aa35bb8c4844999c69b74f6f6766aa70a0', 'extracted', 1);
