INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-175ada8f5c34652f', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.25.3): “…ASTM E2072, except that the charging source shall be ______candle (11 lux) of fluorescent illumination for ______inutes, and the minimum luminance shall be ______ilicandelas per square meter at ______inutes and……” — what value is stated?', '["90 m","120 m","60 m","30 m"]', 2, 'Clause 11.25.3 (GHBC-C-003026, page 557): ASTM E2072, except that the charging source shall be 1 footcandle (11 lux) of fluorescent illumination for 60 minutes, and the minimum luminance shall be 30 milicandelas per square meter at 10 minutes and milicandelas per square meter after 905 minutes.', 'standard', 'GHBC-C-003026', 'GHBC-REQ-010510', 557, '6023cfc92a9014bbc415dab378dcd881a9876f1cf5fd8efdae1fe04386c2cdb8', 'extracted', 1);
