INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-175ada8f5c34652f', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.25.3): “…ASTM E2072, except that the charging source shall be ______candle (11 lux) of fluorescent illumination for ______inutes, and the minimum luminance shall be ______ilicandelas per square meter at ______inutes and……” — what value is stated?', '["15 m","20 m","10 m","5 m"]', 2, 'Clause 11.25.3 (GHBC-C-003026, page 557): ASTM E2072, except that the charging source shall be 1 footcandle (11 lux) of fluorescent illumination for 60 minutes, and the minimum luminance shall be 30 milicandelas per square meter at 10 minutes and milicandelas per square meter after 905 minutes.', 'standard', 'GHBC-C-003026', 'GHBC-REQ-010510', 557, '6023cfc92a9014bbc415dab378dcd881a9876f1cf5fd8efdae1fe04386c2cdb8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-175ada8f5c34652f', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.25.3): “…ASTM E2072, except that the charging source shall be ______candle (11 lux) of fluorescent illumination for ______inutes, and the minimum luminance shall be ______ilicandelas per square meter at ______inutes and……” — what value is stated?', '["1629 m","1800 m","905 m","450 m"]', 2, 'Clause 11.25.3 (GHBC-C-003026, page 557): ASTM E2072, except that the charging source shall be 1 footcandle (11 lux) of fluorescent illumination for 60 minutes, and the minimum luminance shall be 30 milicandelas per square meter at 10 minutes and milicandelas per square meter after 905 minutes.', 'standard', 'GHBC-C-003026', 'GHBC-REQ-010510', 557, '6023cfc92a9014bbc415dab378dcd881a9876f1cf5fd8efdae1fe04386c2cdb8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-10a95ba181e25c31', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.25.5): “…are installed, they shall be provided with not less than ______candle (11 lux) of illumination for not less than ______inutes prior to periods when the building is occupied and continuously during occupancy.…” — what value is stated?', '["60 m","30 m","90 m","120 m"]', 0, 'Clause 11.25.5 (GHBC-C-003027, page 558): Where photoluminescent exit path markings are installed, they shall be provided with not less than 1 footcandle (11 lux) of illumination for not less than 60 minutes prior to periods when the building is occupied and continuously during occupancy.', 'standard', 'GHBC-C-003027', 'GHBC-REQ-010511', 558, '0e37b1c54a0d6c6c24f4106e1c02ac9c956002749c616e5b7c288203920bea56', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9e7049280229edb6', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.26.1): “…Not less than ______ of accessible space per occupant shall be provided on each side of the horizontal exit for the total number of people in adjoining compartments.…” — what value is stated?', '["0.6 m2","0.3 m2","0.93 m2","1.25 m2"]', 0, 'Clause 11.26.1 (GHBC-C-003028, page 558): Not less than 0.6 m2 (6 square feet) of accessible space per occupant shall be provided on each side of the horizontal exit for the total number of people in adjoining compartments.', 'standard', 'GHBC-C-003028', 'GHBC-REQ-010519', 558, '2381549a6ce1218b699d1bd4e28c6549ca48e41506ffc9ec82cad8c8fc5c9456', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-750ddfd90920108e', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.26.2): “…that the distance between connected buildings is more than ______.…” — what value is stated?', '["10000 mm","6096 mm","3048 mm","9144 mm"]', 1, 'Clause 11.26.2 (GHBC-C-003029, page 558): EXCEPTIONS: A fire-resistance rating is not required at horizontal exits between a building area and an above-grade pedestrian walkway constructed in accordance with Clause 32.4, provided that the distance between connected buildings is more than 6096 mm (20 feet).', 'standard', 'GHBC-C-003029', 'GHBC-REQ-010527', 558, 'dbc2f95b6f01034bc1c4fde063f64b233e397b0c41611a70d8598aab3e3013de', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-890eb3f10a54ab27', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.26.2): “…that the distance between connected buildings is more than ______.…” — what value is stated?', '["20 feet","10 feet","30 feet","40 feet"]', 0, 'Clause 11.26.2 (GHBC-C-003029, page 558): EXCEPTIONS: A fire-resistance rating is not required at horizontal exits between a building area and an above-grade pedestrian walkway constructed in accordance with Clause 32.4, provided that the distance between connected buildings is more than 6096 mm (20 feet).', 'standard', 'GHBC-C-003029', 'GHBC-REQ-010527', 558, 'dbc2f95b6f01034bc1c4fde063f64b233e397b0c41611a70d8598aab3e3013de', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fc50b17d2632a24a', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.26.4.1): “…shall be computed based on a net floor area allowance of ______ for each occupant to be accommodated therein.…” — what value is stated?', '["0.4 m2","0.557 m2","0.2787 m2","0.093 m2"]', 2, 'Clause 11.26.4.1 (GHBC-C-003032, page 558): The capacity of the refuge area shall be computed based on a net floor area allowance of 0.2787 m2 (3 square feet) for each occupant to be accommodated therein.', 'standard', 'GHBC-C-003032', 'GHBC-REQ-010532', 558, '1597842d30d12192b0781a3fa4e948dca017a985b08db191ea017065cc42fa1a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7dccf5c3750aaf14', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.3): “…An open side shall have not less than ______ of aggregate open area adjacent to each floor level and the level…” — what value is stated?', '["1.67 m2","5 m2","6.5 m2","3.3 m2"]', 3, 'Clause 11.27.3 (GHBC-C-003037, page 559): An open side shall have not less than 3.3 m2 (35 square feet) of aggregate open area adjacent to each floor level and the level', 'standard', 'GHBC-C-003037', 'GHBC-REQ-010542', 559, '5ef2f781f2c269ef51f9c70fd3788dbd8410edc39cb639429cebb5d68f9e9cf6', 'extracted', 1);
