INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f63def0898655dcf', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.3): “…The required open area shall be located not less than ______ above the adjacent floor or landing level.…” — what value is stated?', '["66 in","84 in","42 in","21 in"]', 2, 'Clause 11.27.3 (GHBC-C-003037, page 559): The required open area shall be located not less than 1067 mm (42 inches) above the adjacent floor or landing level.', 'standard', 'GHBC-C-003037', 'GHBC-REQ-010544', 559, '67031fe47447480db12fc6f4f57db9258500e66124a09e043ab1f5f7066f8e16', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1f2d76e91e57d11d', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.5): “…and ramps shall have a minimum fire separation distance of ______ measured at right angles from the exterior edge of the stairway or ramps______cluding landings, to:…” — what value is stated?', '["1524 mm","4572 mm","6096 mm","3048 mm"]', 3, 'Clause 11.27.5 (GHBC-C-003039, page 559): Exterior exit stairways and ramps shall have a minimum fire separation distance of 3048 mm (10 feet) measured at right angles from the exterior edge of the stairway or ramps, including landings, to:', 'standard', 'GHBC-C-003039', 'GHBC-REQ-010546', 559, 'e801046c1017a17d2124a183a06e1183ca04dabbea9c7e9da769f686b2a871a3', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-df29d94cce8da5dd', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.5): “…and ramps shall have a minimum fire separation distance of ______ measured at right angles from the exterior edge of the stairway or ramps______cluding landings, to:…” — what value is stated?', '["15 feet","20 feet","10 feet","5 feet"]', 2, 'Clause 11.27.5 (GHBC-C-003039, page 559): Exterior exit stairways and ramps shall have a minimum fire separation distance of 3048 mm (10 feet) measured at right angles from the exterior edge of the stairway or ramps, including landings, to:', 'standard', 'GHBC-C-003039', 'GHBC-REQ-010546', 559, 'e801046c1017a17d2124a183a06e1183ca04dabbea9c7e9da769f686b2a871a3', 'extracted', 1);
