INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f0af3a78c4974f5a', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.5): “…Group R-3 shall have a minimum fire separation distance of ______.…” — what value is stated?', '["5 feet","3 feet","8 feet","10 feet"]', 0, 'Clause 11.27.5 (GHBC-C-003039, page 559): EXCEPTIONS: Exterior exit stairways and ramps serving individual dwelling units of Group R-3 shall have a minimum fire separation distance of 1525 mm (5 feet).', 'standard', 'GHBC-C-003039', 'GHBC-REQ-010554', 559, 'b0893335e6c1cdb7d4d217e8747ee445b64fa77c90e0664f0ef0f6f321e4ae70', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0e9ecbcd347fe905', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.6): “…for occupancies, other than those in Group R-1 or R-______ buildings that are…” — what value is stated?', '["-2 in","-1.2 in","-3 in","-4 in"]', 0, 'Clause 11.27.6 (GHBC-C-003040, page 559): Separation from the interior of the building is not required for occupancies, other than those in Group R-1 or R-2, in buildings that are', 'standard', 'GHBC-C-003040', 'GHBC-REQ-010560', 559, 'ff5267d5d615782869b73313992c922ff18be33d9adaad22783beb8d48cb1876', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-71746d4508404536', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.6): “…enclosing wall, with the top of the openings not less than ______ above the top of the balcony.…” — what value is stated?', '["3200 mm","4267 mm","2134 mm","1067 mm"]', 2, 'Clause 11.27.6 (GHBC-C-003040, page 559): To be considered open, the opening shall be not less than 50 percent of the height of the enclosing wall, with the top of the openings not less than 2134 mm (7 feet) above the top of the balcony.', 'standard', 'GHBC-C-003040', 'GHBC-REQ-010564', 559, '4abba7ce3ceb95e743de587b4fd5ccce51a2a78972337adc92025291fda08e86', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ca25ba7dbed33dff', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.6): “…enclosing wall, with the top of the openings not less than ______ above the top of the balcony.…” — what value is stated?', '["3.5 feet","10 feet","14 feet","7 feet"]', 3, 'Clause 11.27.6 (GHBC-C-003040, page 559): To be considered open, the opening shall be not less than 50 percent of the height of the enclosing wall, with the top of the openings not less than 2134 mm (7 feet) above the top of the balcony.', 'standard', 'GHBC-C-003040', 'GHBC-REQ-010564', 559, '4abba7ce3ceb95e743de587b4fd5ccce51a2a78972337adc92025291fda08e86', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c982353a9671b5c3', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.27.6): “…(0.79 rad) occurs, a clear opening of not less than ______ or an exterior stairway or ramp shall be provided.…” — what value is stated?', '["1.67 m2","5 m2","6.5 m2","3.3 m2"]', 3, 'Clause 11.27.6 (GHBC-C-003040, page 559): At any location in an open-ended corridor where a change of direction exceeding 45 degrees (0.79 rad) occurs, a clear opening of not less than 3.3 m2 (35 square feet) or an exterior stairway or ramp shall be provided.', 'standard', 'GHBC-C-003040', 'GHBC-REQ-010576', 559, '5d634e388cb3b7fdaad5077f0a758cb955e7255923a5f1fa2aa8ca357320c5c7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8dfaf98e6cd63a20', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.28.1): “…or ramp shall be separated by a distance of not less than ______ or not less than one-fourth the length of the maximum overall diagonal dimension of the building, whichever is less.…” — what value is stated?', '["7620 mm","9144 mm","4572 mm","16000 mm"]', 1, 'Clause 11.28.1 (GHBC-C-003041, page 560): Where a required interior exit stairway or ramp and an exit access stairway or ramp serve the same floor level and terminate at the same level of exit discharge, the termination of the exit access stairway or ramp and the exit discharge door of the interior exit stairway or ramp shall be separated by a distance of not less than 9144 mm (30 feet) or not less than one-fourth the length of the maximu', 'standard', 'GHBC-C-003041', 'GHBC-REQ-010597', 560, '982556d028e1f4f7eb7ba470f5ff55aa246a6f5beaf09b3c234109747dc13c1a', 'extracted', 1);
