INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-921208819549f7ba', NULL, NULL, 'threshold', 11, 'GS 1207:2018 Part 11 (Clause 11.29.13.1.1): “…of travel along the aisle accessway shall not exceed ______ from any seat to the point where a person has a choice of two or more paths of escape travel to separate exits.…” — what value is stated?', '["4572 mm","16000 mm","7620 mm","9144 mm"]', 3, 'Clause 11.29.13.1.1 (GHBC-C-003086, page 568): The length of travel along the aisle accessway shall not exceed 9144 mm (30 feet) from any seat to the point where a person has a choice of two or more paths of escape travel to separate exits.', 'study', 'GHBC-C-003086', 'GHBC-REQ-010805', 568, '8e11e786362caf27675975a59b68b6853f023989725d84774136d5e8e5146d90', 'requires_review', 0);
