INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-be82bb29ed0537b0', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.3.3.1): “…Enclosed rooms or spaces that are over ______ in area and that are used primarily as a print or copy facility containing five or more printers, copy machines, scanners, facsimile machines or similar machines in any……” — what value is stated?', '["4.65 m2","14 m2","18.6 m2","9.3 m2"]', 3, 'Clause 13.3.3.1 (GHBC-C-003131, page 576): Enclosed rooms or spaces that are over 9.3 m2 (100 square feet) in area and that are used primarily as a print or copy facility containing five or more printers, copy machines, scanners, facsimile machines or similar machines in any combination, and rooms used primarily as janitorial rooms or closets where the use or storage of chemicals occurs, shall comply with all of the following:', 'standard', 'GHBC-C-003131', 'GHBC-REQ-010986', 576, '866221958bbf52e21acae260593fbd06bab08cbaf1bb72d23df4f318034a16fe', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bfb7a850e882eb47', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.3.4): “…across clean MERV 11 filters shall be not greater than ______. w.c. at 500 fpm (412 Pa at ______/s) filter face velocity.…” — what value is stated?', '["0.625 in","1 in","0.45 in","0.229 in"]', 2, 'Clause 13.3.4 (GHBC-C-003132, page 577): The pressure drop across clean MERV 11 filters shall be not greater than 0.45 in. w.c. at 500 fpm (412 Pa at 2.54 m/s) filter face velocity.', 'standard', 'GHBC-C-003132', 'GHBC-REQ-010997', 577, 'f657abdda229590c703ce64c5b1d542c5ffaff7eba31007ccbf4cb4ab8003b98', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a632ecd767dba6a4', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.3.4): “…across clean MERV 11 filters shall be not greater than ______. w.c. at 500 fpm (412 Pa at ______/s) filter face velocity.…” — what value is stated?', '["2.54 m","1.3 m","3.79 m","5.1 m"]', 0, 'Clause 13.3.4 (GHBC-C-003132, page 577): The pressure drop across clean MERV 11 filters shall be not greater than 0.45 in. w.c. at 500 fpm (412 Pa at 2.54 m/s) filter face velocity.', 'standard', 'GHBC-C-003132', 'GHBC-REQ-010997', 577, 'f657abdda229590c703ce64c5b1d542c5ffaff7eba31007ccbf4cb4ab8003b98', 'extracted', 1);
