INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fdc1bfbdd0a9ff09', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.4.1.3): “…units at their maximum outdoor air rate for at least ______ while maintaining an internal temperature of at least 60°F (15.6°C), and relative humidity not higher than 60 percent.…” — what value is stated?', '["7 days","28 days","30 days","14 days"]', 3, 'Clause 13.4.1.3 (GHBC-C-003136, page 577): Where the building indoor environment does not meet the concentration limits in Table 13.4.2 and the tenant does not address the air quality issue by mitigation and retesting, the building shall be flushed out by supplying continuous ventilation with all airhandling units at their maximum outdoor air rate for at least 14 days while maintaining an internal temperature of at least 60°F (15.6°C), and', 'standard', 'GHBC-C-003136', 'GHBC-REQ-011016', 577, '2e678ac8dfa57439c5290bad97e85d346b7c32471c86d9fd63abc9bfb8a35c33', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-db8e9af724e10109', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.4.1.3): “…Occupancy shall be permitted to start ______ after start of the flush out, provided that the flush out continues for the full ______.…” — what value is stated?', '["7 days","2 days","10 days","14 days"]', 0, 'Clause 13.4.1.3 (GHBC-C-003136, page 577): Occupancy shall be permitted to start 7 days after start of the flush out, provided that the flush out continues for the full 14 days.', 'standard', 'GHBC-C-003136', 'GHBC-REQ-011017', 577, '0691e6d040c638ffd31dd4ce2a3b4e92d72cd4845fb2243b87467f12161b6ba6', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-db8e9af724e10109', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.4.1.3): “…Occupancy shall be permitted to start ______ after start of the flush out, provided that the flush out continues for the full ______.…” — what value is stated?', '["14 days","7 days","28 days","30 days"]', 0, 'Clause 13.4.1.3 (GHBC-C-003136, page 577): Occupancy shall be permitted to start 7 days after start of the flush out, provided that the flush out continues for the full 14 days.', 'standard', 'GHBC-C-003136', 'GHBC-REQ-011017', 577, '0691e6d040c638ffd31dd4ce2a3b4e92d72cd4845fb2243b87467f12161b6ba6', 'extracted', 1);
