INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-06b56168e78130b0', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.4.1): “…2 less than ______ for each ______ of crawl space area.…” — what value is stated?', '["100 m","50 m","150 m","200 m"]', 0, 'Clause 13.9.4.1 (GHBC-C-003169, page 590): 2 less than 0.67 m2 for each 100 m (1 square foot for each 150 square feet) of crawl space area.', 'study', 'GHBC-C-003169', 'GHBC-REQ-011329', 590, '62a7de9de5bf201c0fe4b42918cf035e338004b98e549d36e93360be212042a4', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2a6390a59825c01f', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.4.1.2): “…with a Class I vapour retarder shall be not less than 2 ______ for each ______ of crawl space area.…” — what value is stated?', '["1 m2","1.4 m2","0.67 m2","0.305 m2"]', 2, 'Clause 13.9.4.1.2 (GHBC-C-003170, page 591): The net area of ventilation openings for crawl spaces with the ground surface covered with a Class I vapour retarder shall be not less than 2 0.67 m2 for each 1000 m (1 square foot for each 1,500 square feet) of crawl space area.', 'standard', 'GHBC-C-003170', 'GHBC-REQ-011331', 591, '1665b328eda662f7473a790e62fe28b8cf1afdf3e4393a91d011e9711a5e8b41', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-08b98d8642e5f046', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.4.1.2): “…with a Class I vapour retarder shall be not less than 2 ______ for each ______ of crawl space area.…” — what value is stated?', '["2018 m","1000 m","500 m","1629 m"]', 1, 'Clause 13.9.4.1.2 (GHBC-C-003170, page 591): The net area of ventilation openings for crawl spaces with the ground surface covered with a Class I vapour retarder shall be not less than 2 0.67 m2 for each 1000 m (1 square foot for each 1,500 square feet) of crawl space area.', 'standard', 'GHBC-C-003170', 'GHBC-REQ-011331', 591, '1665b328eda662f7473a790e62fe28b8cf1afdf3e4393a91d011e9711a5e8b41', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b2fa5c7da8c4cbaf', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.4.3): “…at a rate of 1.0 cubic foot per minute (cfm) for each ______ of crawl space ground surface area and the ground surface shall be covered with a Class I vapour retarder.…” — what value is stated?', '["15 m2","20 m2","10 m2","5 m2"]', 2, 'Clause 13.9.4.3 (GHBC-C-003172, page 591): Continuously operated mechanical ventilation shall be provided at a rate of 1.0 cubic foot per minute (cfm) for each 50 square feet (1.02 L/s for each 10 m2 ) of crawl space ground surface area and the ground surface shall be covered with a Class I vapour retarder.', 'standard', 'GHBC-C-003172', 'GHBC-REQ-011336', 591, 'fbe7b9c3c9c7774889735a8f96e8538fc371fac4ac0c1912fd73ce47329cf72e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-66c04696cf33be71', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.5.1.1): “…area of the interior room or space, but not less than ______.…” — what value is stated?', '["3.3 m2","4.6 m2","2.3 m2","1.1 m2"]', 2, 'Clause 13.9.5.1.1 (GHBC-C-003177, page 591): Where rooms and spaces without openings to the outdoors are ventilated through an adjoining room, the opening to the adjoining room shall be unobstructed and shall have an area of not less than 8 percent of the floor area of the interior room or space, but not less than 2.3 m2 (25 square feet).', 'standard', 'GHBC-C-003177', 'GHBC-REQ-011342', 591, '5daf5c2c11cdde0c3bbb053831a6f935dd36ad3d2a66fd02ac735ad315bd8248', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2e1db3b0d52e3b4', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.9.5.1.1): “…area of the interior room or space, but not less than ______. The openable area of the openings to the outdoors shall be based on the total floor area being ventilated.…” — what value is stated?', '["0.93 m2","2.79 m2","3.72 m2","1.86 m2"]', 3, 'Clause 13.9.5.1.1 (GHBC-C-003177, page 591): EXCEPTIONS: Exterior openings required for ventilation shall be allowed to open into a sunroom with thermal isolation or a patio cover provided that the openable area between the sunroom addition or patio cover and the interior room shall have an area of not less than 8 percent of the floor area of the interior room or space, but not less than 1.86 m2 (20 square feet). The openable area of the ope', 'standard', 'GHBC-C-003177', 'GHBC-REQ-011344', 591, '54e46a62624a81b3c5adda8f4ed7aee5c89e30921b491a0a7321ba0963c6228c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cd3b3e355d058d37', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.10.1): “…indoor temperature of not less than 68°F (20°C) at a point ______ above the floor on the design heating day.…” — what value is stated?', '["457 mm","1372 mm","1829 mm","914 mm"]', 3, 'Clause 13.10.1 (GHBC-C-003182, page 592): Interior spaces intended for human occupancy shall be provided with active or passive space heating systems capable of maintaining an indoor temperature of not less than 68°F (20°C) at a point 914 mm (3 feet) above the floor on the design heating day.', 'standard', 'GHBC-C-003182', 'GHBC-REQ-011353', 592, '4521172adb8cc16e9ae5dc40670d9bdf46eadb5f1afe69cc0d8bdf75643406b0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ac41afac25d48d54', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.10.1): “…indoor temperature of not less than 68°F (20°C) at a point ______ above the floor on the design heating day.…” — what value is stated?', '["5 feet","6 feet","3 feet","2 feet"]', 2, 'Clause 13.10.1 (GHBC-C-003182, page 592): Interior spaces intended for human occupancy shall be provided with active or passive space heating systems capable of maintaining an indoor temperature of not less than 68°F (20°C) at a point 914 mm (3 feet) above the floor on the design heating day.', 'standard', 'GHBC-C-003182', 'GHBC-REQ-011353', 592, '4521172adb8cc16e9ae5dc40670d9bdf46eadb5f1afe69cc0d8bdf75643406b0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6fbc27ff801a8828', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.11.2.1): “…than one-tenth of the floor area of the interior room or ______…” — what value is stated?', '["3.3 m2","4.65 m2","2.32 m2","1.1 m2"]', 2, 'Clause 13.11.2.1 (GHBC-C-003185, page 592): For the purpose of natural lighting, any room is permitted to be considered as a portion of an adjoining room where one-half of the area of the common wall is open and unobstructed and provides an opening of not less than one-tenth of the floor area of the interior room or 2.32 m2', 'standard', 'GHBC-C-003185', 'GHBC-REQ-011362', 592, 'bcc1fb3b8fb5a49d7f451ff7dd746e910b83a31693c3e228bbfb2efc21e249ed', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f9e3beaa6229ee98', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.11.2.1): “…than one-tenth of the floor area of the interior room or ______, whichever is greater.…” — what value is stated?', '["1.86 m2","0.93 m2","2.79 m2","3.72 m2"]', 0, 'Clause 13.11.2.1 (GHBC-C-003185, page 592): EXCEPTIONS: Openings required for natural light shall be permitted to open into a sunroom with thermal isolation or a patio cover where the common wall provides a glazed area of not less than one-tenth of the floor area of the interior room or 1.86 m2 (20 square feet), whichever is greater.', 'standard', 'GHBC-C-003185', 'GHBC-REQ-011364', 592, 'cd79e7783921bce4f6db8a25951181476a314d80a1988649dc67b34aa3c6cc8e', 'extracted', 1);
