INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3f56d995d3457ba8', NULL, NULL, 'threshold', 13, 'GS 1207:2018 Part 13 (Clause 13.11.2.2): “…Has a ceiling height of not less than ______.…” — what value is stated?', '["14 feet","7 feet","3.5 feet","10 feet"]', 1, 'Clause 13.11.2.2 (GHBC-C-003186, page 592): Has a ceiling height of not less than 2134 mm (7 feet).', 'study', 'GHBC-C-003186', 'GHBC-REQ-011372', 592, '9e7f232a877f1f4ff0f412c3679b25f52161dd597a22e17d90b84a906243fd2e', 'requires_review', 0);
