INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1418214e75f7a9bb', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.3): “…or het recovery system is capable of providing at least ______ of the average daily hot water demand.…” — what value is stated?', '["70 %","30 %","95 %","90 %"]', 0, 'Clause 14.4.3 (GHBC-C-003224, page 598): (b)  Storage should be sized such that the solar or het recovery system is capable of providing at least 70% of the average daily hot water demand.', 'standard', 'GHBC-C-003224', 'GHBC-REQ-011511', 598, 'ee7f856e467611eed28e2e65e433971d05bf3ee2e84955fc64875bc5453df037', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3b3a6fc5da0927ce', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.4): “…type provided by several manufacturers – having at least ______ of high density fiberglass or equivalent insulation which allows reduced standby losses.…” — what value is stated?', '["100 mm","127 mm","65 mm","32 mm"]', 2, 'Clause 14.4.4 (GHBC-C-003225, page 598): Newly purchased tanks should be of the ―Energy Saver‖ or ―energy conserving‖ type provided by several manufacturers – having at least 65 mm of high density fiberglass or equivalent insulation which allows reduced standby losses.', 'standard', 'GHBC-C-003225', 'GHBC-REQ-011516', 598, '2d4d820480cec1e0aace582ef8e213bace58d6ab5f13a3e4fb650eb86f5e1171', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a661321c43b21d1e', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.4): “…with an insulating shroud of the equivalent of at least ______ of blanket-type…” — what value is stated?', '["65 mm","32 mm","100 mm","127 mm"]', 0, 'Clause 14.4.4 (GHBC-C-003225, page 598): Alternatively, standard type storage heaters should be provided with an insulating shroud of the equivalent of at least 65mm of blanket-type', 'standard', 'GHBC-C-003225', 'GHBC-REQ-011517', 598, '47e293ebe90c5dc8cbb8fdc0c9ce8ae9e46c7673da7a67a8b933a9e48afd5df0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4cc6ad7a4ca4ebcd', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.4): “…overall shell thermal resistance (―R value‖) of at least ______ k/W.…” — what value is stated?', '["0.84 m2","2.5 m2","3.7 m2","1.76 m2"]', 3, 'Clause 14.4.4 (GHBC-C-003225, page 598): Storage tanks greater than 450 litres should have an overall shell thermal resistance (―R value‖) of at least 1.76m2 k/W.', 'standard', 'GHBC-C-003225', 'GHBC-REQ-011520', 598, 'd08d172856c3e914dc4aaf91bf17a231d986d2fdbb1866f4b7fff980ac33ae41', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-718599977277fb42', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.6): “…6 hours/day, year round, shall be insulated with at least ______ fiberglass insulation or equivalent.…” — what value is stated?', '["10 mm","30 mm","40 mm","20 mm"]', 3, 'Clause 14.4.6 (GHBC-C-003227, page 599): (d) All circulating hot water piping or non-circulating systems with a demand profile which requires that water be maintained at elevated temperature more than an average 6 hours/day, year round, shall be insulated with at least 20 mm fiberglass insulation or equivalent.', 'standard', 'GHBC-C-003227', 'GHBC-REQ-011529', 599, '2fd388dc3e531d428a93c5ece097ab5a5bb0d6719f1e055bf394582938cc9e33', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-39398ea8ffe3e2b4', NULL, NULL, 'threshold', 14, 'GS 1207:2018 Part 14 (Clause 14.4.6): “…shall have a rated combustion efficiency of at least ______.…” — what value is stated?', '["80 %","40 %","95 %","90 %"]', 0, 'Clause 14.4.6 (GHBC-C-003227, page 599): (f) Combustion efficiency: Combustion devices installed to produce hot water for any purpose shall have a rated combustion efficiency of at least 80%.', 'standard', 'GHBC-C-003227', 'GHBC-REQ-011532', 599, '81e4a5a384e8c52139e96a51275b67ac9a384333ed0b02ccc5d3f6ccffee7ed7', 'extracted', 1);
