INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b88adbbfb87ec85e', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.2.4): “…of Type I, II, III construction that are greater than ______ in height above grade plane and contain a combustible water-resistive barrier shall be tested in accordance with and comply with the acceptance criteria of……” — what value is stated?', '["60 feet","75 feet","40 feet","20 feet"]', 2, 'Clause 15.2.4 (GHBC-C-003233, page 600): Exterior walls on buildings of Type I, II, III construction that are greater than 40 feet (12 192 mm) in height above grade plane and contain a combustible water-resistive barrier shall be tested in accordance with and comply with the acceptance criteria of the Ghana Fire Code.', 'standard', 'GHBC-C-003233', 'GHBC-REQ-011565', 600, 'd2e280c8d9335e2711258b7795691e5e4a9c6d3004851b93b261a75ba63fbef7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9eb2cb7d665f8647', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.2.4): “…of Type I, II, III construction that are greater than ______ in height above grade plane and contain a combustible water-resistive barrier shall be tested in accordance with and comply with the acceptance criteria of……” — what value is stated?', '["192 mm","100 mm","288 mm","381 mm"]', 0, 'Clause 15.2.4 (GHBC-C-003233, page 600): Exterior walls on buildings of Type I, II, III construction that are greater than 40 feet (12 192 mm) in height above grade plane and contain a combustible water-resistive barrier shall be tested in accordance with and comply with the acceptance criteria of the Ghana Fire Code.', 'standard', 'GHBC-C-003233', 'GHBC-REQ-011565', 600, 'd2e280c8d9335e2711258b7795691e5e4a9c6d3004851b93b261a75ba63fbef7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-90af5a83022cb7a2', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.2.4): “…of less than 150 kW/m2 , a total heat release of less than ______J/m2…” — what value is stated?', '["40 m","20 m","10 m","30 m"]', 1, 'Clause 15.2.4 (GHBC-C-003233, page 600): Walls in which the water-resistive barrier is the only combustible component and the water-resistive barrier has a peak heat release rate of less than 150 kW/m2 , a total heat release of less than 20 MJ/m2', 'standard', 'GHBC-C-003233', 'GHBC-REQ-011571', 600, 'f36ad9982f4c06f33ab571273d95aae9f2f7c91a88e0521622319509b481cbd8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-89e6bf7452b183a7', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.2.4): “…and an effective heat of combustion of less than ______J/kg as determined in accordance with ASTM E1354 and has a flame spread index of 25 or less and a smoke-developed index of 450 or less as determined in accordance……” — what value is stated?', '["28 m","35 m","18 m","9 m"]', 2, 'Clause 15.2.4 (GHBC-C-003233, page 600): and an effective heat of combustion of less than 18 MJ/kg as determined in accordance with ASTM E1354 and has a flame spread index of 25 or less and a smoke-developed index of 450 or less as determined in accordance with ASTM E84.', 'standard', 'GHBC-C-003233', 'GHBC-REQ-011572', 600, 'a22a26431b1eb10675a705858747da343186ea5edcd592e79b1ccffc65bc4f01', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-863094207c7a4ba1', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.3.2): “…studs or sheathing, with flashing as described in Clause ______ such a manner as to provide a continuous water-resistive barrier behind the exterior wall veneer.…” — what value is stated?', '["2 in","6 in","8 in","4 in"]', 3, 'Clause 15.3.2 (GHBC-C-003237, page 601): Not fewer than one layer of No.15 asphalt felt, complying with ASTM D226 for Type 1 felt or other approved materials, shall be attached to the studs or sheathing, with flashing as described in Clause 15.4.4, in such a manner as to provide a continuous water-resistive barrier behind the exterior wall veneer.', 'standard', 'GHBC-C-003237', 'GHBC-REQ-011579', 601, '19d281486c239df8b1783b0e9146ef3c520adf7cef280cd6073173047232c7cc', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-218782cb47edfa2f', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.3.12.2): “…siding and the adjacent building shall be not less than ______.…” — what value is stated?', '["5 feet","15 feet","20 feet","10 feet"]', 3, 'Clause 15.3.12.2 (GHBC-C-003254, page 602): The fire separation distance between a building with polypropylene siding and the adjacent building shall be not less than 10 feet (3048 mm).', 'study', 'GHBC-C-003254', 'GHBC-REQ-011603', 602, '8623bdf22e170157b03f365664e42e0d4086e262747b3e0f608d608a510bcc1a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6fe1b591284eac49', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.3.12.2): “…siding and the adjacent building shall be not less than ______.…” — what value is stated?', '["4572 mm","6096 mm","3048 mm","1524 mm"]', 2, 'Clause 15.3.12.2 (GHBC-C-003254, page 602): The fire separation distance between a building with polypropylene siding and the adjacent building shall be not less than 10 feet (3048 mm).', 'study', 'GHBC-C-003254', 'GHBC-REQ-011603', 602, '8623bdf22e170157b03f365664e42e0d4086e262747b3e0f608d608a510bcc1a', 'requires_review', 0);
