INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f56b48ab6f7585b9', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.7): “…Anchored stone veneer units not exceeding ______ in thickness shall be anchored…” — what value is stated?', '["381 mm","508 mm","254 mm","127 mm"]', 2, 'Clause 15.4.7 (GHBC-C-003269, page 605): Anchored stone veneer units not exceeding 10 inches (254 mm) in thickness shall be anchored', 'standard', 'GHBC-C-003269', 'GHBC-REQ-011653', 605, '9a87f2247bad63b63ca632fddd17d6117d04cad8b1e1ff81684370c355cc2147', 'extracted', 1);
