INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c11ceb0ccfee2c5f', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.7): “…The legs of the loops shall be not less than ______ in length bent at right angles and laid in the mortar joint, and spaced so that the eyes or loops are ______ maximum on center in both directions.…” — what value is stated?', '["12 in","6 in","3 in","9 in"]', 1, 'Clause 15.4.7 (GHBC-C-003269, page 605): The legs of the loops shall be not less than 6 inches (152 mm) in length bent at right angles and laid in the mortar joint, and spaced so that the eyes or loops are 12 inches (305 mm) maximum on center in both directions.', 'standard', 'GHBC-C-003269', 'GHBC-REQ-011657', 605, 'b2ba0b00fa0fbe2b99b04be4d2ae05dc494e1980cb713f0eeca14d9d6efaaeb9', 'extracted', 1);
