INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f0c3cd970aaf5b7d', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.11.1): “…The spacing of the fastenings or ties shall not exceed ______ either vertically or horizontally, but where units exceed ______ in area there shall be not less than four attachments per unit.…” — what value is stated?', '["0.4 m2","0.2 m2","0.6 m2","0.77 m2"]', 0, 'Clause 15.4.11.1 (GHBC-C-003288, page 608): The spacing of the fastenings or ties shall not exceed 24 inches (610 mm) either vertically or horizontally, but where units exceed 4 square feet (0.4 m2 ) in area there shall be not less than four attachments per unit.', 'study', 'GHBC-C-003288', 'GHBC-REQ-011720', 608, '7af55def69686ba152f7d7769daf270d2fb20bdd9413f125253b837d4b4238ce', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9e7020e6b6c80c98', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12): “…of thin exterior structural glass veneer shall not exceed ______ where that clause is not more than ______ above the level of the sidewalk or grade level directly below, and shall not exceed ______ where it is more than……” — what value is stated?', '["1.86 m2","0.93 m2","0.46 m2","1.4 m2"]', 1, 'Clause 15.4.12 (GHBC-C-003292, page 608): The area of a single clause of thin exterior structural glass veneer shall not exceed 10 square feet (0.93 m2 ) where that clause is not more than 15 feet (4572 mm) above the level of the sidewalk or grade level directly below, and shall not exceed 6 square feet (0.56 m2 ) where it is more than 15 feet (4572 mm) above that level.', 'study', 'GHBC-C-003292', 'GHBC-REQ-011728', 608, 'ddd2a7be49803616c045a0c2ae9fbec0089cef0cbc20b4b37a0b3d743269d817', 'requires_review', 0);
