INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a7f4b2327c77e0b0', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4): “…approved metal molding, and be set not less than1 / inch (______) above the highest point of the sidewalk.4 The space between the molding and the sidewalk shall be thoroughly caulked and made water tight.…” — what value is stated?', '["9.53 mm","12.732 mm","6.4 mm","3.2 mm"]', 2, 'Clause 15.4.12.4 (GHBC-C-003296, page 609): Where glass extends to a sidewalk surface, each clause shall rest in an approved metal molding, and be set not less than1 / inch (6.4 mm) above the highest point of the sidewalk.4 The space between the molding and the sidewalk shall be thoroughly caulked and made water tight.', 'standard', 'GHBC-C-003296', 'GHBC-REQ-011736', 609, '34c84cc957e24c84b231dea9ecb15659034aa347179c6be698f0fd85042d72cf', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f942b2d71b0aaaf5', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4.1): “…of the top of a bulkhead facing, or at a level more than ______ above the sidewalk level, the mastic cement binding shall be supplemented with approved nonferrous metal shelf angles located in the horizontal joints in……” — what value is stated?', '["54 in","72 in","36 in","18 in"]', 2, 'Clause 15.4.12.4.1 (GHBC-C-003297, page 609): Where thin exterior structural glass veneer is installed above the level of the top of a bulkhead facing, or at a level more than 36 inches (914 mm) above the sidewalk level, the mastic cement binding shall be supplemented with approved nonferrous metal shelf angles located in the horizontal joints in every course.', 'standard', 'GHBC-C-003297', 'GHBC-REQ-011737', 609, 'd28128d14d2e039e0f5ac0d28bccc1f012ad371bcf9bbbac3a10e117b7aac187', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8c0e10ac9a66aaab', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4.1): “…of the top of a bulkhead facing, or at a level more than ______ above the sidewalk level, the mastic cement binding shall be supplemented with approved nonferrous metal shelf angles located in the horizontal joints in……” — what value is stated?', '["457 mm","1372 mm","1829 mm","914 mm"]', 3, 'Clause 15.4.12.4.1 (GHBC-C-003297, page 609): Where thin exterior structural glass veneer is installed above the level of the top of a bulkhead facing, or at a level more than 36 inches (914 mm) above the sidewalk level, the mastic cement binding shall be supplemented with approved nonferrous metal shelf angles located in the horizontal joints in every course.', 'standard', 'GHBC-C-003297', 'GHBC-REQ-011737', 609, 'd28128d14d2e039e0f5ac0d28bccc1f012ad371bcf9bbbac3a10e117b7aac187', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5fd87b12217dda52', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4.1): “…Such shelf angles shall be not less than 0.0478-inch (______) thick and not less than ______ long and shall be spaced at approved intervals, with not less than two angles for each glass unit.…” — what value is stated?', '["2.31 mm","1.2 mm","0.64 mm","1.8 mm"]', 1, 'Clause 15.4.12.4.1 (GHBC-C-003297, page 609): Such shelf angles shall be not less than 0.0478-inch (1.2 mm) thick and not less than 2 inches (51 mm) long and shall be spaced at approved intervals, with not less than two angles for each glass unit.', 'standard', 'GHBC-C-003297', 'GHBC-REQ-011738', 609, '2798facafeec6c040b0376efb7009b3d55a878c6ef06d4f7dea8cc5025eeaac0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1de7b8c59602d5f9', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4.1): “…Such shelf angles shall be not less than 0.0478-inch (______) thick and not less than ______ long and shall be spaced at approved intervals, with not less than two angles for each glass unit.…” — what value is stated?', '["2 in","1 in","3 in","4 in"]', 0, 'Clause 15.4.12.4.1 (GHBC-C-003297, page 609): Such shelf angles shall be not less than 0.0478-inch (1.2 mm) thick and not less than 2 inches (51 mm) long and shall be spaced at approved intervals, with not less than two angles for each glass unit.', 'standard', 'GHBC-C-003297', 'GHBC-REQ-011738', 609, '2798facafeec6c040b0376efb7009b3d55a878c6ef06d4f7dea8cc5025eeaac0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5fd87b12217dda52', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.4.1): “…Such shelf angles shall be not less than 0.0478-inch (______) thick and not less than ______ long and shall be spaced at approved intervals, with not less than two angles for each glass unit.…” — what value is stated?', '["102 mm","51 mm","25.4 mm","76 mm"]', 1, 'Clause 15.4.12.4.1 (GHBC-C-003297, page 609): Such shelf angles shall be not less than 0.0478-inch (1.2 mm) thick and not less than 2 inches (51 mm) long and shall be spaced at approved intervals, with not less than two angles for each glass unit.', 'standard', 'GHBC-C-003297', 'GHBC-REQ-011738', 609, '2798facafeec6c040b0376efb7009b3d55a878c6ef06d4f7dea8cc5025eeaac0', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-976016ee5d4a2923', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.5): “…and horizontal joints shall be held to not less than ______ by an approved nonrigid substance or device.…” — what value is stated?', '["0.063 in","0.032 in","0.091 in","0.128 in"]', 0, 'Clause 15.4.12.5 (GHBC-C-003298, page 609): Joints shall be uniformly buttered with an approved jointing compound and horizontal joints shall be held to not less than 0.063 inch (1.6 mm) by an approved nonrigid substance or device.', 'standard', 'GHBC-C-003298', 'GHBC-REQ-011742', 609, 'd9b64142a5814694ec68497a28cd65f8db541e252d979ca36f067646dcfa4f8f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-60a20c792836d277', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.5): “…and horizontal joints shall be held to not less than ______ by an approved nonrigid substance or device.…” — what value is stated?', '["0.8 mm","2.31 mm","3.2 mm","1.6 mm"]', 3, 'Clause 15.4.12.5 (GHBC-C-003298, page 609): Joints shall be uniformly buttered with an approved jointing compound and horizontal joints shall be held to not less than 0.063 inch (1.6 mm) by an approved nonrigid substance or device.', 'standard', 'GHBC-C-003298', 'GHBC-REQ-011742', 609, 'd9b64142a5814694ec68497a28cd65f8db541e252d979ca36f067646dcfa4f8f', 'extracted', 1);
