INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e270acd6d646696c', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.12.6): “…the heads of show windows and finish installed more than ______ above sidewalk level shall______ addition to the mastic cement and shelf angles, be held in place by the use of fastenings at each vertical or horizontal……” — what value is stated?', '["12 feet","6 feet","18 feet","24 feet"]', 0, 'Clause 15.4.12.6 (GHBC-C-003299, page 609): Thin exterior structural glass veneer installed above the level of the heads of show windows and finish installed more than 12 feet (3658 mm) above sidewalk level shall, in addition to the mastic cement and shelf angles, be held in place by the use of fastenings at each vertical or horizontal edge, or at the four corners of each glass unit.', 'standard', 'GHBC-C-003299', 'GHBC-REQ-011744', 609, '89699b1a7593ab8c77abd4fde03c92a4bc784eb87def7b33933aec8ef12409ed', 'extracted', 1);
