INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ac1c9af9150ca437', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.16.2): “…Lap siding shall be lapped not less than 11 / inches (______) and lap siding not having tongue-and-groove end joints4 shall have the ends protected with caulking, covered with an H-clause joint cover, located over a……” — what value is stated?', '["32 mm","16 mm","50 mm","64 mm"]', 0, 'Clause 15.4.16.2 (GHBC-C-003308, page 610): Lap siding shall be lapped not less than 11 / inches (32 mm) and lap siding not having tongue-and-groove end joints4 shall have the ends protected with caulking, covered with an H-clause joint cover, located over a strip of flashing or shall be otherwise designed to comply with Clause 15.2.2.', 'standard', 'GHBC-C-003308', 'GHBC-REQ-011780', 610, '08713222763508cd470503e3b682d3b694408ede55423ec51009da6b24dd1c9a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7831e92a4ccc0ac1', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.4.17): “…except where sheathing is of wood not less than 1-inch (______) nominal thickness or of wood structural panels as specified in Table 24.8.6.3(3).…” — what value is stated?', '["50 mm","25 mm","12.5 mm","38 mm"]', 1, 'Clause 15.4.17 (GHBC-C-003309, page 611): Shingles and other weather coverings shall be attached with appropriate standard-shingle nails to furring strips securely nailed to studs, or with approved mechanically bonding nails, except where sheathing is of wood not less than 1-inch (25 mm) nominal thickness or of wood structural panels as specified in Table 24.8.6.3(3).', 'standard', 'GHBC-C-003309', 'GHBC-REQ-011783', 611, 'ffb83c230ae05088dbb87cb0de92ce2654f784d2fcfbe3b1e6cd3db9777e7a88', 'extracted', 1);
