INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d58a5cf512ee7253', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.5.1.1.1.1): “…on exterior walls having a fire separation distance of ______ or less, combustible exterior wall coverings shall not exhibit sustained flaming as defined in this Code.…” — what value is stated?', '["2286 mm","3048 mm","1524 mm","762 mm"]', 2, 'Clause 15.5.1.1.1.1 (GHBC-C-003314, page 611): Where installed on exterior walls having a fire separation distance of 5 feet (1524 mm) or less, combustible exterior wall coverings shall not exhibit sustained flaming as defined in this Code.', 'study', 'GHBC-C-003314', 'GHBC-REQ-011807', 611, 'bf4dbce615c9fb74ae1d8cdfd14d90cfa7fe5b9c567da2a9afc5da394bd139c9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-040cb6e735e5c19a', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.5.1.1.1.2): “…For fire separation distances greater than ______, any exterior wall covering shall be permitted that has been exposed to a reduced level of incident radiant heat flux in accordance with the this Code test method……” — what value is stated?', '["5 feet","3 feet","8 feet","10 feet"]', 0, 'Clause 15.5.1.1.1.2 (GHBC-C-003315, page 611): For fire separation distances greater than 5 feet (1524 mm), any exterior wall covering shall be permitted that has been exposed to a reduced level of incident radiant heat flux in accordance with the this Code test method without exhibiting sustained flaming.', 'standard', 'GHBC-C-003315', 'GHBC-REQ-011809', 611, '1eb95a3bfba04ba93bb21730ce80e2e171ed6acba271cc414ea43461dd25f98b', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c5b5841941026e46', NULL, NULL, 'threshold', 15, 'GS 1207:2018 Part 15 (Clause 15.5.1.1.1.2): “…For fire separation distances greater than ______, any exterior wall covering shall be permitted that has been exposed to a reduced level of incident radiant heat flux in accordance with the this Code test method……” — what value is stated?', '["1524 mm","762 mm","2286 mm","3048 mm"]', 0, 'Clause 15.5.1.1.1.2 (GHBC-C-003315, page 611): For fire separation distances greater than 5 feet (1524 mm), any exterior wall covering shall be permitted that has been exposed to a reduced level of incident radiant heat flux in accordance with the this Code test method without exhibiting sustained flaming.', 'standard', 'GHBC-C-003315', 'GHBC-REQ-011809', 611, '1eb95a3bfba04ba93bb21730ce80e2e171ed6acba271cc414ea43461dd25f98b', 'extracted', 1);
