INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e8f3af46fddc6399', NULL, NULL, 'threshold', 16, 'GS 1207:2018 Part 16 (Clause 16.10.6.3): “…Where the fire separation distance is not less than ______, the mechanical equipment screen shall be constructed of materials having a flame spread index of 25 or less when tested in the minimum and maximum thicknesses……” — what value is stated?', '["6096 mm","3048 mm","9144 mm","10000 mm"]', 0, 'Clause 16.10.6.3 (GHBC-C-003542, page 643): Where the fire separation distance is not less than 6096 mm (20 feet), the mechanical equipment screen shall be constructed of materials having a flame spread index of 25 or less when tested in the minimum and maximum thicknesses intended for use with each face tested independently in accordance with ASTM E84.', 'standard', 'GHBC-C-003542', 'GHBC-REQ-012425', 643, 'c5a1dac62ad27502e6a12b6ad93c97dd27a75305282cc09965431cf4ab0e1690', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3f86b27c5f40c568', NULL, NULL, 'threshold', 16, 'GS 1207:2018 Part 16 (Clause 16.10.6.3): “…Where the fire separation distance is not less than ______, the mechanical equipment screen shall be constructed of materials having a flame spread index of 25 or less when tested in the minimum and maximum thicknesses……” — what value is stated?', '["20 feet","10 feet","30 feet","40 feet"]', 0, 'Clause 16.10.6.3 (GHBC-C-003542, page 643): Where the fire separation distance is not less than 6096 mm (20 feet), the mechanical equipment screen shall be constructed of materials having a flame spread index of 25 or less when tested in the minimum and maximum thicknesses intended for use with each face tested independently in accordance with ASTM E84.', 'standard', 'GHBC-C-003542', 'GHBC-REQ-012425', 643, 'c5a1dac62ad27502e6a12b6ad93c97dd27a75305282cc09965431cf4ab0e1690', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9c3af9d05541928e', NULL, NULL, 'threshold', 16, 'GS 1207:2018 Part 16 (Clause 16.10.8.1): “…EXCEPTIONS: Aerial supports not greater than ______ in height as measured from the roof deck to the highest point on the aerial supports shall be permitted to be constructed of combustible materials.…” — what value is stated?', '["1829 mm","5486 mm","7315 mm","3658 mm"]', 3, 'Clause 16.10.8.1 (GHBC-C-003547, page 644): EXCEPTIONS: Aerial supports not greater than 3658 mm (12 feet) in height as measured from the roof deck to the highest point on the aerial supports shall be permitted to be constructed of combustible materials.', 'standard', 'GHBC-C-003547', 'GHBC-REQ-012431', 644, 'f50f33f199d2b0dde1d0d1cea1c9cf50a21d6eec933ecf603a74032ca98e30bb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7edd55fe52620a81', NULL, NULL, 'threshold', 16, 'GS 1207:2018 Part 16 (Clause 16.10.8.1): “…EXCEPTIONS: Aerial supports not greater than ______ in height as measured from the roof deck to the highest point on the aerial supports shall be permitted to be constructed of combustible materials.…” — what value is stated?', '["24 feet","12 feet","6 feet","18 feet"]', 1, 'Clause 16.10.8.1 (GHBC-C-003547, page 644): EXCEPTIONS: Aerial supports not greater than 3658 mm (12 feet) in height as measured from the roof deck to the highest point on the aerial supports shall be permitted to be constructed of combustible materials.', 'standard', 'GHBC-C-003547', 'GHBC-REQ-012431', 644, 'f50f33f199d2b0dde1d0d1cea1c9cf50a21d6eec933ecf603a74032ca98e30bb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-326cb3a732c72aeb', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.5.2.2.1): “…(BS EN 1990: Table NA.A1.2 (B)) of ______ay be used.…” — what value is stated?', '["1 m","0.5 m","1.5 m","2 m"]', 0, 'Clause 17.5.2.2.1 (GHBC-C-003582, page 652): (BS EN 1990: Table NA.A1.2 (B)) of 1.0 may be used.', 'standard', 'GHBC-C-003582', 'GHBC-REQ-012562', 652, '72cd40e2beb95f2d12774e1a401f381bf2e8458790ec1fb6c4b66e701fbb5dbc', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-92cdc732e9f17600', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.7.2): “…loads applied over a specified area of a square with a ______ side shall be located so as to cause maximum effects.…” — what value is stated?', '["600 mm","300 mm","150 mm","450 mm"]', 1, 'Clause 17.7.2 (GHBC-C-003585, page 655): The concentrated loads applied over a specified area of a square with a 300mm side shall be located so as to cause maximum effects.', 'standard', 'GHBC-C-003585', 'GHBC-REQ-012570', 655, '42ca09412d1ba1998bdc03276e76814fc47328acd00af817d1d2b05b10eadd3c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c4f7d064d42642a6', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.7.2): “…(4) Beams, ribs and joists spaced at not more than ______etre centres may be designed as floor slabs.…” — what value is stated?', '["1 m","0.5 m","1.5 m","2 m"]', 0, 'Clause 17.7.2 (GHBC-C-003585, page 655): (4)   Beams, ribs and joists spaced at not more than 1 metre centres may be designed as floor slabs.', 'standard', 'GHBC-C-003585', 'GHBC-REQ-012575', 655, '7f49e3da39cded5e0a6f846b357e885ba797b3a20a04605fced6cf3b2ef0ed9f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e9c20abcc42257f4', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…a single span of a beam or girder supports not less than ______ of floor at one general level, the imposed load may______ the design of beam or girder, be reduced by ______ for each ______ supported, subject to a……” — what value is stated?', '["70 m2","92.9 m2","46 m2","23 m2"]', 2, 'Clause null (GHBC-C-003588, page 656): (2) Where a single span of a beam or girder supports not less than 46m2 of floor at one general level, the imposed load may, in the design of beam or girder, be reduced by 5% for each 46m2 supported, subject to a maximum reduction of 25%.', 'standard', 'GHBC-C-003588', 'GHBC-REQ-012584', 656, '7ec446a4692f3ee0760ed01858d2272f538b571431ea18eee60be5af712fbd2d', 'extracted', 1);
