INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e9c20abcc42257f4', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…a single span of a beam or girder supports not less than ______ of floor at one general level, the imposed load may______ the design of beam or girder, be reduced by ______ for each ______ supported, subject to a……” — what value is stated?', '["70 m2","92.9 m2","46 m2","23 m2"]', 2, 'Clause null (GHBC-C-003588, page 656): (2) Where a single span of a beam or girder supports not less than 46m2 of floor at one general level, the imposed load may, in the design of beam or girder, be reduced by 5% for each 46m2 supported, subject to a maximum reduction of 25%.', 'standard', 'GHBC-C-003588', 'GHBC-REQ-012584', 656, '7ec446a4692f3ee0760ed01858d2272f538b571431ea18eee60be5af712fbd2d', 'extracted', 1);
