INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e8177ba35719d1a7', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…and repairs) shall withstand an imposed load of 0.25kN/m______easured on plan or a load of 0.9kN concentrated on a square with ______ side whichever produces the greater stress.…” — what value is stated?', '["4 m","2 m","1 m","3 m"]', 1, 'Clause null (GHBC-C-003590, page 656): Flat roofs to which there is no direct access (except only such cases as is necessary for cleaning and repairs) shall withstand an imposed load of 0.25kN/m2 measured on plan or a load of 0.9kN concentrated on a square with 300mm side whichever produces the greater stress.', 'standard', 'GHBC-C-003590', 'GHBC-REQ-012588', 656, '36e445c41d44d163406d2ffd7b2819ea816bf26a0391e28c5aa701030e7f2e96', 'extracted', 1);
