INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-770d109bef1086ff', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…allowance shall be made for an imposed load of 1.5kN/m______easured on plan or a load of 1.8kN concentrated on a square with a ______ side.…” — what value is stated?', '["4 m","2 m","1 m","3 m"]', 1, 'Clause null (GHBC-C-003590, page 656): (2) On flat floors where access (in addition to that necessary for cleaning and repair) is provided to the roof, allowance shall be made for an imposed load of 1.5kN/m2 measured on plan or a load of 1.8kN concentrated on a square with a 300mm side.', 'standard', 'GHBC-C-003590', 'GHBC-REQ-012589', 656, '4b99e150344252fc0ab776c579830999156a18063b8f7c7fd8be56e176057030', 'extracted', 1);
