INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c95fe5978b77ff3e', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…the horizontal shall withstand an imposed load of 0.25kN/m______easured on plan or a vertical load of 0.9kN concentrated on a square with ______ side whichever produces the greater stress.…” — what value is stated?', '["4 m","2 m","1 m","3 m"]', 1, 'Clause null (GHBC-C-003599, page 659): (3) Sloping Roofs up to angle of 65o to the horizontal shall withstand an imposed load of 0.25kN/m2 measured on plan or a vertical load of 0.9kN concentrated on a square with 300mm side whichever produces the greater stress.', 'standard', 'GHBC-C-003599', 'GHBC-REQ-012624', 659, 'a42c5960ca87532fddbc13699e749eff20077095bdb3ca47619471b72682e3e8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cd6046ba79011321', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…the horizontal shall withstand an imposed load of 0.25kN/m______easured on plan or a vertical load of 0.9kN concentrated on a square with ______ side whichever produces the greater stress.…” — what value is stated?', '["450 mm","600 mm","300 mm","150 mm"]', 2, 'Clause null (GHBC-C-003599, page 659): (3) Sloping Roofs up to angle of 65o to the horizontal shall withstand an imposed load of 0.25kN/m2 measured on plan or a vertical load of 0.9kN concentrated on a square with 300mm side whichever produces the greater stress.', 'standard', 'GHBC-C-003599', 'GHBC-REQ-012624', 659, 'a42c5960ca87532fddbc13699e749eff20077095bdb3ca47619471b72682e3e8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9d47100d97bbb6ef', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…carrying a load of 0.9kN concentrated on any square with ______ side.…” — what value is stated?', '["250 mm","125 mm","63 mm","190 mm"]', 1, 'Clause null (GHBC-C-003599, page 659): (5) Roof coverings and purlins at a slope of less than 450 shall be capable of carrying a load of 0.9kN concentrated on any square with 125mm side.', 'standard', 'GHBC-C-003599', 'GHBC-REQ-012626', 659, 'f660a37798935df94bc85dec325361e816730099284291870a5fb46e5c4328e1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3a0e47d7821d208b', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.8.3): “…which shall be: (i) for power operated crane trolleys, ______ and for hand operated trolleys, ______ of the sum of the weights of the lifted loads and of the crane trolley excluding other parts of the crane; (ii)……” — what value is stated?', '["10 %","30 %","40 %","20 %"]', 3, 'Clause 17.8.3 (GHBC-C-003602, page 661): The minimum horizontal design loads on cranes runway rails are: (a)  Lateral force which shall be: (i) for power operated crane trolleys, 20% and for hand operated trolleys, 10% of the sum of the weights of the lifted loads and of the crane trolley excluding other parts of the crane; (ii) applied at the top of the rail, one-half in each side of the runway, and (iii) considered acting in either dir', 'standard', 'GHBC-C-003602', 'GHBC-REQ-012633', 661, 'f6b9172a27f709c0176c8b6d4c8c6fb7e494b259e5ce3da07678b67450133b98', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3a0e47d7821d208b', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.8.3): “…which shall be: (i) for power operated crane trolleys, ______ and for hand operated trolleys, ______ of the sum of the weights of the lifted loads and of the crane trolley excluding other parts of the crane; (ii)……” — what value is stated?', '["5 %","15 %","20 %","10 %"]', 3, 'Clause 17.8.3 (GHBC-C-003602, page 661): The minimum horizontal design loads on cranes runway rails are: (a)  Lateral force which shall be: (i) for power operated crane trolleys, 20% and for hand operated trolleys, 10% of the sum of the weights of the lifted loads and of the crane trolley excluding other parts of the crane; (ii) applied at the top of the rail, one-half in each side of the runway, and (iii) considered acting in either dir', 'standard', 'GHBC-C-003602', 'GHBC-REQ-012633', 661, 'f6b9172a27f709c0176c8b6d4c8c6fb7e494b259e5ce3da07678b67450133b98', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-721df2ecf5ba71c8', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.8.4): “…at the top of a railing which guards a drop of more than ______ shall be: (a) 5.8kN/m for exterior balconies of individual residential units and a concentrated load of 0.9kN applied concurrently; for industrial catwalks……” — what value is stated?', '["915 mm","460 mm","230 mm","686 mm"]', 1, 'Clause 17.8.4 (GHBC-C-003603, page 661): The minimum design load applied horizontally at the top of a railing which guards a drop of more than 460mm shall be: (a) 5.8kN/m for exterior balconies of individual residential units and a concentrated load of 0.9kN applied concurrently; for industrial catwalks and other areas where crowding by many people is very improbable.', 'standard', 'GHBC-C-003603', 'GHBC-REQ-012635', 661, '88d0eaa53771ad007ddbef438e8b7a186b273c77e1bb2a129d1ae77441136c03', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d0674ad40768c992', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.8.4): “…to panels under railings which guard a drop of more than ______ shall be 1.0kN/m2.…” — what value is stated?', '["686 mm","915 mm","460 mm","230 mm"]', 2, 'Clause 17.8.4 (GHBC-C-003603, page 661): The minimum design load applied horizontally to panels under railings which guard a drop of more than 460mm shall be 1.0kN/m2.', 'standard', 'GHBC-C-003603', 'GHBC-REQ-012637', 661, 'f998d8998f22f6b088351fbddc359e7d29034e0575066176300feaa48385c879', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0b3236cd8093e525', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.8.4): “…at the top of a railing which guards a drop of more than ______ shall be 1.5kN/m acting separately from the horizontal load provided in Clause 17.8.4(1).…” — what value is stated?', '["230 mm","686 mm","915 mm","460 mm"]', 3, 'Clause 17.8.4 (GHBC-C-003603, page 661): (3) The minimum design load applied vertically at the top of a railing which guards a drop of more than 460mm shall be 1.5kN/m acting separately from the horizontal load provided in Clause 17.8.4(1).', 'standard', 'GHBC-C-003603', 'GHBC-REQ-012638', 661, '556188ab7536c6f9ca58d6717d6556c80ec7c72b0bf92e66e6e8024e33afd382', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0a1ed33d566e8307', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.9.5): “…table is specified in 5.9.5(2) and the factors S1, S2, S______ 5.9.5(3).…” — what value is stated?', '["4.3 in","6 in","3 in","1.5 in"]', 2, 'Clause 17.9.5 (GHBC-C-003608, page 664): (1) General: The design wind speed Vs should be calculated from Vs = VS1 S2 S3 The basic wind speed table is specified in 5.9.5(2) and the factors S1, S2, S3 in 5.9.5(3).', 'study', 'GHBC-C-003608', 'GHBC-REQ-012728', 664, '7fd60971017649223c67f347bbaf72460b90bca4cb011486f5e0af621aba43ca', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c94f459d15403cf6', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.9.5): “…velocity is the maximum 3-second gust speed at a height of ______ above ground likely to be exceeded on the average not more than once in 50years______ open country.…” — what value is stated?', '["5 m","15 m","20 m","10 m"]', 3, 'Clause 17.9.5 (GHBC-C-003608, page 664): (2) Basic Wind Speed: a) The basic wind velocity is the maximum 3-second gust speed at a height of 10m above ground likely to be exceeded on the average not more than once in 50years, in open country.', 'study', 'GHBC-C-003608', 'GHBC-REQ-012729', 664, '985e3db8706da139794f90e00ae184d0ee548784d06995c909dbef733cfc1fd1', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6d422da533cafaa6', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…The value of S______ Table 17.9 can be explicitly calculated for the effect of a cliff or escarpment at a site.…” — what value is stated?', '["2 in","1 in","0.5 in","1.5 in"]', 1, 'Clause null (GHBC-C-003609, page 666): The value of S1 in Table 17.9 can be explicitly calculated for the effect of a cliff or escarpment at a site.', 'standard', 'GHBC-C-003609', 'GHBC-REQ-012768', 666, 'ab48a4dde0cdbb33baf5bd98131241ec393d4c1c99e7cb63854f2b6fec7738bc', 'extracted', 1);
