INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-97494a268106bc2a', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…Tan θ = 10/35 = 0.2857, θ = 15.74 X = +5 Le = ______ H = ______ X/Le = +5/10 = +0.5 H/Le = 20/10 = 2 Basic wind speed for Ho, V = ______/s (Fig. 5.1,…” — what value is stated?', '["10 m","5 m","15 m","20 m"]', 0, 'Clause null (GHBC-C-003610, page 670): Tan θ = 10/35 = 0.2857, θ = 15.74 X = +5     Le = 10m   H = 20m    X/Le = +5/10 = +0.5       H/Le = 20/10 = 2 Basic wind speed for Ho, V = 29m/s (Fig. 5.1,', 'standard', 'GHBC-C-003610', 'GHBC-REQ-012817', 670, '931b2e4ff871a431615b6393e86e97302ae45dcf34dcbe7248bc58ade89238ab', 'extracted', 1);
