INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c16f0a2e39494ecd', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.9.6): “…speed = Vs = V x S1 x S2 x S3 = 29 (1.12)(0.9)(1.05) = ______/s…” — what value is stated?', '["30.7 m","15.25 m","45 m","61.6 m"]', 0, 'Clause 17.9.6 (GHBC-C-003612, page 672): From Table 17.11, factor C = 1.2Z/Le = 1.2x20/10 = 2.4 → S1 = 1 + C x s = 1+ 0.05 x 2.4 = 1.12 →Design wind speed = Vs = V x S1 x S2 x S3 = 29 (1.12)(0.9)(1.05) = 30.7m/s', 'study', 'GHBC-C-003612', 'GHBC-REQ-012821', 672, '1a585f46bd47a44cdf2cc9514f69ba79572ba6c84264a78c7d0991342325e9a9', 'requires_review', 0);
