INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7e02ca26d11850c2', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause null): “…members of the frame have DVs value less or greater than ______/s are given in Table 17.27.…” — what value is stated?', '["6 m2","3 m2","9 m2","12 m2"]', 0, 'Clause null (GHBC-C-003617, page 690): The force coefficients for a single frame consisting of (a) flat-sided members or (b) circular clause members in which all the members of the frame have DVs value less or greater than 6m2/s are given in Table 17.27.', 'standard', 'GHBC-C-003617', 'GHBC-REQ-012887', 690, 'c4b092b2dabab62b0551dd4b946f233ec268b5c8d277d17fb84f878f0a5995a2', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e82e81e5e0ca1d72', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 0.5): “…the overall force coefficients Cf given in Tables 5.29 and ______ay be used.…” — what value is stated?', '["5.3 m","2.7 m","8 m","10.2 m"]', 0, 'Clause 0.5 (GHBC-C-003620, page 692): When it can be shown that all the members of the tower are wholly in the same flow regime the overall force coefficients Cf  given in Tables 5.29 and 5.30 may be used.', 'standard', 'GHBC-C-003620', 'GHBC-REQ-012905', 692, 'a76622bae238a0b05f95a8bde5e3ca531c89cf64289f561fb383f234464e6227', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1141ff50a6f42584', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.4.1.1): “…stress shall not exceed its normal values by more than ______.…” — what value is stated?', '["25 %","30 %","15 %","7.5 %"]', 2, 'Clause 17.10.4.1.1 (GHBC-C-003627, page 695): (iii) The actual yield stress shall not exceed its normal values by more than 15%.', 'study', 'GHBC-C-003627', 'GHBC-REQ-012933', 695, '82ad535116e7a8518be0225a1f3920682f32acd7cae8dcdd1aadfc160c75200e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1a78bb022d370000', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.4.2.1): “…centre of mass and that of the stiffness does not exceed l______ of the ‗resistance radius‘ defined as the square root of the ratio of storey torsional and translation stiffnesses.…” — what value is stated?', '["10 %","5 %","2.5 %","7.5 %"]', 1, 'Clause 17.10.4.2.1 (GHBC-C-003631, page 696): (ii) At any storey the distance (measured in the direction orthogonal to that of the seismic action) between the centre of mass and that of the stiffness does not exceed l5% of the ‗resistance radius‘ defined as the square root of the ratio of storey torsional and translation stiffnesses.', 'study', 'GHBC-C-003631', 'GHBC-REQ-012947', 696, '357dc7d58274dc515700e2676c837413cc25ea1fbd296ee06510d49c694a96f3', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-990b00fc8ac9f65b', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.4.2.1): “…its height, the setback at any floor is not greater than l______ of the plan dimension in the direction of the setback.…” — what value is stated?', '["0 %","0.2 %","0.25 %","0.4 %"]', 0, 'Clause 17.10.4.2.1 (GHBC-C-003631, page 696): (iii) In the case of a gradual setback along its height, the setback at any floor is not greater than l0% of the plan dimension in the direction of the setback.', 'study', 'GHBC-C-003631', 'GHBC-REQ-012952', 696, 'e3fc64463ecd2fe3f54f411c79bf87fe8e1b3394a4520c498e0b78ff33a4613e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1bc24ed37beb20b4', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.4.2.1): “…be complied with if the setback occurs within the lower l______ of the total height of the building.…” — what value is stated?', '["2.5 %","7.5 %","10 %","5 %"]', 3, 'Clause 17.10.4.2.1 (GHBC-C-003631, page 696): This clause need not be complied with if the setback occurs within the lower l5% of the total height of the building.', 'study', 'GHBC-C-003631', 'GHBC-REQ-012953', 696, 'e6df39e568c8f0e9120a1ba29fc94b59604ba2c4fbea5b1ee4e6ff5c4bfb8b29', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-44c232aa659a60e2', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.4.2.3): “…in 17.10.4.2.4 provided their height does not exceed ______, and the fundamental period is shorter than 2 secs.…” — what value is stated?', '["152 m","80 m","40 m","120 m"]', 1, 'Clause 17.10.4.2.3 (GHBC-C-003633, page 697): (3) Regular buildings can be designed according to the simplified method of analysis (indicated as equivalent static analysis) described in 17.10.4.2.4 provided their height does not exceed 80m, and the fundamental period is shorter than 2 secs.', 'study', 'GHBC-C-003633', 'GHBC-REQ-012969', 697, 'e4e611595b678b3d85914b750662e0e91c8ed83fbcc9c302b876b0ffa61b846c', 'requires_review', 0);
