INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-65eb2f3ef3b34eb9', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.6.4): “…to the various walls, as obtained from the elastic analysis______ay be subsequently modified, provided the global equilibrium is maintained and the maximum value of the action in any wall is not reduced by more than……” — what value is stated?', '["30 %","40 %","20 %","10 %"]', 2, 'Clause 17.10.6.4 (GHBC-C-003644, page 704): (4) Structural Walls (a) The design actions shall be those obtained from a linear analysis of the building modified as appropriate in accordance with clause 17.10.6.4(b) - (f) (b) Redistribution (i) The distribution of the total force to the various walls, as obtained from the elastic analysis, may be subsequently modified, provided the global equilibrium is maintained and the maximum value of the', 'standard', 'GHBC-C-003644', 'GHBC-REQ-013157', 704, '45605293f57dffa8ac6f427964734dc6a7f6626e99e8382a921c00272cb7c096', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-efe465a40ff40864', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.7.1): “…1.6.1 as functions of concrete grades and 1 is given by ______   o…” — what value is stated?', '["3.75 m","11.1 m","15 m","7.4 m"]', 3, 'Clause 17.10.7.1 (GHBC-C-003646, page 707): (4) Resistance to Shear (a) Contribution of Concrete The magnitude of the term Vcd, expressing design resistance contributed by concrete shall be taken as follows: (i) When  Nd ≤ 0.1 Ag fcd , Vcd shall be assumed to be zero in all regions where stirrup-ties are required in accordance with Clause 5.10.8.2.3 (with the exception of Case (c)) shall be (ii) When  Nd > 0.1 Ag fcd ,  Vcd computed by the ', 'standard', 'GHBC-C-003646', 'GHBC-REQ-013189', 707, '1e76acf77474fbe195d67011206acf4e9ea273ca8735b7000f6f8fe32d30615c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a657ae104b9e1b6c', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.7.2): “…plane of any beam framing into a joint shall not exceed ______, and in no case, shall there be, less than one intermediate bar in each side of the column in that plane.…” — what value is stated?', '["100 mm","300 mm","400 mm","200 mm"]', 3, 'Clause 17.10.7.2 (GHBC-C-003647, page 709): (d) The spacing of vertical joint reinforcement in each plane of any beam framing into a joint shall not exceed 200mm, and in no case, shall there be, less than one intermediate bar in each side of the column in that plane.', 'study', 'GHBC-C-003647', 'GHBC-REQ-013260', 709, '34408477b86852a74f951926f91dc04f76b9c01e32b6502c9c0419fc4e1f1345', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c6d9440fcfb3b37d', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.7.4): “…II buildings, the indicated limits may be increased by ______ if it can be demonstrated that the finishes adopted are not brittle - type and can accommodate without significant damage to those limits.…” — what value is stated?', '["95 %","50 %","25 %","75 %"]', 1, 'Clause 17.10.7.4 (GHBC-C-003650, page 712): (b) For Class II buildings, the indicated limits may be increased by 50% if it can be demonstrated that the finishes adopted are not brittle - type and can accommodate without significant damage to those limits.', 'study', 'GHBC-C-003650', 'GHBC-REQ-013287', 712, 'eaa444d9395c2db486a501b075eaa5582479b09cd3707ae4602650d20a9b033a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-67dd905c010c057d', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.1): “…shall be satisfied (i) The width shall not be less than ______ or more than the width of the supporting column, plus lengths, on each side of this member not exceeding one fourth of the depth of the column cross clause.…” — what value is stated?', '["400 mm","200 mm","100 mm","300 mm"]', 1, 'Clause 17.10.8.2.1 (GHBC-C-003653, page 713): DL II and DL III Structures Unless special proofs for exemption are given, the following dimensional limitations shall be satisfied (i) The width shall not be less than 200mm or more than the width of the supporting column, plus lengths, on each side of this member not exceeding one fourth of the depth of the column cross clause.', 'study', 'GHBC-C-003653', 'GHBC-REQ-013304', 713, '806aa39e5c5b23508b4b78b56d8c804bef63c1b59cb7d1520d5f5e18b91a83d3', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-095567fc37d201f3', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…(b) At least two ______ bars shall be provided both top and bottom throughout the length of the members.…” — what value is stated?', '["18 mm","23.8 mm","12 mm","6 mm"]', 2, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (b) At least two 12mm bars shall be provided both top and bottom throughout the length of the members.', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013319', 714, 'b96d70f3370eaf575ce319c461520cca45e03d6b2cf98b81faf8f59ab57150a7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-27b2c528e8e3d1ca', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…Effective Reinforcement (v) In all cases, at least ______ of the reinforcement in each face providing the required flexural capacity______ust pass through or be anchored in the column core.…” — what value is stated?', '["75 %","40 %","95 %","90 %"]', 0, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): Effective Reinforcement (v) In all cases, at least 75% of the reinforcement in each face providing the required flexural capacity, must pass through or be anchored in the column core.', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013329', 714, '793ae2b0ffb119eec7b172847557bd1ff3a37eaa3815b51e3a5ce42263d74e31', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c511cc932674716e', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…______inimum Transverse Reinforcement (1) Transverse reinforcement as specified in this clause shall be provided unless a larger amount is required to resist shear (clause 17.10.7.1.(4) ) .…” — what value is stated?', '["3.5 m","4.6 m","2.3 m","1.15 m"]', 2, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): 17.10.8.2.3 Minimum Transverse Reinforcement (1) Transverse reinforcement as specified in this clause shall be provided unless a larger amount is required to resist shear (clause 17.10.7.1.(4) ) .', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013332', 714, 'dcc688b26a3ee748f67a422c9383da99684dedac9f0ed65fbf16e9048f2a9b34', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3da7b7907444bfb7', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…defined in 17.10.8.2.3 (1), stirrup ties of not less than ______ diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c)……” — what value is stated?', '["12 mm","6 mm","3 mm","8.7 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (2) DL II Structures In the critical regions as defined in 17.10.8.2.3 (1), stirrup ties of not less than 6mm diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c) 24 times the diameter of the hoop bars (d) 200mm The first hoop shall be located not more distant than 50mm from the face of the support', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013337', 714, 'b39ac663b9bd2ae226b1988805c0522b7faa5cea8d35f893fb1d3820f96b93b7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3da7b7907444bfb7', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…defined in 17.10.8.2.3 (1), stirrup ties of not less than ______ diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c)……” — what value is stated?', '["400 mm","200 mm","100 mm","300 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (2) DL II Structures In the critical regions as defined in 17.10.8.2.3 (1), stirrup ties of not less than 6mm diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c) 24 times the diameter of the hoop bars (d) 200mm The first hoop shall be located not more distant than 50mm from the face of the support', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013337', 714, 'b39ac663b9bd2ae226b1988805c0522b7faa5cea8d35f893fb1d3820f96b93b7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3da7b7907444bfb7', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…defined in 17.10.8.2.3 (1), stirrup ties of not less than ______ diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c)……” — what value is stated?', '["100 mm","50 mm","25 mm","75 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (2) DL II Structures In the critical regions as defined in 17.10.8.2.3 (1), stirrup ties of not less than 6mm diameter shall be provided, with maximum spacings not exceeding the smaller of: (a) h/4 (b) eight times the minimum diameter of the longitudinal bars (c) 24 times the diameter of the hoop bars (d) 200mm The first hoop shall be located not more distant than 50mm from the face of the support', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013337', 714, 'b39ac663b9bd2ae226b1988805c0522b7faa5cea8d35f893fb1d3820f96b93b7', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-dfb0be0e95fa2601', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…defined in 17.10.8.2.3 (1) stirrup ties of not less than ______ diameter shall be provided, with maximum spacing not exceeding the smaller of: (a) h/4 (b) six times the diameter of the longitudinal bars (c) ______ The……” — what value is stated?', '["12 mm","6 mm","3 mm","8.7 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (3) DL III Structures In the critical regions as defined in 17.10.8.2.3 (1) stirrup ties of not less than 6mm diameter shall be provided, with maximum spacing not exceeding the smaller of: (a) h/4 (b) six times the diameter of the longitudinal bars (c) 150 mm The minimum area of one leg of the transverse reinforcement shall be:', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013338', 714, '618b7af3172d6a7fd38d7d1e392f996a3112bdf1945dd4bdddb06ec7ba7ee9d5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-dfb0be0e95fa2601', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…defined in 17.10.8.2.3 (1) stirrup ties of not less than ______ diameter shall be provided, with maximum spacing not exceeding the smaller of: (a) h/4 (b) six times the diameter of the longitudinal bars (c) ______ The……” — what value is stated?', '["300 mm","150 mm","75 mm","225 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): (3) DL III Structures In the critical regions as defined in 17.10.8.2.3 (1) stirrup ties of not less than 6mm diameter shall be provided, with maximum spacing not exceeding the smaller of: (a) h/4 (b) six times the diameter of the longitudinal bars (c) 150 mm The minimum area of one leg of the transverse reinforcement shall be:', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013338', 714, '618b7af3172d6a7fd38d7d1e392f996a3112bdf1945dd4bdddb06ec7ba7ee9d5', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4e353f7a57d7808f', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.2.2): “…in mm The first hoop shall be located not more than ______ from the face of the supporting member.…” — what value is stated?', '["100 mm","50 mm","25 mm","75 mm"]', 1, 'Clause 17.10.8.2.2 (GHBC-C-003654, page 714): Ab = Sum of the areas of longitudinal bars at the clause considered to be restrained by the transverse leg fyk   = yield strength of longitudinal bars fykt    = yield strength of stirrups S     = spacing of stirrups in mm The first hoop shall be located not more than 50mm from the face of the supporting member.', 'standard', 'GHBC-C-003654', 'GHBC-REQ-013347', 714, '64af434100a64ccd909f1e1b3aaae5667622764cb1e9a3bfafc0bc07656bc065', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3476076fecf8fec2', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.2): “…minimum cross - clauseal dimension shall not be less than ______ The ratio l/b shall not exceed 25 (2) DL III Structures (a) The minimum cross-clause shall not be less than ______ The ratio l/b shall not exceed the……” — what value is stated?', '["381 mm","500 mm","250 mm","125 mm"]', 2, 'Clause 17.10.8.3.2 (GHBC-C-003657, page 715): (1) DL II Structures (a) The minimum cross - clauseal dimension shall not be less than 250mm (b) The ratio l/b shall not exceed 25 (2) DL III Structures (a) The minimum cross-clause shall not be less than 300mm (b) The ratio l/b shall not exceed the value of 16 for columns having moments of opposite sign at the two extremities; 10 for cantilever columns.', 'study', 'GHBC-C-003657', 'GHBC-REQ-013356', 715, 'd181d6f20361a4f7137cb1a21e7ed022ec151c05c62389357d7eeb68c552890e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3476076fecf8fec2', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.2): “…minimum cross - clauseal dimension shall not be less than ______ The ratio l/b shall not exceed 25 (2) DL III Structures (a) The minimum cross-clause shall not be less than ______ The ratio l/b shall not exceed the……” — what value is stated?', '["450 mm","600 mm","300 mm","150 mm"]', 2, 'Clause 17.10.8.3.2 (GHBC-C-003657, page 715): (1) DL II Structures (a) The minimum cross - clauseal dimension shall not be less than 250mm (b) The ratio l/b shall not exceed 25 (2) DL III Structures (a) The minimum cross-clause shall not be less than 300mm (b) The ratio l/b shall not exceed the value of 16 for columns having moments of opposite sign at the two extremities; 10 for cantilever columns.', 'study', 'GHBC-C-003657', 'GHBC-REQ-013356', 715, 'd181d6f20361a4f7137cb1a21e7ed022ec151c05c62389357d7eeb68c552890e', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e262080c12e056c3', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.3): “…ratio shall not be less than 0.01 or larger than ______cluding the region of lap splices.…” — what value is stated?', '["0.06 in","0.0296 in","0.091 in","0.12 in"]', 0, 'Clause 17.10.8.3.3 (GHBC-C-003658, page 716): (1) General (a) The reinforcement ratio shall not be less than 0.01 or larger than 0.06 including the region of lap splices.', 'study', 'GHBC-C-003658', 'GHBC-REQ-013357', 716, 'dcadb019b2d510fa63940ad76f2aad5938f181dfe450729f0e16ab50ece8f2d2', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4986b35bcf987c8b', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.3): “…shall not be spaced further apart between centres than ______.…” — what value is stated?', '["100 mm","300 mm","400 mm","200 mm"]', 3, 'Clause 17.10.8.3.3 (GHBC-C-003658, page 716): (c) The bars shall not be spaced further apart between centres than 200mm.', 'study', 'GHBC-C-003658', 'GHBC-REQ-013359', 716, 'c1e2720b97504ac591e4c7e7b246017b8c4126bc73480b6bcaae0abf408d80e2', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7d88001cdb64bdf0', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…(ii) one-sixth of the clear height of the column (iii) ______When a masonry infill wall is in contact with one or both of the two opposite sides of the column, over the whole height or part of it, the entire column……” — what value is stated?', '["900 mm","450 mm","225 mm","668 mm"]', 1, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (ii) one-sixth of the clear height of the column (iii) 450mm (b)When a masonry infill wall is in contact with one or both of the two opposite sides of the column, over the whole height or part of it, the entire column height shall be considered as a critical region.(Fig  17.10.8.5a)', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013362', 716, 'c3c0ae100504754d769a770fed1bfff100d632b07561de41e09c36d7d436c915', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a49dafec815ef7ee', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…transverse reinforcement having a minimum diameter of ______ in the form of spiral or hoop reinforcement shall be provided.…” — what value is stated?', '["4 mm","12 mm","16 mm","8 mm"]', 3, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (3)   DL II Structures (A) Critical Regions (a) Special transverse reinforcement having a minimum diameter of 8mm in the form of spiral or hoop reinforcement shall be provided.', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013364', 716, '277f1df0f03f807e846a23d01f46cddddaa9d4563b1e67cf82064f12454e70be', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-12afda969c6d6c78', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…the least cross-clauseal dimension of the clause (iii) ______ The transverse reinforcement in the amount specified above shall be continued throughout the length of the beam - column joint.…” — what value is stated?', '["100 mm","300 mm","400 mm","200 mm"]', 3, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (b) Cross ties to restrain longitudinal bars not directly held by hoops shall be used in accordance with BS 8110 (c) The maximum spacing between spirals or hoops shall not exceed the smaller of: (i) eight times the minimum diameter of the longitudinal bars (ii) one half the least cross-clauseal dimension of the clause (iii) 200 mm (d) The transverse reinforcement in the amount specified above shal', 'study', 'GHBC-C-003659', 'GHBC-REQ-013365', 716, 'e4a82c3a28c148d9ecb919577ba3085732fabb2e00438f73d6ea0c735cf05f52', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-30b4df9413b32518', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…REINFORCEMENT - DL II Critical Region lc = max (h, l/6, ______) (4) DL III Structures (A) Definition (a) The volumetric ratio is the ratio of volume of spiral or hoop reinforcement to total volume of concrete core ( out……” — what value is stated?', '["225 mm","668 mm","900 mm","450 mm"]', 3, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): TRANSVERSE REINFORCEMENT - DL II Critical Region lc = max   (h,  l/6,  450 mm) (4) DL III Structures (A) Definition (a) The volumetric ratio is the ratio of volume of spiral or hoop reinforcement to total volume of concrete core ( out -to-out of bars) within the spacing, Sh (b) The volumetric ratio s for rectangular clauses is defined as', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013368', 716, '63eb3367a85da3132def12cf9313215bcc5516ccec96a26243bc1edaac29fa81', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-be5227f8f958720c', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…2 (b) The minimum diameter of spiral or hoops shall be ______.…” — what value is stated?', '["8 mm","4 mm","12 mm","16 mm"]', 0, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): OF 1 AND 2 (b) The minimum diameter of spiral or hoops shall be 8mm.', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013383', 716, 'b49ac944a640ff0e8fd7a00b68c62cee4b0f29bb7ecef1675513bfc9574fdea2', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-50241466650228f6', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…(iii) l______ Each longitudinal reinforcement bar or bundle of bars shall be laterally supported by the corner of a hoop having an included angle of not more than 135o or by a supplementary cross tie except that the……” — what value is stated?', '["25 mm","75 mm","100 mm","50 mm"]', 3, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (iii) l50 mm (d) Each longitudinal reinforcement bar or bundle of bars shall be laterally supported by the corner of a hoop having an included angle of not more than 135o    or by a supplementary cross tie except that the following bars are exempted from this requirement: (i) bars or bundles of bars which lie between two bars supported by the same hoop where the distance between the laterally supp', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013387', 716, '097d759db44ea817b7bc3f20ff3afa2f3cc844d7259873969aaa1be8adfefc61', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-50241466650228f6', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…(iii) l______ Each longitudinal reinforcement bar or bundle of bars shall be laterally supported by the corner of a hoop having an included angle of not more than 135o or by a supplementary cross tie except that the……” — what value is stated?', '["100 mm","300 mm","400 mm","200 mm"]', 3, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (iii) l50 mm (d) Each longitudinal reinforcement bar or bundle of bars shall be laterally supported by the corner of a hoop having an included angle of not more than 135o    or by a supplementary cross tie except that the following bars are exempted from this requirement: (i) bars or bundles of bars which lie between two bars supported by the same hoop where the distance between the laterally supp', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013387', 716, '097d759db44ea817b7bc3f20ff3afa2f3cc844d7259873969aaa1be8adfefc61', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cc6c5c8c76ea1140', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…bars within the concrete core centred more than ______ from the inner face of hoops.…” — what value is stated?', '["75 mm","38 mm","114 mm","150 mm"]', 0, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): (ii) inner layers of reinforcing bars within the concrete core centred more than 75mm from the inner face of hoops.', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013388', 716, '61fc9e3c0e758c9f53dbd7509e0a3eeecfe3d0e5bc7d549f30fa9654a22a3d6f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-418e8720eb793027', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…of hoops shall not be spaced transversely more than either ______ or one-quarter of the column clause dimension perpendicular to the direction of the transverse steel.…” — what value is stated?', '["300 mm","400 mm","200 mm","100 mm"]', 2, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): Supplementary ties and legs of hoops shall not be spaced transversely more than either 200mm or one-quarter of the column clause dimension perpendicular to the direction of the transverse steel.', 'study', 'GHBC-C-003659', 'GHBC-REQ-013390', 716, 'a1d124426fcb81dfd7a00b0ed7b9222f7f3de4032d8e81859fbd9438d3a977d9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cd3b07e1e53c31e7', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.3.4): “…DUCTILITY LEVEL III Critical Region lc = max (h, l/6, ______) (Fig. 17.10.8.6)…” — what value is stated?', '["450 mm","225 mm","668 mm","900 mm"]', 0, 'Clause 17.10.8.3.4 (GHBC-C-003659, page 716): REINFORCEMENT DUCTILITY LEVEL III Critical Region lc = max (h, l/6, 450mm) (Fig. 17.10.8.6)', 'standard', 'GHBC-C-003659', 'GHBC-REQ-013404', 716, '78bdae05cf82fd2b5bfab969312c637a5e4de9e8f7e0ddf7f80e5feb5d57349f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0313e1f7e7547880', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.4.1): “…core exceed ten times the diameter of the column bar, or ______, whichever is less.…” — what value is stated?', '["200 mm","100 mm","300 mm","400 mm"]', 0, 'Clause 17.10.8.4.1 (GHBC-C-003661, page 720): (2) DL III Structures (a) The horizontal transverse confinement reinforcement in beam - column joints shall not be less than that required for the columns with the exception of joints connecting beams at all four column faces that are designed according to Clause 17.10.7.2(1)(b)(ii) or (iii) in which case the transverse joint reinforcement may be reduced to one half of that required for the column', 'study', 'GHBC-C-003661', 'GHBC-REQ-013406', 720, 'cc8b2e3f8bf4b0f087bad7286345751584924795b457857f76ba09ce8a30f006', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4d5de54c44f3d198', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.5.1): “…(1) General (i) Wall thickness shall not be less than ______.…” — what value is stated?', '["150 mm","75 mm","225 mm","300 mm"]', 0, 'Clause 17.10.8.5.1 (GHBC-C-003663, page 720): (1) General (i) Wall thickness shall not be less than 150 mm.', 'study', 'GHBC-C-003663', 'GHBC-REQ-013409', 720, 'c774018c685c3b4e18ad1ddf11d2cad6d4a2b6cd1c260d7c7a7f7a91bb8a128a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4f06a372bd2b6fb1', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 1.7.5.1): “…ratio in any part of the clause shall not be less than ______ or greater than ______.…” — what value is stated?', '["0.075 %","0.4 %","0.2 %","0.25 %"]', 3, 'Clause 1.7.5.1 (GHBC-C-003665, page 720): Reinforcement Ratio 17.10.8.5.2 Longitudinal Reinforcement (a) The vertical reinforcement ratio in any part of the clause shall not be less than 0.25% or greater than 4% (see Fig. 17.10.8.10).', 'study', 'GHBC-C-003665', 'GHBC-REQ-013416', 720, '80fa7a61a67399ee8a6cf6ea9550c74e8e7bb6f527b0c356900b1741811f3c21', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4f06a372bd2b6fb1', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 1.7.5.1): “…ratio in any part of the clause shall not be less than ______ or greater than ______.…” — what value is stated?', '["2 %","5 %","7.5 %","4 %"]', 3, 'Clause 1.7.5.1 (GHBC-C-003665, page 720): Reinforcement Ratio 17.10.8.5.2 Longitudinal Reinforcement (a) The vertical reinforcement ratio in any part of the clause shall not be less than 0.25% or greater than 4% (see Fig. 17.10.8.10).', 'study', 'GHBC-C-003665', 'GHBC-REQ-013416', 720, '80fa7a61a67399ee8a6cf6ea9550c74e8e7bb6f527b0c356900b1741811f3c21', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-87b22c52dfeae116', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 1.7.5.1): “…exceed b/10 (d) The maximum spacing between bars shall be ______ except where the clause is required to be confined______ which case the spacing shall not exceed ______.…” — what value is stated?', '["300 mm","150 mm","450 mm","600 mm"]', 0, 'Clause 1.7.5.1 (GHBC-C-003665, page 720): (b) At least two orthogonal grids of reinforcement shall be used one near each side of the wall (c) The diameter of the bars used in any part of a wall shall not exceed b/10 (d) The maximum spacing between bars shall be 300mm except where the clause is required to be confined, in which case the spacing shall not exceed 200 mm.', 'study', 'GHBC-C-003665', 'GHBC-REQ-013417', 720, 'b3ccdb91542312d0d2cceefac8a0aeed88148d472aae674c445e4cd83f78db24', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-87b22c52dfeae116', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 1.7.5.1): “…exceed b/10 (d) The maximum spacing between bars shall be ______ except where the clause is required to be confined______ which case the spacing shall not exceed ______.…” — what value is stated?', '["200 mm","100 mm","300 mm","400 mm"]', 0, 'Clause 1.7.5.1 (GHBC-C-003665, page 720): (b) At least two orthogonal grids of reinforcement shall be used one near each side of the wall (c) The diameter of the bars used in any part of a wall shall not exceed b/10 (d) The maximum spacing between bars shall be 300mm except where the clause is required to be confined, in which case the spacing shall not exceed 200 mm.', 'study', 'GHBC-C-003665', 'GHBC-REQ-013417', 720, 'b3ccdb91542312d0d2cceefac8a0aeed88148d472aae674c445e4cd83f78db24', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e02a5ef20c5d77f9', NULL, NULL, 'threshold', 17, 'GS 1207:2018 Part 17 (Clause 17.10.8.5.4): “…however their spacing or pitch shall not exceed l______.…” — what value is stated?', '["0.127 mm","0.15 mm","0 mm","0.102 mm"]', 2, 'Clause 17.10.8.5.4 (GHBC-C-003667, page 723): (a) The diagonal reinforcement in each direction shall be enclosed by rectangular stirrups, hoops or spirals in accordance with Clause 5.10.8.3.4(4), however their spacing or pitch shall not exceed l00mm.', 'study', 'GHBC-C-003667', 'GHBC-REQ-013468', 723, 'c36bac596cf783c6050ae8b08bfe6d228a32d5c326c0b8db7237110f4c02fa1d', 'requires_review', 0);
