INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9f91147f6b09befc', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.4.6): “…EXCEPTIONS: Compacted fill material ______ in depth or less need not comply with an approved report, provided that the in-place dry density is not less than 90 percent of the maximum dry density at optimum moisture……” — what value is stated?', '["24 in","12 in","6 in","18 in"]', 1, 'Clause 18.4.6 (GHBC-C-003696, page 738): EXCEPTIONS: Compacted fill material 12 inches (305 mm) in depth or less need not comply with an approved report, provided that the in-place dry density is not less than 90 percent of the maximum dry density at optimum moisture content determined in accordance with ASTM D1557. The compaction shall be verified by special inspection in accordance with Part 19.5.6.', 'standard', 'GHBC-C-003696', 'GHBC-REQ-013733', 738, 'fd87e841fdbd5f566a20dfba3d56a3ce03fa561661bac0a064d9c3813c189044', 'extracted', 1);
