INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e0ac3cfe37b84fb8', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.3.2): “…consist of two-ply hot-mopped felts, not less than 6-mil (______; ______) polyvinyl chloride, 40-mil (______; ______) polymer-modified asphalt, 6-mil (______; ______) polyethylene or other approved methods or materials……” — what value is stated?', '["0.3 mm","0.152 mm","0.102 mm","0.25 mm"]', 1, 'Clause 18.5.3.2 (GHBC-C-003709, page 740): Waterproofing shall consist of two-ply hot-mopped felts, not less than 6-mil (0.006 inch; 0.152 mm) polyvinyl chloride, 40-mil (0.040 inch; 1.02 mm) polymer-modified asphalt, 6-mil (0.006 inch; 0.152 mm) polyethylene or other approved methods or materials capable of bridging nonstructural cracks.', 'standard', 'GHBC-C-003709', 'GHBC-REQ-013766', 740, 'aff4da142105063db5fde26134b1dd45cdc3c9ec9c79b2b0b0332e2d0d1ea180', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2954863cfbbeb33', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.1): “…shall be placed over a floor base course not less than ______ in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (______) sieve.…” — what value is stated?', '["51 mm","153 mm","204 mm","102 mm"]', 3, 'Clause 18.5.4.1 (GHBC-C-003713, page 740): Floors of basements, except as provided for in Clause 18.5.1.1, shall be placed over a floor base course not less than 102 mm (4 inches) in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (4.75 mm) sieve.', 'standard', 'GHBC-C-003713', 'GHBC-REQ-013772', 740, 'b312835a0ee408dd8ca621590e997f16f9769c8da533c771c2f097fe23e7ee80', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-63774c1ee8d37be8', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.1): “…shall be placed over a floor base course not less than ______ in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (______) sieve.…” — what value is stated?', '["4 in","2 in","6 in","8 in"]', 0, 'Clause 18.5.4.1 (GHBC-C-003713, page 740): Floors of basements, except as provided for in Clause 18.5.1.1, shall be placed over a floor base course not less than 102 mm (4 inches) in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (4.75 mm) sieve.', 'standard', 'GHBC-C-003713', 'GHBC-REQ-013772', 740, 'b312835a0ee408dd8ca621590e997f16f9769c8da533c771c2f097fe23e7ee80', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f2954863cfbbeb33', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.1): “…shall be placed over a floor base course not less than ______ in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (______) sieve.…” — what value is stated?', '["2.31 mm","7 mm","9.5 mm","4.75 mm"]', 3, 'Clause 18.5.4.1 (GHBC-C-003713, page 740): Floors of basements, except as provided for in Clause 18.5.1.1, shall be placed over a floor base course not less than 102 mm (4 inches) in thickness that consists of gravel or crushed stone containing not more than 10 percent of material that passes through a No. 4 (4.75 mm) sieve.', 'standard', 'GHBC-C-003713', 'GHBC-REQ-013772', 740, 'b312835a0ee408dd8ca621590e997f16f9769c8da533c771c2f097fe23e7ee80', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6ca0982fb029bcec', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…more than 10percent material that passes through a No. 4 (______) sieve.…” — what value is stated?', '["7 mm","9.5 mm","4.75 mm","2.31 mm"]', 2, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): A drain shall be placed around the perimeter of a foundation that consists of gravel or crushed stone containing not more than 10percent material that passes through a No. 4 (4.75 mm) sieve.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013774', 740, '9e1ab8493bde0c95e0cf676639323951fbd8674c7bbde5ac81d6ad35b12e65c3', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c1376d6df4d4775c', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The drain shall extend not less than ______ beyond the outside edge of the footing.…” — what value is stated?', '["152.4 mm","457 mm","610 mm","305 mm"]', 3, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The drain shall extend not less than 305 mm (12 inches) beyond the outside edge of the footing.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013775', 740, '067ae4533a7d4d8618ec54e19fa1e33e5cbee8487d85e888c1ada8dacdb8d68c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bc6c89d50b07d381', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The drain shall extend not less than ______ beyond the outside edge of the footing.…” — what value is stated?', '["6 in","18 in","24 in","12 in"]', 3, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The drain shall extend not less than 305 mm (12 inches) beyond the outside edge of the footing.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013775', 740, '067ae4533a7d4d8618ec54e19fa1e33e5cbee8487d85e888c1ada8dacdb8d68c', 'extracted', 1);
