INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-940ed19398c6cfbe', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…the floor, and that the top of the drain is not less than ______ above the top of the footing.…” — what value is stated?', '["12 in","6 in","3 in","9 in"]', 1, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The thickness shall be such that the bottom of the drain is not higher than the bottom of the base under the floor, and that the top of the drain is not less than 152 mm (6 inches) above the top of the footing.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013776', 740, '4956b26e743472ad66ca35397c91433bf135a4f3689559ae2eb152bee67c08e1', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9eb97b7293f6fe5a', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The pipe or tile shall be placed on not less than ______ of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than ______ of the same material.…” — what value is stated?', '["25.4 mm","76 mm","102 mm","51 mm"]', 3, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The pipe or tile shall be placed on not less than 51 mm (2 inches) of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than 152 mm (6 inches) of the same material.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013780', 740, '39d261469a435a735d82f6549e28b6de523901b3a10e81ac4cdb73014d57f223', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bc9da2a85cdf6b4c', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The pipe or tile shall be placed on not less than ______ of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than ______ of the same material.…” — what value is stated?', '["3 in","4 in","2 in","1 in"]', 2, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The pipe or tile shall be placed on not less than 51 mm (2 inches) of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than 152 mm (6 inches) of the same material.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013780', 740, '39d261469a435a735d82f6549e28b6de523901b3a10e81ac4cdb73014d57f223', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9eb97b7293f6fe5a', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The pipe or tile shall be placed on not less than ______ of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than ______ of the same material.…” — what value is stated?', '["76 mm","229 mm","304 mm","152 mm"]', 3, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The pipe or tile shall be placed on not less than 51 mm (2 inches) of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than 152 mm (6 inches) of the same material.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013780', 740, '39d261469a435a735d82f6549e28b6de523901b3a10e81ac4cdb73014d57f223', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bc9da2a85cdf6b4c', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.5.4.2): “…The pipe or tile shall be placed on not less than ______ of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than ______ of the same material.…” — what value is stated?', '["9 in","12 in","6 in","3 in"]', 2, 'Clause 18.5.4.2 (GHBC-C-003714, page 740): The pipe or tile shall be placed on not less than 51 mm (2 inches) of gravel or crushed stone complying with Clause 18.5.4.1, and shall be covered with not less than 152 mm (6 inches) of the same material.', 'standard', 'GHBC-C-003714', 'GHBC-REQ-013780', 740, '39d261469a435a735d82f6549e28b6de523901b3a10e81ac4cdb73014d57f223', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-60c3b17b33c55697', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.6.3.3): “…increased by the tabular value for each additional foot (______) of depth to a value that is not greater than 15 times the tabular value.…” — what value is stated?', '["457 mm","610 mm","305 mm","152.4 mm"]', 2, 'Clause 18.6.3.3 (GHBC-C-003720, page 742): The lateral bearing pressures specified in Table 18.6.2 shall be permitted to be increased by the tabular value for each additional foot (305 mm) of depth to a value that is not greater than 15 times the tabular value.', 'standard', 'GHBC-C-003720', 'GHBC-REQ-013800', 742, 'fb22312ecceccc52a42f5d086de0151126bb05fae65ac4c7558cf02f0da1e999', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b6b355d617970f0e', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.6.3.4): “…to support buildings that are not adversely affected by a ______ motion at the ground surface due to shortterm lateral loads shall be permitted to be designed using lateral bearing pressures equal to two times the……” — what value is stated?', '["25.4 mm","12.7 mm","6.4 mm","19.05 mm"]', 1, 'Clause 18.6.3.4 (GHBC-C-003721, page 742): Isolated poles for uses such as flagpoles or signs and poles used to support buildings that are not adversely affected by a 12.7 mm (1/2inch) motion at the ground surface due to shortterm lateral loads shall be permitted to be designed using lateral bearing pressures equal to two times the tabular values.', 'standard', 'GHBC-C-003721', 'GHBC-REQ-013801', 742, 'f1d1f08b7cb6b9c882d35f90378e927520db0b6af545c5bd00ff07da9e5db8fd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d6a9eae999871949', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.6.3.4): “…to support buildings that are not adversely affected by a ______ motion at the ground surface due to shortterm lateral loads shall be permitted to be designed using lateral bearing pressures equal to two times the……” — what value is stated?', '["3 in","4 in","2 in","1 in"]', 2, 'Clause 18.6.3.4 (GHBC-C-003721, page 742): Isolated poles for uses such as flagpoles or signs and poles used to support buildings that are not adversely affected by a 12.7 mm (1/2inch) motion at the ground surface due to shortterm lateral loads shall be permitted to be designed using lateral bearing pressures equal to two times the tabular values.', 'standard', 'GHBC-C-003721', 'GHBC-REQ-013801', 742, 'f1d1f08b7cb6b9c882d35f90378e927520db0b6af545c5bd00ff07da9e5db8fd', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-47204c98efd2c28c', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.3): “…of rough or random rubble stone shall be not less than ______ thick.…” — what value is stated?', '["406 mm","203 mm","610 mm","812 mm"]', 0, 'Clause 18.7.1.3 (GHBC-C-003725, page 742): Foundation walls of rough or random rubble stone shall be not less than 406 mm (16 inches) thick.', 'standard', 'GHBC-C-003725', 'GHBC-REQ-013807', 742, '56418204304139417a1a7a2560748a11ba707e8e03208f4ce05df75a4d711b7d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ebeac34b6600f1bb', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.3): “…of rough or random rubble stone shall be not less than ______ thick.…” — what value is stated?', '["16 in","8 in","24 in","32 in"]', 0, 'Clause 18.7.1.3 (GHBC-C-003725, page 742): Foundation walls of rough or random rubble stone shall be not less than 406 mm (16 inches) thick.', 'standard', 'GHBC-C-003725', 'GHBC-REQ-013807', 742, '56418204304139417a1a7a2560748a11ba707e8e03208f4ce05df75a4d711b7d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9f970cc965e343ce', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.1): “…supported, except that foundation walls of not less than ______ nominal width shall be permitted to support brick-veneered frame walls and ______ cavity walls provided that the requirements of Clause 18.7.1.6.2 or……” — what value is stated?', '["304.8 mm","406 mm","203 mm","102 mm"]', 2, 'Clause 18.7.1.6.1 (GHBC-C-003728, page 743): The thickness of prescriptively designed foundation walls shall be not less than the thickness of the wall supported, except that foundation walls of not less than 203 mm (8inch) nominal width shall be permitted to support brick-veneered frame walls and 254 mm (10inch-wide) cavity walls provided that the requirements of Clause 18.7.1.6.2 or 18.7.1.6.3 are met.', 'study', 'GHBC-C-003728', 'GHBC-REQ-013817', 743, '3448927ef9aebdfea937d8ff2d080431a268adbf846abd6f77e0e85cdbee95cb', 'requires_review', 0);
