INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9f970cc965e343ce', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.1): “…supported, except that foundation walls of not less than ______ nominal width shall be permitted to support brick-veneered frame walls and ______ cavity walls provided that the requirements of Clause 18.7.1.6.2 or……” — what value is stated?', '["381 mm","508 mm","254 mm","127 mm"]', 2, 'Clause 18.7.1.6.1 (GHBC-C-003728, page 743): The thickness of prescriptively designed foundation walls shall be not less than the thickness of the wall supported, except that foundation walls of not less than 203 mm (8inch) nominal width shall be permitted to support brick-veneered frame walls and 254 mm (10inch-wide) cavity walls provided that the requirements of Clause 18.7.1.6.2 or 18.7.1.6.3 are met.', 'study', 'GHBC-C-003728', 'GHBC-REQ-013817', 743, '3448927ef9aebdfea937d8ff2d080431a268adbf846abd6f77e0e85cdbee95cb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9e63aeef007ef195', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.1): “…supported, except that foundation walls of not less than ______ nominal width shall be permitted to support brick-veneered frame walls and ______ cavity walls provided that the requirements of Clause 18.7.1.6.2 or……” — what value is stated?', '["20 in","10 in","5 in","15 in"]', 1, 'Clause 18.7.1.6.1 (GHBC-C-003728, page 743): The thickness of prescriptively designed foundation walls shall be not less than the thickness of the wall supported, except that foundation walls of not less than 203 mm (8inch) nominal width shall be permitted to support brick-veneered frame walls and 254 mm (10inch-wide) cavity walls provided that the requirements of Clause 18.7.1.6.2 or 18.7.1.6.3 are met.', 'study', 'GHBC-C-003728', 'GHBC-REQ-013817', 743, '3448927ef9aebdfea937d8ff2d080431a268adbf846abd6f77e0e85cdbee95cb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a7862d31e5d8ec4d', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…the use of reinforcement with a minimum yield strength of ______Pa (60,000 pounds per square inch (psi)).…” — what value is stated?', '["414 m","207 m","620 m","900 m"]', 0, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): The size and spacing of vertical reinforcement shown in Table 1807.1.6.2 are based on the use of reinforcement with a minimum yield strength of 414 MPa (60,000 pounds per square inch (psi)).', 'study', 'GHBC-C-003729', 'GHBC-REQ-013822', 743, 'cdd7fcb295fdf33b8861464db49e91084db71c0fc493e66f8acd1e7c7d733263', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-484bfb361a63d567', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…reinforcement with a minimum yield strength of 40,000 psi (______Pa) or ______Pa (50,000 psi) shall be permitted, provided that the same size bar is used and the spacing shown in the table is reduced by multiplying the……” — what value is stated?', '["551 m","276 m","137 m","414 m"]', 1, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): Vertical reinforcement with a minimum yield strength of 40,000 psi (276 MPa) or 345 MPa (50,000 psi) shall be permitted, provided that the same size bar is used and the spacing shown in the table is reduced by multiplying the spacing by 0.67 or 0.83, respectively.', 'study', 'GHBC-C-003729', 'GHBC-REQ-013823', 743, 'a6bb60ac3e04ca2c55c905d858fdb0ef458e8fd551c885149b7f480ef3412345', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-484bfb361a63d567', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…reinforcement with a minimum yield strength of 40,000 psi (______Pa) or ______Pa (50,000 psi) shall be permitted, provided that the same size bar is used and the spacing shown in the table is reduced by multiplying the……” — what value is stated?', '["689 m","345 m","180 m","500 m"]', 1, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): Vertical reinforcement with a minimum yield strength of 40,000 psi (276 MPa) or 345 MPa (50,000 psi) shall be permitted, provided that the same size bar is used and the spacing shown in the table is reduced by multiplying the spacing by 0.67 or 0.83, respectively.', 'study', 'GHBC-C-003729', 'GHBC-REQ-013823', 743, 'a6bb60ac3e04ca2c55c905d858fdb0ef458e8fd551c885149b7f480ef3412345', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-efd52fc0861d4cc0', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…The distance, d, is equal to the wall thickness, t______inus ______ plus one-half the bar diameter, db, [d = t - (1.25 + db / 2)].…” — what value is stated?', '["1.25 in","0.625 in","2 in","2.5 in"]', 0, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): The distance, d, is equal to the wall thickness, t, minus 1.25 inches (32 mm) plus one-half the bar diameter, db, [d = t - (1.25 + db / 2)].', 'study', 'GHBC-C-003729', 'GHBC-REQ-013826', 743, 'ee76006171f1d967af49986eb4588ed426c5a0454ccd731d2fe9939eacd1ddb9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d873e3459858e915', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…The distance, d, is equal to the wall thickness, t______inus ______ plus one-half the bar diameter, db, [d = t - (1.25 + db / 2)].…” — what value is stated?', '["16 mm","50 mm","64 mm","32 mm"]', 3, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): The distance, d, is equal to the wall thickness, t, minus 1.25 inches (32 mm) plus one-half the bar diameter, db, [d = t - (1.25 + db / 2)].', 'study', 'GHBC-C-003729', 'GHBC-REQ-013826', 743, 'ee76006171f1d967af49986eb4588ed426c5a0454ccd731d2fe9939eacd1ddb9', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-6f43fad9f2f16d58', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.2): “…The reinforcement shall be placed within a tolerance of ± 3/______ where d is less than or equal to ______ or ± 1/______ where d is greater than ______.…” — what value is stated?', '["8 in","4 in","12 in","16 in"]', 0, 'Clause 18.7.1.6.2 (GHBC-C-003729, page 743): The reinforcement shall be placed within a tolerance of ± 3/8 inch (9.5 mm) where d is less than or equal to 203 mm (8 inches) or ± 1/2 inch (12.7 mm) where d is greater than 203 mm (8 inches).', 'study', 'GHBC-C-003729', 'GHBC-REQ-013827', 743, '777f0196e6572eafeaf50d081b8abdd5ffff1bc6db6186937177abfda6408897', 'requires_review', 0);
