INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5707cfd45b272b30', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.1.6.3): “…provided that the spacing of reinforcement does not exceed ______ and reinforcing bar sizes do not exceed No. 11.…” — what value is stated?', '["72 in","36 in","100 in","119 in"]', 0, 'Clause 18.7.1.6.3 (GHBC-C-003731, page 744): In lieu of the reinforcement provisions for masonry foundation walls in Table 18.7.1.6.3(2), 18.7.1.6.3(3) or 18.7.1.6.3(4), alternative reinforcing bar sizes and spacings having an equivalent cross-clauseal area of reinforcement per linear foot (mm) of wall shall be permitted to be used, provided that the spacing of reinforcement does not exceed 1829 mm (72 inches) and reinforcing bar sizes do no', 'study', 'GHBC-C-003731', 'GHBC-REQ-013911', 744, 'd5767f6d956922c7c2f44a1fa06772e7e0a08c4b580087d1efbee435d990a804', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b1976cb48fe0b83e', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.7.2.2): “…or F, the design of retaining walls supporting more than ______ of backfill height shall incorporate the additional seismic lateral earth pressure in accordance with the geotechnical investigation where required in……” — what value is stated?', '["1829 mm","914 mm","2743 mm","3658 mm"]', 0, 'Clause 18.7.2.2 (GHBC-C-003735, page 750): For structures assigned to Seismic Design Category D, E, or F, the design of retaining walls supporting more than 1829 mm (6 feet) of backfill height shall incorporate the additional seismic lateral earth pressure in accordance with the geotechnical investigation where required in Clause 18.3.2.', 'standard', 'GHBC-C-003735', 'GHBC-REQ-013928', 750, '81594f3b5bab18673d88c036f1e05a78567c9a0f56b30ec0368fa473952713bb', 'extracted', 1);
