INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e4369dd2dfc0aca3', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.3.2): “…of the load that produces a gross lateral movement of ______ at the lower of the top of foundation element and the ground surface, unless it can be shown that the predicted lateral movement shall cause neither harmful……” — what value is stated?', '["12.5 mm","38 mm","50 mm","25 mm"]', 3, 'Clause 18.10.3.3.2 (GHBC-C-003821, page 765): The resulting allowable load shall not be more than one-half of the load that produces a gross lateral movement of 25 mm (1 inch) at the lower of the top of foundation element and the ground surface, unless it can be shown that the predicted lateral movement shall cause neither harmful distortion of, nor instability in, the structure, nor cause any element to be loaded beyond its capacity.', 'study', 'GHBC-C-003821', 'GHBC-REQ-014278', 765, 'bfdb43e9f46dfe65fcf92deda8e015a71f5b5c7c1fb6ad8ef95931cd7b512fba', 'requires_review', 0);
