INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a73f3aed4c9c86d3', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.5.3.4): “…C, D, E or F shall have a wall thickness of not less than ______.…” — what value is stated?', '["16 in","8 in","24 in","32 in"]', 0, 'Clause 18.10.3.5.3.4 (GHBC-C-003832, page 767): Concrete-filled steel pipes or tubes in structures assigned to Seismic Design Category C, D, E or F shall have a wall thickness of not less than 5 mm (3/16 inch).', 'standard', 'GHBC-C-003832', 'GHBC-REQ-014316', 767, '547d84e689805526dec859feccacb936ec85d42bfdc9d6b229ce6d13ee0020ac', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5f5d4da48e3ba84f', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.5.3.4): “…shall have a nominal outside diameter of not less than ______, a wall thickness of not less than ______ and a suitable steel driving shoe welded to the bottom; the diameter of the rock socket shall be approximately……” — what value is stated?', '["686 mm","914 mm","457 mm","229 mm"]', 2, 'Clause 18.10.3.5.3.4 (GHBC-C-003832, page 767): The pipe or tube casing for socketed drilled shafts shall have a nominal outside diameter of not less than 457 mm (18 inches), a wall thickness of not less than 9.5 mm (3/8 inch) and a suitable steel driving shoe welded to the bottom; the diameter of the rock socket shall be approximately equal to the inside diameter of the casing.', 'standard', 'GHBC-C-003832', 'GHBC-REQ-014317', 767, '53c5d0e9f48ff267f4fb0e0f6993a6bd959af9c08eb751646d25e11b1bf2576f', 'extracted', 1);
