INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-b53875126a8f0a52', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…Effective prestress shall be based on an assumed loss of ______Pa (30,000 psi) in the prestressing steel.…” — what value is stated?', '["100 m","310 m","414 m","207 m"]', 3, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): Effective prestress shall be based on an assumed loss of 207 MPa (30,000 psi) in the prestressing steel.', 'standard', 'GHBC-C-003842', 'GHBC-REQ-014367', 769, 'd106e5e3d374deb050b2e9cbe749113a3b2647371ac7ab3d41fd7e03f78f0fd3', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-034a42bf99e0a7a7', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…the amount required by the following formula for the upper ______ of the pile.…” — what value is stated?', '["3048 mm","9144 mm","10000 mm","6096 mm"]', 3, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): The volumetric ratio of spiral reinforcement shall not be less than the amount required by the following formula for the upper 6096 mm (20 feet) of the pile.', 'study', 'GHBC-C-003842', 'GHBC-REQ-014371', 769, '6dc1285f9e0b7f33e581ddbf634a609934688430c09dc3dcf27cc0b9334f154d', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-411d81bef0419697', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…the amount required by the following formula for the upper ______ of the pile.…” — what value is stated?', '["30 feet","40 feet","20 feet","10 feet"]', 2, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): The volumetric ratio of spiral reinforcement shall not be less than the amount required by the following formula for the upper 6096 mm (20 feet) of the pile.', 'study', 'GHBC-C-003842', 'GHBC-REQ-014371', 769, '6dc1285f9e0b7f33e581ddbf634a609934688430c09dc3dcf27cc0b9334f154d', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e62e2b49fa117166', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…= Yield strength of spiral reinforcement £ yh 85,000 psi (______Pa).…” — what value is stated?', '["900 m","1000 m","586 m","300 m"]', 2, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): = Yield strength of spiral reinforcement £ yh 85,000 psi (586 MPa).', 'standard', 'GHBC-C-003842', 'GHBC-REQ-014376', 769, '92d324e16e87c89f9101758259aaf7b8e9397305af89ee8568838d0f876a39e2', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9046c96b003c7c28', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…by Equation 18-5 shall be provided below the upper ______ of the pile.…” — what value is stated?', '["3048 mm","9144 mm","10000 mm","6096 mm"]', 3, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): Not less than one-half the volumetric ratio required by Equation 18-5 shall be provided below the upper 6096 mm (20 feet) of the pile.', 'standard', 'GHBC-C-003842', 'GHBC-REQ-014379', 769, '6a8de955eabcb8fecd14277f5d7fdcc4254fb552ebe4b11fd6ee9e56e38450ea', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a51913cd2822898c', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.3.8.3.1): “…by Equation 18-5 shall be provided below the upper ______ of the pile.…” — what value is stated?', '["10 feet","30 feet","40 feet","20 feet"]', 3, 'Clause 18.10.3.8.3.1 (GHBC-C-003842, page 769): Not less than one-half the volumetric ratio required by Equation 18-5 shall be provided below the upper 6096 mm (20 feet) of the pile.', 'standard', 'GHBC-C-003842', 'GHBC-REQ-014379', 769, '6a8de955eabcb8fecd14277f5d7fdcc4254fb552ebe4b11fd6ee9e56e38450ea', 'extracted', 1);
