INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a4b301fa6ab7494a', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.4.8): “…withdrawn at a steady rate or in increments not to exceed ______, concreting or grouting pumping pressures shall be measured and maintained high enough at all times to offset hydrostatic and lateral earth pressures.…” — what value is stated?', '["457 mm","610 mm","305 mm","152.4 mm"]', 2, 'Clause 18.10.4.8 (GHBC-C-003875, page 777): As the auger is withdrawn at a steady rate or in increments not to exceed 305 mm (1 foot), concreting or grouting pumping pressures shall be measured and maintained high enough at all times to offset hydrostatic and lateral earth pressures.', 'standard', 'GHBC-C-003875', 'GHBC-REQ-014605', 777, '5d72542196976320ab1360ac2594871a063c58795331454746d31c79104ed0b9', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-a815eabdb72b908b', NULL, NULL, 'threshold', 18, 'GS 1207:2018 Part 18 (Clause 18.10.4.8): “…pressure occurs, the element shall be redrilled to ______ below the elevation of the tip of the auger when the installation was interrupted or concrete or grout pressure was lost and reformed.…” — what value is stated?', '["3048 mm","1524 mm","762 mm","2286 mm"]', 1, 'Clause 18.10.4.8 (GHBC-C-003875, page 777): Where the installation process of any element is interrupted or a loss of concreting or grouting pressure occurs, the element shall be redrilled to 1524 mm (5 feet) below the elevation of the tip of the auger when the installation was interrupted or concrete or grout pressure was lost and reformed.', 'standard', 'GHBC-C-003875', 'GHBC-REQ-014607', 777, 'f8f96be061af149317cea3ba193dd8ebec74ef0b5b3d13fab582f294a0e443ce', 'extracted', 1);
