INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-78ef3fd7607347a6', NULL, NULL, 'threshold', 19, 'GS 1207:2018 Part 19 (Clause 19.5.3): “…f ‘c, not more than 2,500 pounds per square inch (psi) (______Pa), regardless of the compressive strength specified in the approved construction documents or used in the footing construction.…” — what value is stated?', '["25 m","35 m","17.2 m","8.6 m"]', 2, 'Clause 19.5.3 (GHBC-C-003922, page 786): The structural design of the footing is based on a specified compressive strength, f ‘c, not more than 2,500 pounds per square inch (psi) (17.2 MPa), regardless of the compressive strength specified in the approved construction documents or used in the footing construction.', 'standard', 'GHBC-C-003922', 'GHBC-REQ-014791', 786, '99a8ef106559fcf66a462c43d8a55bf633826cde94365ce2e405d47743382507', 'extracted', 1);
