INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8d2224cc4ff74f43', NULL, NULL, 'threshold', 19, 'GS 1207:2018 Part 19 (Clause 19.5.5.2): “…For wood trusses with a clear span of 18 ______ or greater, the special inspector shall verify during construction that the temporary installation restraint/bracing is installed in accordance with the approved truss……” — what value is stated?', '["288 mm","144 mm","440 mm","576 mm"]', 0, 'Clause 19.5.5.2 (GHBC-C-003930, page 788): For wood trusses with a clear span of 18 288 mm (60 feet) or greater, the special inspector shall verify during construction that the temporary installation restraint/bracing is installed in accordance with the approved truss Submission package.', 'study', 'GHBC-C-003930', 'GHBC-REQ-014824', 788, 'ccaf569158a146fd1c243effb278476f869b07a8892cc9b860a583254575bfad', 'requires_review', 0);
