INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c82267c7363c7f92', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.3): “…Coarse aggregate shall have a ______ Fines test result of not less than 160 kN and the Wet/Dry ratio shall be at least ______.…” — what value is stated?', '["95 %","90 %","75 %","40 %"]', 2, 'Clause 20.2.3 (GHBC-C-004000, page 802): Coarse aggregate shall have a 10% Fines test result of not less than 160 kN and the Wet/Dry ratio shall be at least 75%.', 'standard', 'GHBC-C-004000', 'GHBC-REQ-015117', 802, '685548a1f969c9cc618ace6b398f9ecf8de25847c37a9aafbabc3c06fb6525b3', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-49096505cc00d57b', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.3): “…(LAA) value of the coarse aggregate shall not be more than ______.…” — what value is stated?', '["20 %","60 %","80 %","40 %"]', 3, 'Clause 20.2.3 (GHBC-C-004000, page 802): The Los Angeles Abrasion (LAA) value of the coarse aggregate shall not be more than 40%.', 'study', 'GHBC-C-004000', 'GHBC-REQ-015118', 802, '6a76cc2ec73f9e3296cccd53e181a1bbc4264315c6f5511b4aa16441b436c0fb', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-567c2459d8079bc6', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.3): “…shrinkage of coarse aggregate shall not be greater than ______ when tested to BS EN 1367–4.…” — what value is stated?', '["0.2 %","0.075 %","0.03 %","0.05 %"]', 1, 'Clause 20.2.3 (GHBC-C-004000, page 802): The drying shrinkage of coarse aggregate shall not be greater than 0.075% when tested to BS EN 1367–4.', 'study', 'GHBC-C-004000', 'GHBC-REQ-015122', 802, '72c4ab7f3906cb711573ac6ee1256ebcad01267a24748096e84f563d6622663a', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4f9612f54e789394', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.3): “…aggregate shall not have a water absorption of more than ______ when tested according to ASTM C 127.…” — what value is stated?', '["5 %","2.5 %","1 %","4 %"]', 1, 'Clause 20.2.3 (GHBC-C-004000, page 802): The aggregate shall not have a water absorption of more than 2.5% when tested according to ASTM C 127.', 'study', 'GHBC-C-004000', 'GHBC-REQ-015123', 802, '61dfa21fbcd31f6b1021e4b467b79dbd5333580a876126cb77e8a480ffcb2763', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ffe4cae66888044d', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.4): “…the chloride content of the mixing water shall not exceed ______g/ℓ.…” — what value is stated?', '["250 m","701 m","1000 m","500 m"]', 3, 'Clause 20.2.4 (GHBC-C-004001, page 803): For reinforced and prestressed concrete the chloride content of the mixing water shall not exceed 500 mg/ℓ.', 'study', 'GHBC-C-004001', 'GHBC-REQ-015126', 803, '225f857338e84c33f9eee88ead95adf96c47b1bb13dfa6ee8faf917a331ad291', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ad1e70889c29c227', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.5): “…dispensing the admixture in quantities accurate to within ______ of the required quantity.…” — what value is stated?', '["10 %","5 %","2.5 %","7.5 %"]', 1, 'Clause 20.2.5 (GHBC-C-004002, page 803): Admixtures shall be used only in liquid form and shall be batched in solution in the mixing water by a mechanical batcher that is capable of dispensing the admixture in quantities accurate to within 5% of the required quantity.', 'standard', 'GHBC-C-004002', 'GHBC-REQ-015130', 803, '761ee2b53feb894416e3ec44a5eef9a9e9695b10d182595a2cc7d04148bbb817', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3a94dc343d664677', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.2.5): “…The chloride ion content of any admixture shall not exceed ______ by mass of the admixture nor ______ by mass of the cement in the mix.…” — what value is stated?', '["3 %","4 %","2 %","1 %"]', 2, 'Clause 20.2.5 (GHBC-C-004002, page 803): The chloride ion content of any admixture shall not exceed 2% by mass of the admixture nor 0.03% by mass of the cement in the mix.', 'study', 'GHBC-C-004002', 'GHBC-REQ-015132', 803, '905a24fc76215b364dc0cc064b86eaf588866bc23f72aa182c181d6802b7d400', 'requires_review', 0);
