INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f23b843fe021ad57', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.1): “…(ii) For any other reinforced concrete: ______ in ______ of all test results provided no result is more than ______.…” — what value is stated?', '["0.075 %","0.25 %","0.4 %","0.2 %"]', 3, 'Clause 20.4.1 (GHBC-C-004007, page 805): (ii) For any other reinforced concrete: 0.2% in 95% of all test results provided no result is more than 0.4%.', 'standard', 'GHBC-C-004007', 'GHBC-REQ-015176', 805, '75b91e9c0efc5680d14bc58bb1434a0b274ff172afd74a233ffb8fb10b429788', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f23b843fe021ad57', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.1): “…(ii) For any other reinforced concrete: ______ in ______ of all test results provided no result is more than ______.…” — what value is stated?', '["50 %","80 %","75 %","95 %"]', 3, 'Clause 20.4.1 (GHBC-C-004007, page 805): (ii) For any other reinforced concrete: 0.2% in 95% of all test results provided no result is more than 0.4%.', 'standard', 'GHBC-C-004007', 'GHBC-REQ-015176', 805, '75b91e9c0efc5680d14bc58bb1434a0b274ff172afd74a233ffb8fb10b429788', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f23b843fe021ad57', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.1): “…(ii) For any other reinforced concrete: ______ in ______ of all test results provided no result is more than ______.…” — what value is stated?', '["0.2 %","0.25 %","1 %","0.4 %"]', 3, 'Clause 20.4.1 (GHBC-C-004007, page 805): (ii) For any other reinforced concrete: 0.2% in 95% of all test results provided no result is more than 0.4%.', 'standard', 'GHBC-C-004007', 'GHBC-REQ-015176', 805, '75b91e9c0efc5680d14bc58bb1434a0b274ff172afd74a233ffb8fb10b429788', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bd18896e57474cdf', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.1): “…including cement, water and admixtures shall not exceed ______ by mass of the aggregate or ______ of the mass of cement in the mix, whichever is the lesser.…” — what value is stated?', '["0.4 %","0.2 %","0.25 %","1 %"]', 0, 'Clause 20.4.1 (GHBC-C-004007, page 805): The total sulfate content expressed as SO3 of all the ingredients in a mix including cement, water and admixtures shall not exceed 0.4% by mass of the aggregate or 4.0% of the mass of cement in the mix, whichever is the lesser.', 'study', 'GHBC-C-004007', 'GHBC-REQ-015177', 805, '55d8cdf669d9e64660514c8e446461d9558c1f5241c29125bd6993dfefb8d290', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-bd18896e57474cdf', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.1): “…including cement, water and admixtures shall not exceed ______ by mass of the aggregate or ______ of the mass of cement in the mix, whichever is the lesser.…” — what value is stated?', '["4 %","2 %","5 %","7.5 %"]', 0, 'Clause 20.4.1 (GHBC-C-004007, page 805): The total sulfate content expressed as SO3 of all the ingredients in a mix including cement, water and admixtures shall not exceed 0.4% by mass of the aggregate or 4.0% of the mass of cement in the mix, whichever is the lesser.', 'study', 'GHBC-C-004007', 'GHBC-REQ-015177', 805, '55d8cdf669d9e64660514c8e446461d9558c1f5241c29125bd6993dfefb8d290', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7357e4e7c59fbd29', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…compressive strength is determined on specimens tested at ______.…” — what value is stated?', '["90 days","28 days","14 days","10 days"]', 1, 'Clause 20.4.2 (GHBC-C-004008, page 805): Unless specified otherwise in the Special Specification, the compressive strength is determined on specimens tested at 28 days.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015192', 805, '1db6f3a57d00ebe00215e62f3c2574b43b62b0157a7d34166fe4fded11bc7b68', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-74f6053ffe3ccc95', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…the compressive strength at ages earlier or later than ______ or after storage under special conditions (e.g. heat treatment).…” — what value is stated?', '["90 days","28 days","14 days","10 days"]', 1, 'Clause 20.4.2 (GHBC-C-004008, page 805): For particular uses, it may be necessary to specify the compressive strength at ages earlier or later than 28 days (e.g. for massive structural elements) or after storage under special conditions (e.g. heat treatment).', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015193', 805, '4c71351ef6de4017791dc2e7a9dbb6c27b459575eaf1c823915037a833243ef6', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-f7e023f0c68614c1', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…graded from the nominal maximum size of stone down to the ______icron size.…” — what value is stated?', '["250 m","125 m","63 m","180 m"]', 1, 'Clause 20.4.2 (GHBC-C-004008, page 805): (i) The aggregate portion shall be well graded from the nominal maximum size of stone down to the 125 micron size.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015195', 805, '3934ddc68e4ad51c24348aa6c009854e71e8755e302d9a62ab84bcc06e451e58', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d08886c9ff2ab0a4', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete having a maximum aggregate size of ______ or less, ______ cubes or 150 diameter by ______ high cylinders shall be used.…” — what value is stated?', '["60 mm","82.6 mm","40 mm","20 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete having a maximum aggregate size of 40 mm or less, 150 mm cubes or 150 diameter by 300 mm high cylinders shall be used.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015206', 805, '06d6357fecd574124f0b41ef50d2f2682c21bc4cbaa8ad3a11d8efe107226f5c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d08886c9ff2ab0a4', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete having a maximum aggregate size of ______ or less, ______ cubes or 150 diameter by ______ high cylinders shall be used.…” — what value is stated?', '["225 mm","300 mm","150 mm","75 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete having a maximum aggregate size of 40 mm or less, 150 mm cubes or 150 diameter by 300 mm high cylinders shall be used.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015206', 805, '06d6357fecd574124f0b41ef50d2f2682c21bc4cbaa8ad3a11d8efe107226f5c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d08886c9ff2ab0a4', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete having a maximum aggregate size of ______ or less, ______ cubes or 150 diameter by ______ high cylinders shall be used.…” — what value is stated?', '["450 mm","600 mm","300 mm","150 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete having a maximum aggregate size of 40 mm or less, 150 mm cubes or 150 diameter by 300 mm high cylinders shall be used.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015206', 805, '06d6357fecd574124f0b41ef50d2f2682c21bc4cbaa8ad3a11d8efe107226f5c', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3f5303274e35af0c', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete containing ______ or larger aggregate, ______ cubes shall be used and aggregates larger than ______ shall be removed from the mixed concrete before casting the cubes.…” — what value is stated?', '["114 mm","150 mm","75 mm","38 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete containing 75 mm or larger aggregate, 200 mm cubes shall be used and aggregates larger than 63 mm shall be removed from the mixed concrete before casting the cubes.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015207', 805, '5a9f843af0966268b7b30a1fa836bfbab98ec9ae12edd8670e696ff3afdd688e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3f5303274e35af0c', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete containing ______ or larger aggregate, ______ cubes shall be used and aggregates larger than ______ shall be removed from the mixed concrete before casting the cubes.…” — what value is stated?', '["300 mm","400 mm","200 mm","100 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete containing 75 mm or larger aggregate, 200 mm cubes shall be used and aggregates larger than 63 mm shall be removed from the mixed concrete before casting the cubes.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015207', 805, '5a9f843af0966268b7b30a1fa836bfbab98ec9ae12edd8670e696ff3afdd688e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-3f5303274e35af0c', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…In the case of concrete containing ______ or larger aggregate, ______ cubes shall be used and aggregates larger than ______ shall be removed from the mixed concrete before casting the cubes.…” — what value is stated?', '["92 mm","127 mm","63 mm","32 mm"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): In the case of concrete containing 75 mm or larger aggregate, 200 mm cubes shall be used and aggregates larger than 63 mm shall be removed from the mixed concrete before casting the cubes.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015207', 805, '5a9f843af0966268b7b30a1fa836bfbab98ec9ae12edd8670e696ff3afdd688e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-0bdf155940d275b2', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.2): “…strength at seven days and the remaining three at ______.…” — what value is stated?', '["10 days","90 days","28 days","14 days"]', 2, 'Clause 20.4.2 (GHBC-C-004008, page 805): (iv) Three samples from each batch shall be tested for compressive strength at seven days and the remaining three at 28 days.', 'standard', 'GHBC-C-004008', 'GHBC-REQ-015209', 805, '3415456ad8943da14faa90c1a13062eedfd56eedc0d85f590dfd5b6fdcb16e14', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8b2116aaca793643', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.5): “…i. slump between ______ and ______; ii.…” — what value is stated?', '["20 mm","10 mm","5 mm","15 mm"]', 1, 'Clause 20.4.5 (GHBC-C-004010, page 807): i. slump between 10 mm and 210 mm; ii.', 'standard', 'GHBC-C-004010', 'GHBC-REQ-015224', 807, 'aed76ca4d802cacad7acbdf6bbf1138d0fc34d486adfdd522053dda07ce099e8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8b2116aaca793643', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.5): “…i. slump between ______ and ______; ii.…” — what value is stated?', '["419 mm","210 mm","102 mm","323 mm"]', 1, 'Clause 20.4.5 (GHBC-C-004010, page 807): i. slump between 10 mm and 210 mm; ii.', 'standard', 'GHBC-C-004010', 'GHBC-REQ-015224', 807, 'aed76ca4d802cacad7acbdf6bbf1138d0fc34d486adfdd522053dda07ce099e8', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1150d3e54f273223', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.5): “…between 1.04 and 1.46; iv. flow diameter between ______ and ______.…” — what value is stated?', '["340 mm","171 mm","508 mm","685 mm"]', 0, 'Clause 20.4.5 (GHBC-C-004010, page 807): Vebe time between 30 and  5 seconds; iii. degree of compactability between 1.04 and 1.46; iv. flow diameter between  340 mm and 620 mm.', 'study', 'GHBC-C-004010', 'GHBC-REQ-015225', 807, 'cd2de35a67a7b9951abf2e3a0f0403cc560278836208079c9a826c3d0d217d35', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1150d3e54f273223', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.5): “…between 1.04 and 1.46; iv. flow diameter between ______ and ______.…” — what value is stated?', '["620 mm","306 mm","915 mm","1230 mm"]', 0, 'Clause 20.4.5 (GHBC-C-004010, page 807): Vebe time between 30 and  5 seconds; iii. degree of compactability between 1.04 and 1.46; iv. flow diameter between  340 mm and 620 mm.', 'study', 'GHBC-C-004010', 'GHBC-REQ-015225', 807, 'cd2de35a67a7b9951abf2e3a0f0403cc560278836208079c9a826c3d0d217d35', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-dd2f589f867bbfdd', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.4.5): “…Agent shall produce concrete with a target slump of ______.…” — what value is stated?', '["114 mm","150 mm","75 mm","38 mm"]', 2, 'Clause 20.4.5 (GHBC-C-004010, page 807): If no specific target value is specified the Owner or Owner‘s Authorised Agent shall produce concrete with a target slump of 75 mm.', 'standard', 'GHBC-C-004010', 'GHBC-REQ-015231', 807, '01ca3ffc6246e65075d144d3476b7557c1fda048a5fc97bf1a67b3576cb7398f', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c9991e44071ddf61', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.6.1): “…employed shall be within a tolerance of plus or minus ______ of the respective masses per batch approved by the Head of works.…” — what value is stated?', '["4 %","2 %","1 %","3 %"]', 1, 'Clause 20.6.1 (GHBC-C-004014, page 809): The masses of cement and of each size of aggregate as indicated by the mechanisms employed shall be within a tolerance of plus or minus 2% of the respective masses per batch approved by the Head of works.', 'standard', 'GHBC-C-004014', 'GHBC-REQ-015243', 809, 'e7fac27ef397ba4bcb83e0f3ae3bc54fbb0139c98c483fb63b6b3baa931ac57d', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-096c0bb544231ef6', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.6.2): “…used bags shall be batched by mass, accurate to within ______ of the required mass.…” — what value is stated?', '["4 %","2 %","1 %","3 %"]', 1, 'Clause 20.6.2 (GHBC-C-004015, page 809): All cement taken from bulk containers or partly used bags shall be batched by mass, accurate to within 2% of the required mass.', 'standard', 'GHBC-C-004015', 'GHBC-REQ-015249', 809, '54a3d262d8f26ce9e6675f993fe59e502fc721066b489f68dcabd398f1016fd4', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c056acbc11f4475f', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.6.3): “…shall be measured either by mass or by volume, accurate to ______ of the required quantity.…” — what value is stated?', '["3 %","4 %","2 %","1 %"]', 2, 'Clause 20.6.3 (GHBC-C-004016, page 809): The mixing water for each batch shall be measured either by mass or by volume, accurate to 2% of the required quantity.', 'standard', 'GHBC-C-004016', 'GHBC-REQ-015252', 809, 'ed83cc94fbc83db9096c5709ca04d019912e3c80e7013c710e021bfe573ff68e', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cb2bf67833ddff2a', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.6.4): “…concrete shall be measured separately by mass, accurate to ______ of the required mass.…” — what value is stated?', '["1 %","3 %","4 %","2 %"]', 3, 'Clause 20.6.4 (GHBC-C-004017, page 809): All aggregate for strength concrete shall be measured separately by mass, accurate to 2% of the required mass.', 'standard', 'GHBC-C-004017', 'GHBC-REQ-015254', 809, '6cc2bea879209289007373447839fe245ec08bb08866ffe6e27c75459063141a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-ea9f4e89c6c39bf4', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.7.3): “…Mixers that have been out of use for more than ______inutes shall be thoroughly cleaned before any fresh concrete is mixed and thereafter the first batch of concrete through the mixers shall contain only half the normal……” — what value is stated?', '["30 m","15 m","45 m","60 m"]', 0, 'Clause 20.7.3 (GHBC-C-004020, page 810): Mixers that have been out of use for more than 30 minutes shall be thoroughly cleaned before any fresh concrete is mixed and thereafter the first batch of concrete through the mixers shall contain only half the normal quantity of coarse aggregate.', 'standard', 'GHBC-C-004020', 'GHBC-REQ-015278', 810, 'eb98a9b215c245b52f65ecc4d33cd4b6615ea0a4e5ba1fbb4c6a84ca139e6686', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-c92802caa68a3953', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.7.4): “…If the mixer has stopped running for a period in excess of ______inutes, it shall be thoroughly cleaned out.…” — what value is stated?', '["45 m","60 m","30 m","15 m"]', 2, 'Clause 20.7.4 (GHBC-C-004021, page 810): If the mixer has stopped running for a period in excess of 30 minutes, it shall be thoroughly cleaned out.', 'standard', 'GHBC-C-004021', 'GHBC-REQ-015282', 810, '6cc653607c676c7e5c0bfd535e8e581f255ef5c9a89e10f1b25dec9fce9a2f81', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-fad9c29cc693add9', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.7.5): “…a standby mixer shall be held in readiness to run on ______inutes notice should the stock mixer break down.…” — what value is stated?', '["22.7 m","30 m","15 m","7.5 m"]', 2, 'Clause 20.7.5 (GHBC-C-004022, page 810): When clauses are cast where it is important for the casting to continue without interruption, a standby mixer shall be held in readiness to run on 15 minutes notice should the stock mixer break down.', 'standard', 'GHBC-C-004022', 'GHBC-REQ-015284', 810, 'eb3ffd4edb8db9498566de93d6b9fdc8c9e46729b15f9889544981c1a967efab', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-4da3a853fa8c4d7a', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.7.7): “…the specified quantities of cement shall be increased by ______ and not more than ______3 shall be mixed at one time.…” — what value is stated?', '["5 %","15 %","20 %","10 %"]', 3, 'Clause 20.7.7 (GHBC-C-004024, page 811): For hand mixed concrete the specified quantities of cement shall be increased by 10% and not more than 0.5 m3 shall be mixed at one time.', 'standard', 'GHBC-C-004024', 'GHBC-REQ-015293', 811, 'a3189b2e64329bf39644baaf2c4413edd108a6c61097842fa9036f267a202d48', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-797dd42c4fa7db3c', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause null): “…discharge from the mixer and placing shall not exceed ______.…” — what value is stated?', '["38 mm","50 mm","25 mm","12.5 mm"]', 2, 'Clause null (GHBC-C-004025, page 811): The loss of slump between discharge from the mixer and placing shall not exceed 25 mm.', 'study', 'GHBC-C-004025', 'GHBC-REQ-015296', 811, 'e323a12ec02848a948eee10d0c02ba9fc83379d92fd3560eeecff0fad669c150', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-73db13ca05105112', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.2): “…Concrete shall be placed within ______inutes of mixing.…” — what value is stated?', '["120 m","60 m","30 m","90 m"]', 1, 'Clause 20.9.2 (GHBC-C-004027, page 811): Concrete shall be placed within 60 minutes of mixing.', 'standard', 'GHBC-C-004027', 'GHBC-REQ-015307', 811, '5d22fb341fb60b696d450298048277ddbc027447d14dba9c0b91b58777bbf789', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cd93ce0535d6d6a8', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.3): “…The joints of the material between strips shall have a ______ overlap, and the lining shall be held firmly in position by nails, pegs, etc. Polyethylene sheeting shall have a minimum thickness of…” — what value is stated?', '["300 mm","150 mm","75 mm","225 mm"]', 1, 'Clause 20.9.3 (GHBC-C-004028, page 811): The joints of the material between strips shall have a 150 mm overlap, and the lining shall be held firmly in position by nails, pegs, etc. Polyethylene sheeting shall have a minimum thickness of', 'standard', 'GHBC-C-004028', 'GHBC-REQ-015311', 811, '460ed73156ffa1fabdbe129e8ca9ac21f2c78eab2be34f9c5b436d4fa44aedeb', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-26c2ed1ff2dad186', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.3): “…______, and waterproof paper shall comply with BS 1521 Waterproof Building Paper, Class B, and shall have fibrous reinforcement.…” — what value is stated?', '["0.102 mm","0.25 mm","0.3 mm","0.15 mm"]', 3, 'Clause 20.9.3 (GHBC-C-004028, page 811): 0.15 mm, and waterproof paper shall comply with BS 1521 Waterproof Building Paper, Class B, and shall have fibrous reinforcement.', 'standard', 'GHBC-C-004028', 'GHBC-REQ-015312', 811, 'f37db2a4328e6f2cb3846e3447b5b91b4b8695cec0e83411981829683abb3fe6', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-e074a8bd00fa78e6', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.3): “…of the excavated surface and it shall be not less than ______ thick.…” — what value is stated?', '["10 mm","5 mm","2.5 mm","7.6 mm"]', 1, 'Clause 20.9.3 (GHBC-C-004028, page 811): The mortar shall be kept ahead of the concrete, it shall be well worked into all parts of the excavated surface and it shall be not less than 5 mm thick.', 'standard', 'GHBC-C-004028', 'GHBC-REQ-015317', 811, 'ce9fd629dc43498d8a6e8b0f5bc98eebf976b5d07f410687e8a115a234b5fc85', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8a3c091709257f30', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.4): “…to the construction joint planes and between 200 and ______ thick unless otherwise permitted or directed by the Head of works.…” — what value is stated?', '["1000 mm","500 mm","250 mm","750 mm"]', 1, 'Clause 20.9.4 (GHBC-C-004029, page 812): In vertical elements such as walls or columns, concrete shall be brought up in layers of approximately uniform thicknesses parallel to the construction joint planes and between 200 and 500 mm thick unless otherwise permitted or directed by the Head of works.', 'standard', 'GHBC-C-004029', 'GHBC-REQ-015330', 812, '38369e861ff5514be1db66bd7efda9a1aab2184d9ce9d89d3ed8f4475c02122a', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-5ba9973386e6be55', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.4): “…against concrete that has been in position for more than ______inutes, unless a construction joint is formed.…” — what value is stated?', '["30 m","15 m","45 m","60 m"]', 0, 'Clause 20.9.4 (GHBC-C-004029, page 812): Fresh concrete shall not be placed against concrete that has been in position for more than 30 minutes, unless a construction joint is formed.', 'study', 'GHBC-C-004029', 'GHBC-REQ-015333', 812, '308b5e7e5422bef313b7a293f67699a9507390f127b24dec8e6bf0c149fc4d46', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-105773affef9267c', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.6): “…If it becomes possible to resume concrete placing within ______inutes of the stoppage and the Head of works consents to a resumption, the new concrete shall be thoroughly worked in and compacted against the surface of……” — what value is stated?', '["15 m","45 m","60 m","30 m"]', 3, 'Clause 20.9.6 (GHBC-C-004031, page 813): If it becomes possible to resume concrete placing within 30 minutes of the stoppage and the Head of works consents to a resumption, the new concrete shall be thoroughly worked in and compacted against the surface of the existing concrete so as to avoid any cold joints.', 'standard', 'GHBC-C-004031', 'GHBC-REQ-015361', 813, 'ea634ace4f1fc7201fda4684b06ea7e41c2bc97ba804b6a943366396db188d08', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-7e5be6ea06458cba', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.9.7): “…by the Head of works, pours shall not be more than ______ high and shall as far as possible have a uniform thickness over the plan area of the pour.…” — what value is stated?', '["2 m","1 m","3 m","4 m"]', 0, 'Clause 20.9.7 (GHBC-C-004032, page 813): Unless otherwise approved by the Head of works, pours shall not be more than 2.0 m high and shall as far as possible have a uniform thickness over the plan area of the pour.', 'study', 'GHBC-C-004032', 'GHBC-REQ-015362', 813, '08228395a0d9680c67dff1c711b55080965a7a829487fbd216d1526f24f89346', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-873d023ffd2ff565', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause null): “…the concrete contains aggregate with a nominal size of ______ or more, vibrators with a diameter of ______ or more shall be used.…” — what value is stated?', '["127 mm","63 mm","32 mm","92 mm"]', 1, 'Clause null (GHBC-C-004033, page 814): Where the concrete contains aggregate with a nominal size of 63 mm or more, vibrators with a diameter of 100 mm or more shall be used.', 'standard', 'GHBC-C-004033', 'GHBC-REQ-015372', 814, '8a61f952b6276ff65a3412dc3b0240e975c503d95cd2aa6a4393e226d3ce5a51', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-873d023ffd2ff565', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause null): “…the concrete contains aggregate with a nominal size of ______ or more, vibrators with a diameter of ______ or more shall be used.…” — what value is stated?', '["200 mm","100 mm","50 mm","150 mm"]', 1, 'Clause null (GHBC-C-004033, page 814): Where the concrete contains aggregate with a nominal size of 63 mm or more, vibrators with a diameter of 100 mm or more shall be used.', 'standard', 'GHBC-C-004033', 'GHBC-REQ-015372', 814, '8a61f952b6276ff65a3412dc3b0240e975c503d95cd2aa6a4393e226d3ce5a51', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-2824bdc166b5a576', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.11.1): “…Curing shall be continued for at least ______ for concrete made with CEM I cement and for at least ______ for concrete made with CEM II and CEM III cement, or until the concrete is covered by later construction,……” — what value is stated?', '["14 days","7 days","2 days","10 days"]', 1, 'Clause 20.11.1 (GHBC-C-004034, page 814): Curing shall be continued for at least 7 days for concrete made with CEM I cement and for at least 10 days for concrete made with CEM II and CEM III cement, or until the concrete is covered by later construction, whichever is the shorter period.', 'standard', 'GHBC-C-004034', 'GHBC-REQ-015380', 814, 'a834c2cd04891017c3086dbe3fd55044d8464f53451d7127f392117641ecbe3e', 'extracted', 1);
