INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-21615fe5ab962646', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.11.2): “…a curing compound having an efficiency index of at least ______.…” — what value is stated?', '["75 %","90 %","50 %","80 %"]', 1, 'Clause 20.11.2 (GHBC-C-004035, page 814): (v) If use of the foregoing methods is inappropriate, surfaces that will not have further concrete bonded to them and which are not to receive an application of a finish may be cured by the application of a curing compound having an efficiency index of at least 90%.', 'standard', 'GHBC-C-004035', 'GHBC-REQ-015394', 814, 'fa7ff732f29ae7763877de1734bd65b12d407c4d4d45869cad87e4f4b5ee29ff', 'extracted', 1);
