INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-1aaf3433c6aae245', NULL, NULL, 'threshold', 20, 'GS 1207:2018 Part 20 (Clause 20.11.3): “…shall have an insulation value at least equivalent to ______ of dry mineral wool; (iv) leaving formwork in place during the curing period.…” — what value is stated?', '["100 mm","50 mm","25 mm","75 mm"]', 1, 'Clause 20.11.3 (GHBC-C-004036, page 815): Such blankets shall have an insulation value at least equivalent to 50 mm of dry mineral wool; (iv) leaving formwork in place during the curing period.', 'standard', 'GHBC-C-004036', 'GHBC-REQ-015401', 815, '03f089d020ca35249db8b3fab7ef7a97560a5e6c80ad79937980978ac8706a3f', 'extracted', 1);
