INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-8b81eed1c905cc99', NULL, NULL, 'threshold', 22, 'GS 1207:2018 Part 22 (Clause 22.12.3): “…floor of a masonry heater shall be a minimum thickness of ______ of noncombustible material and be supported on a noncombustible footing and foundation in accordance with Clause 22.13.2.…” — what value is stated?', '["2 in","6 in","8 in","4 in"]', 3, 'Clause 22.12.3 (GHBC-C-004155, page 833): The firebox floor of a masonry heater shall be a minimum thickness of 102 mm (4 inches) of noncombustible material and be supported on a noncombustible footing and foundation in accordance with Clause 22.13.2.', 'standard', 'GHBC-C-004155', 'GHBC-REQ-015807', 833, '3b09c553e6f982644e125af8f98aa5f0116cfd85cb2d6b8896774537cb81cf46', 'extracted', 1);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-d102e0c851b47546', NULL, NULL, 'threshold', 22, 'GS 1207:2018 Part 22 (Clause 22.12.5): “…Combustible materials shall not be placed within ______ or the distance of the allowed reduction method from the outside surface of a masonry heater in accordance with the Ghana fire Code, Clause 12.6, and the required……” — what value is stated?', '["1829 mm","914 mm","457 mm","1372 mm"]', 1, 'Clause 22.12.5 (GHBC-C-004157, page 833): Combustible materials shall not be placed within 914 mm (36 inches) or the distance of the allowed reduction method from the outside surface of a masonry heater in accordance with the Ghana fire Code, Clause 12.6, and the required space between the heater and combustible material shall be fully vented to permit the free flow of air around all heater surfaces.', 'study', 'GHBC-C-004157', 'GHBC-REQ-015812', 833, '716e40887f2ce220b6ff084de3cb6f19ce7283af373548f4d8b7fa39c1e208bc', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-9f570ce3b99a55e4', NULL, NULL, 'threshold', 22, 'GS 1207:2018 Part 22 (Clause 22.12.5): “…Combustible materials shall not be placed within ______ or the distance of the allowed reduction method from the outside surface of a masonry heater in accordance with the Ghana fire Code, Clause 12.6, and the required……” — what value is stated?', '["54 in","72 in","36 in","18 in"]', 2, 'Clause 22.12.5 (GHBC-C-004157, page 833): Combustible materials shall not be placed within 914 mm (36 inches) or the distance of the allowed reduction method from the outside surface of a masonry heater in accordance with the Ghana fire Code, Clause 12.6, and the required space between the heater and combustible material shall be fully vented to permit the free flow of air around all heater surfaces.', 'study', 'GHBC-C-004157', 'GHBC-REQ-015812', 833, '716e40887f2ce220b6ff084de3cb6f19ce7283af373548f4d8b7fa39c1e208bc', 'requires_review', 0);
INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('q-cae5e6f244f97973', NULL, NULL, 'threshold', 22, 'GS 1207:2018 Part 22 (Clause 22.12.5): “…Where the masonry heater wall thickness is not less than ______ of solid masonry and the wall thickness of the heat exchange channels is not less than ______ of solid masonry, combustible materials shall not be placed……” — what value is stated?', '["203 mm","102 mm","304.8 mm","406 mm"]', 0, 'Clause 22.12.5 (GHBC-C-004157, page 833): Where the masonry heater wall thickness is not less than 203 mm (8 inches) of solid masonry and the wall thickness of the heat exchange channels is not less than 127 mm (5 inches) of solid masonry, combustible materials shall not be placed within 102 mm (4 inches) of the outside surface of a masonry heater.', 'study', 'GHBC-C-004157', 'GHBC-REQ-015814', 833, '19bdd1257d87b7493552939697b42fa09f1ec308b4306b30ea3cb1ead9a0d196', 'requires_review', 0);
