INSERT OR REPLACE INTO academy_questions (id, course_id, lesson_id, kind, part_no, prompt, options_json, correct_index, explanation, difficulty, clause_id, requirement_id, page, content_hash, verification_status, is_exam_eligible) VALUES ('qdef-6c3979b274d9dc36', NULL, NULL, 'definition', 2, 'Which term is defined as: "that is equal to or less than 20°C (68°F) and a boiling point that is greater than 20°C (68°F) at 14.7 pounds per square inch absolute (psia) (101 kPa). When not otherwise identified, the term ―liquid‖ includes both flammable and combustibl"', '["LABEL","LABORATORY","LABORATORY SUITE","LIQUID"]', 3, 'Part 2 (LIQUID, page 146): that is equal to or less than 20°C (68°F) and a boiling point that is greater than 20°C (68°F) at 14.7 pounds per square inch absolute (psia) (101 kPa). When not otherwise identified, the term ―liquid‖ includes both flammable and combustible liquids.', 'standard', 'LIQUID', NULL, 146, 'dbee9a4da011bc9a6ba85ced6869ad0792de10a3107eb98c97781c563198612d', 'extracted', 1);
